insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (186, 17, 1, 8, 'سورة الإسراء ١ – ٨', 'الإسراء من المسجد الحرام إلى المسجد الأقصى، وإفساد بني إسرائيل في الأرض مرتين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 186) = $j$[{"lbl": "الآية ١", "q": "سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلٗا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِي بَٰرَكۡنَا حَوۡلَهُۥ لِنُرِيَهُۥ مِنۡ ءَايَٰتِنَآۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ ﴿١﴾", "w": [["سبحان", "تنزّه وتقدّس عن كل ما لا يليق بجلاله وكماله."], ["بعبده", "بعبده ورسوله محمد ﷺ."], ["من المسجد الحرام", "الذي بمكة."], ["إلى المسجد الأقصى", "الذي ببيت المقدس."], ["من آياتنا", "من عجائب قدرتنا ومظاهرها في الملكوت الأعلى."]], "m": "سبحان الذي أسرى بعبده محمد ﷺ ليلاً من المسجد الحرام بمكة، إذ أُخرج من بيت أم هانئ وغُسل قلبه بماء زمزم وحُشي إيماناً وحكمة، ثم أُسري به إلى المسجد الأقصى ببيت المقدس، فجمع الله له الأنبياء فصلّى بهم إماماً، فكان إمام الأنبياء وخاتمهم، ثم عُرج به إلى السماء سماءً بعد سماء، حتى انتهى إلى سدرة المنتهى عندها جنة المأوى، ثم إلى مستوى سمع فيه صريف الأقلام. الذي باركنا حوله بالأشجار والأنهار والثمار، أما داخله فالبركة الدينية بمضاعفة أجر الصلاة فيه. لنريه من آياتنا: علّة الإسراء والمعراج، أن يريه من عجائب صنعه في الملكوت الأعلى، فيكون ما علمه بالوحي قد علمه بالرؤية والمشاهدة. إنه هو السميع لأقوال عباده، البصير بأعمالهم وأحوالهم، فاقتضت حكمته هذا الإسراء العجيب ليزداد الذين آمنوا إيماناً، ويزداد المرتابون كفراً وعناداً.", "h": ["تقرير عقيدة الإسراء والمعراج بالنبي ﷺ بالروح والجسد معاً، من المسجد الحرام إلى المسجد الأقصى، ثم إلى السماوات العلى، وفرض الله عليه وعلى أمته الصلوات الخمس.", "شرف المساجد الثلاثة: المسجد الحرام ومسجد النبي ﷺ والمسجد الأقصى؛ فالحرام والأقصى ذُكرا بالنص، ومسجد الرسول ﷺ بالإشارة، إذ الأقصى يقتضي قصياً، فالقصي هو المسجد النبوي.", "بيان الحكمة في الإسراء والمعراج، وهي أن يرى الرسول ﷺ بعيني رأسه ما آمن به وعلمه من طريق الوحي، فأصبح الغيب لديه شهادة."], "k": "«لنريه من آياتنا»… رأى ﷺ ما آمن به بعينه؛ فهل يملأ يقيني بالغيب قلبي كأني أراه؟"}, {"lbl": "الآيات ٢ – ٦", "q": "وَءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَجَعَلۡنَٰهُ هُدٗى لِّبَنِيٓ إِسۡرَـٰٓءِيلَ أَلَّا تَتَّخِذُواْ مِن دُونِي وَكِيلٗا ﴿٢﴾ ذُرِّيَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍۚ إِنَّهُۥ كَانَ عَبۡدٗا شَكُورٗا ﴿٣﴾ وَقَضَيۡنَآ إِلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ فِي ٱلۡكِتَٰبِ لَتُفۡسِدُنَّ فِي ٱلۡأَرۡضِ مَرَّتَيۡنِ وَلَتَعۡلُنَّ عُلُوّٗا كَبِيرٗا ﴿٤﴾ فَإِذَا جَآءَ وَعۡدُ أُولَىٰهُمَا بَعَثۡنَا عَلَيۡكُمۡ عِبَادٗا لَّنَآ أُوْلِي بَأۡسٖ شَدِيدٖ فَجَاسُواْ خِلَٰلَ ٱلدِّيَارِۚ وَكَانَ وَعۡدٗا مَّفۡعُولٗا ﴿٥﴾ ثُمَّ رَدَدۡنَا لَكُمُ ٱلۡكَرَّةَ عَلَيۡهِمۡ وَأَمۡدَدۡنَٰكُم بِأَمۡوَٰلٖ وَبَنِينَ وَجَعَلۡنَٰكُمۡ أَكۡثَرَ نَفِيرًا ﴿٦﴾", "w": [["وآتينا موسى الكتاب", "التوراة."], ["وجعلناه هدى", "جعلنا الكتاب هادياً لبني إسرائيل."], ["وكيلاً", "حفيظاً أو شريكاً."], ["من حملنا", "أي في السفينة مع نوح."], ["وقضينا", "أعلمناهم قضاءنا فيهم."], ["علواً كبيراً", "بغياً عظيماً."], ["أولاهما", "أولى المرّتين."], ["فجاسوا خلال الديار", "تردّدوا جائين ذاهبين وسط الديار يقتلون ويفسدون."], ["وعداً مفعولاً", "منجزاً لم يتخلّف."]], "m": "يخبر تعالى أنه الذي أسرى بعبده، وأنه آتى موسى التوراة، فهو المتفضّل على محمد ﷺ وأمته بالإسراء والمعراج، وعلى بني إسرائيل بالكتاب، وجعله هدى لهم لئلا يتخذوا من دونه حفيظاً يتوكّلون عليه ويفوّضون إليه أمرهم. يا ذرية من حملنا مع نوح: اشكروني كما شكرني نوح على إنجائه في السفينة، إنه كان عبداً شكوراً، فكونوا مثله فوحّدوني ولا تتركوا طاعتي. وأعلمنا بني إسرائيل في التوراة أنهم سيفسدون في الأرض مرتين بالمعاصي، ويعلون بالجرأة على الله وظلم الناس علواً عظيماً. فإذا جاء وقت المرة الأولى بعثنا عليهم عباداً لنا ذوي قوة وبطش في الحرب شديد، لما أفسدوا وانتهكوا حدود الشرع حتى قتلوا نبيّهم، فجاسوا خلال الديار قتلاً وإفساداً، وكان ذلك وعداً منجزاً. ثم بعد سنين طويلة من الاضطهاد والتشريد طلبوا ملكاً يقودهم إلى الجهاد، فقتل داود جالوت، وذلك معنى: ثم رددنا لكم الكرّة عليهم، وأمددناكم بأموال وبنين وجعلناكم أكثر رجالاً في الحروب، فقامت لهم دولة على عهد داود وسليمان ﵉.", "h": ["بيان إفضال الله تعالى على الأمتين الإسلامية والإسرائيلية.", "بيان سرّ إنزال الكتب، وهو هداية الناس إلى عبادة الله تعالى وتوحيده فيها.", "وجوب شكر الله تعالى على نعمه؛ إذ كان نوح ﵇ إذا أكل الأكلة قال: الحمد لله، وإذا شرب الشربة قال: الحمد لله، وإذا لبس حذاءه قال: الحمد لله، وإذا قضى حاجة قال: الحمد لله، فسُمّي عبداً شكوراً.", "ما قضاه الله تعالى كائن، وما وعد به ناجز، والإيمان بذلك واجب.", "التنديد بالإفساد والظلم والعلو في الأرض، وبيان سوء عاقبتها."], "k": "«إنه كان عبداً شكوراً»… لقمة وشربة ونعل وحاجة؛ أي حمد أقوله اليوم في كل واحدة منها؟"}, {"lbl": "الآيتان ٧ – ٨", "q": "إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ لِيَسُـُٔواْ وُجُوهَكُمۡ وَلِيَدۡخُلُواْ ٱلۡمَسۡجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٖ وَلِيُتَبِّرُواْ مَا عَلَوۡاْ تَتۡبِيرًا ﴿٧﴾ عَسَىٰ رَبُّكُمۡ أَن يَرۡحَمَكُمۡۚ وَإِنۡ عُدتُّمۡ عُدۡنَاۚ وَجَعَلۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ حَصِيرًا ﴿٨﴾", "w": [["إن أحسنتم", "طاعة الله ورسوله بالإخلاص فيها وأدائها على الوجه المشروع."], ["أحسنتم لأنفسكم", "الأجر والجزاء الحسن يعود عليكم لا على غيركم."], ["وإن أسأتم", "في الطاعة فإلى أنفسكم سوء عاقبة الإساءة."], ["وعد الآخرة", "المرة الآخرة المقابلة للأولى."], ["ليسوءوا وجوهكم", "يقبّحوها بالكرب واسوداد الحزن والذل."], ["وليدخلوا المسجد", "بيت المقدس."], ["وليتبّروا ما علوا تتبيراً", "ليدمّروا ما غلبوا عليه من ديار بني إسرائيل تدميراً."], ["وإن عدتم عدنا", "إن رجعتم إلى الفساد والمعاصي عدنا بالتسليط عليكم."], ["حصيراً", "محبساً وسجناً."]], "m": "ما زال السياق في بني إسرائيل: لما رجعوا إلى الله بتطبيق كتابه رُدّت لهم الكرّة، وقال لهم: إن أحسنتم باتباع الحق والتزام الطاعة فلأنفسكم، وإن أسأتم بتعطيل الشريعة والانغماس في الملاذ والشهوات فنتائج ذلك عائدة عليكم. فإذا جاء وقت المرة الآخرة بعث عليهم عباداً له، بختنصّر وجنوده، ليسوءوا وجوههم بما يصيبونهم به من الهم والذل، وليدخلوا بيت المقدس كما دخلوه أول مرة، وليدمّروا ما غلبوا عليه تدميراً كاملاً، وحصل لهم هذا لما قتلوا زكريا ويحيى ﵉ وكثيراً من العلماء، وظهر فيهم الفسق وفي نسائهم التبرّج والفجور. عسى ربكم أن يرحمكم: خير عظيم لو طلبوه بصدق لفازوا به، ولكنهم أعرضوا. وإن عدتم إلى الفسق عدنا بتسليط من نشاء عليكم، فأنجز الله ما وعد، فسلّط عليهم رسوله ﷺ والمؤمنين فأجلى بني قينقاع وبني النضير وقتل بني قريظة. وإن كان عذاب الدنيا تسليطاً وأسراً وتشريداً، فعذاب الآخرة حبس في جهنم لا يخرج منه الكافرون، الذين يكفرون شرائع الله ونعمه.", "h": ["صدق وعد الله تعالى.", "تقرير نبوة النبي ﷺ، إذ مثل هذه الأنباء لا يقصّها إلا نبي يوحى إليه.", "تقرير قاعدة «من عمل صالحاً فلنفسه ومن أساء فعليها».", "وجوب الرجاء في الله، وهو انتظار الفرج والخير منه وإن طال الزمن.", "قد يجمع الله تعالى للكافرين بين عذاب الدنيا وعذاب الآخرة، وكذا الفاسقون من المؤمنين."], "k": "«إن أحسنتم أحسنتم لأنفسكم»… كل إحسان أقدّمه يعود إليّ؛ فما الإحسان الذي أؤجّله؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 186;
insert into public.tdb_cards(topic, i, body) select 186, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآية ١", "q": "سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلٗا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِي بَٰرَكۡنَا حَوۡلَهُۥ لِنُرِيَهُۥ مِنۡ ءَايَٰتِنَآۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ ﴿١﴾", "w": [["سبحان", "تنزّه وتقدّس عن كل ما لا يليق بجلاله وكماله."], ["بعبده", "بعبده ورسوله محمد ﷺ."], ["من المسجد الحرام", "الذي بمكة."], ["إلى المسجد الأقصى", "الذي ببيت المقدس."], ["من آياتنا", "من عجائب قدرتنا ومظاهرها في الملكوت الأعلى."]], "m": "سبحان الذي أسرى بعبده محمد ﷺ ليلاً من المسجد الحرام بمكة، إذ أُخرج من بيت أم هانئ وغُسل قلبه بماء زمزم وحُشي إيماناً وحكمة، ثم أُسري به إلى المسجد الأقصى ببيت المقدس، فجمع الله له الأنبياء فصلّى بهم إماماً، فكان إمام الأنبياء وخاتمهم، ثم عُرج به إلى السماء سماءً بعد سماء، حتى انتهى إلى سدرة المنتهى عندها جنة المأوى، ثم إلى مستوى سمع فيه صريف الأقلام. الذي باركنا حوله بالأشجار والأنهار والثمار، أما داخله فالبركة الدينية بمضاعفة أجر الصلاة فيه. لنريه من آياتنا: علّة الإسراء والمعراج، أن يريه من عجائب صنعه في الملكوت الأعلى، فيكون ما علمه بالوحي قد علمه بالرؤية والمشاهدة. إنه هو السميع لأقوال عباده، البصير بأعمالهم وأحوالهم، فاقتضت حكمته هذا الإسراء العجيب ليزداد الذين آمنوا إيماناً، ويزداد المرتابون كفراً وعناداً.", "h": ["تقرير عقيدة الإسراء والمعراج بالنبي ﷺ بالروح والجسد معاً، من المسجد الحرام إلى المسجد الأقصى، ثم إلى السماوات العلى، وفرض الله عليه وعلى أمته الصلوات الخمس.", "شرف المساجد الثلاثة: المسجد الحرام ومسجد النبي ﷺ والمسجد الأقصى؛ فالحرام والأقصى ذُكرا بالنص، ومسجد الرسول ﷺ بالإشارة، إذ الأقصى يقتضي قصياً، فالقصي هو المسجد النبوي.", "بيان الحكمة في الإسراء والمعراج، وهي أن يرى الرسول ﷺ بعيني رأسه ما آمن به وعلمه من طريق الوحي، فأصبح الغيب لديه شهادة."], "k": "«لنريه من آياتنا»… رأى ﷺ ما آمن به بعينه؛ فهل يملأ يقيني بالغيب قلبي كأني أراه؟"}, {"lbl": "الآيات ٢ – ٦", "q": "وَءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَجَعَلۡنَٰهُ هُدٗى لِّبَنِيٓ إِسۡرَـٰٓءِيلَ أَلَّا تَتَّخِذُواْ مِن دُونِي وَكِيلٗا ﴿٢﴾ ذُرِّيَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍۚ إِنَّهُۥ كَانَ عَبۡدٗا شَكُورٗا ﴿٣﴾ وَقَضَيۡنَآ إِلَىٰ بَنِيٓ إِسۡرَـٰٓءِيلَ فِي ٱلۡكِتَٰبِ لَتُفۡسِدُنَّ فِي ٱلۡأَرۡضِ مَرَّتَيۡنِ وَلَتَعۡلُنَّ عُلُوّٗا كَبِيرٗا ﴿٤﴾ فَإِذَا جَآءَ وَعۡدُ أُولَىٰهُمَا بَعَثۡنَا عَلَيۡكُمۡ عِبَادٗا لَّنَآ أُوْلِي بَأۡسٖ شَدِيدٖ فَجَاسُواْ خِلَٰلَ ٱلدِّيَارِۚ وَكَانَ وَعۡدٗا مَّفۡعُولٗا ﴿٥﴾ ثُمَّ رَدَدۡنَا لَكُمُ ٱلۡكَرَّةَ عَلَيۡهِمۡ وَأَمۡدَدۡنَٰكُم بِأَمۡوَٰلٖ وَبَنِينَ وَجَعَلۡنَٰكُمۡ أَكۡثَرَ نَفِيرًا ﴿٦﴾", "w": [["وآتينا موسى الكتاب", "التوراة."], ["وجعلناه هدى", "جعلنا الكتاب هادياً لبني إسرائيل."], ["وكيلاً", "حفيظاً أو شريكاً."], ["من حملنا", "أي في السفينة مع نوح."], ["وقضينا", "أعلمناهم قضاءنا فيهم."], ["علواً كبيراً", "بغياً عظيماً."], ["أولاهما", "أولى المرّتين."], ["فجاسوا خلال الديار", "تردّدوا جائين ذاهبين وسط الديار يقتلون ويفسدون."], ["وعداً مفعولاً", "منجزاً لم يتخلّف."]], "m": "يخبر تعالى أنه الذي أسرى بعبده، وأنه آتى موسى التوراة، فهو المتفضّل على محمد ﷺ وأمته بالإسراء والمعراج، وعلى بني إسرائيل بالكتاب، وجعله هدى لهم لئلا يتخذوا من دونه حفيظاً يتوكّلون عليه ويفوّضون إليه أمرهم. يا ذرية من حملنا مع نوح: اشكروني كما شكرني نوح على إنجائه في السفينة، إنه كان عبداً شكوراً، فكونوا مثله فوحّدوني ولا تتركوا طاعتي. وأعلمنا بني إسرائيل في التوراة أنهم سيفسدون في الأرض مرتين بالمعاصي، ويعلون بالجرأة على الله وظلم الناس علواً عظيماً. فإذا جاء وقت المرة الأولى بعثنا عليهم عباداً لنا ذوي قوة وبطش في الحرب شديد، لما أفسدوا وانتهكوا حدود الشرع حتى قتلوا نبيّهم، فجاسوا خلال الديار قتلاً وإفساداً، وكان ذلك وعداً منجزاً. ثم بعد سنين طويلة من الاضطهاد والتشريد طلبوا ملكاً يقودهم إلى الجهاد، فقتل داود جالوت، وذلك معنى: ثم رددنا لكم الكرّة عليهم، وأمددناكم بأموال وبنين وجعلناكم أكثر رجالاً في الحروب، فقامت لهم دولة على عهد داود وسليمان ﵉.", "h": ["بيان إفضال الله تعالى على الأمتين الإسلامية والإسرائيلية.", "بيان سرّ إنزال الكتب، وهو هداية الناس إلى عبادة الله تعالى وتوحيده فيها.", "وجوب شكر الله تعالى على نعمه؛ إذ كان نوح ﵇ إذا أكل الأكلة قال: الحمد لله، وإذا شرب الشربة قال: الحمد لله، وإذا لبس حذاءه قال: الحمد لله، وإذا قضى حاجة قال: الحمد لله، فسُمّي عبداً شكوراً.", "ما قضاه الله تعالى كائن، وما وعد به ناجز، والإيمان بذلك واجب.", "التنديد بالإفساد والظلم والعلو في الأرض، وبيان سوء عاقبتها."], "k": "«إنه كان عبداً شكوراً»… لقمة وشربة ونعل وحاجة؛ أي حمد أقوله اليوم في كل واحدة منها؟"}, {"lbl": "الآيتان ٧ – ٨", "q": "إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ لِيَسُـُٔواْ وُجُوهَكُمۡ وَلِيَدۡخُلُواْ ٱلۡمَسۡجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةٖ وَلِيُتَبِّرُواْ مَا عَلَوۡاْ تَتۡبِيرًا ﴿٧﴾ عَسَىٰ رَبُّكُمۡ أَن يَرۡحَمَكُمۡۚ وَإِنۡ عُدتُّمۡ عُدۡنَاۚ وَجَعَلۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ حَصِيرًا ﴿٨﴾", "w": [["إن أحسنتم", "طاعة الله ورسوله بالإخلاص فيها وأدائها على الوجه المشروع."], ["أحسنتم لأنفسكم", "الأجر والجزاء الحسن يعود عليكم لا على غيركم."], ["وإن أسأتم", "في الطاعة فإلى أنفسكم سوء عاقبة الإساءة."], ["وعد الآخرة", "المرة الآخرة المقابلة للأولى."], ["ليسوءوا وجوهكم", "يقبّحوها بالكرب واسوداد الحزن والذل."], ["وليدخلوا المسجد", "بيت المقدس."], ["وليتبّروا ما علوا تتبيراً", "ليدمّروا ما غلبوا عليه من ديار بني إسرائيل تدميراً."], ["وإن عدتم عدنا", "إن رجعتم إلى الفساد والمعاصي عدنا بالتسليط عليكم."], ["حصيراً", "محبساً وسجناً."]], "m": "ما زال السياق في بني إسرائيل: لما رجعوا إلى الله بتطبيق كتابه رُدّت لهم الكرّة، وقال لهم: إن أحسنتم باتباع الحق والتزام الطاعة فلأنفسكم، وإن أسأتم بتعطيل الشريعة والانغماس في الملاذ والشهوات فنتائج ذلك عائدة عليكم. فإذا جاء وقت المرة الآخرة بعث عليهم عباداً له، بختنصّر وجنوده، ليسوءوا وجوههم بما يصيبونهم به من الهم والذل، وليدخلوا بيت المقدس كما دخلوه أول مرة، وليدمّروا ما غلبوا عليه تدميراً كاملاً، وحصل لهم هذا لما قتلوا زكريا ويحيى ﵉ وكثيراً من العلماء، وظهر فيهم الفسق وفي نسائهم التبرّج والفجور. عسى ربكم أن يرحمكم: خير عظيم لو طلبوه بصدق لفازوا به، ولكنهم أعرضوا. وإن عدتم إلى الفسق عدنا بتسليط من نشاء عليكم، فأنجز الله ما وعد، فسلّط عليهم رسوله ﷺ والمؤمنين فأجلى بني قينقاع وبني النضير وقتل بني قريظة. وإن كان عذاب الدنيا تسليطاً وأسراً وتشريداً، فعذاب الآخرة حبس في جهنم لا يخرج منه الكافرون، الذين يكفرون شرائع الله ونعمه.", "h": ["صدق وعد الله تعالى.", "تقرير نبوة النبي ﷺ، إذ مثل هذه الأنباء لا يقصّها إلا نبي يوحى إليه.", "تقرير قاعدة «من عمل صالحاً فلنفسه ومن أساء فعليها».", "وجوب الرجاء في الله، وهو انتظار الفرج والخير منه وإن طال الزمن.", "قد يجمع الله تعالى للكافرين بين عذاب الدنيا وعذاب الآخرة، وكذا الفاسقون من المؤمنين."], "k": "«إن أحسنتم أحسنتم لأنفسكم»… كل إحسان أقدّمه يعود إليّ؛ فما الإحسان الذي أؤجّله؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (187, 17, 9, 17, 'سورة الإسراء ٩ – ١٧', '«إن هذا القرآن يهدي للتي هي أقوم»، و«وكل إنسان ألزمناه طائره في عنقه»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 187) = $j$[{"lbl": "الآيات ٩ – ١٢", "q": "إِنَّ هَٰذَا ٱلۡقُرۡءَانَ يَهۡدِي لِلَّتِي هِيَ أَقۡوَمُ وَيُبَشِّرُ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّـٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرٗا كَبِيرٗا ﴿٩﴾ وَأَنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمٗا ﴿١٠﴾ وَيَدۡعُ ٱلۡإِنسَٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلۡخَيۡرِۖ وَكَانَ ٱلۡإِنسَٰنُ عَجُولٗا ﴿١١﴾ وَجَعَلۡنَا ٱلَّيۡلَ وَٱلنَّهَارَ ءَايَتَيۡنِۖ فَمَحَوۡنَآ ءَايَةَ ٱلَّيۡلِ وَجَعَلۡنَآ ءَايَةَ ٱلنَّهَارِ مُبۡصِرَةٗ لِّتَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡ وَلِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ وَكُلَّ شَيۡءٖ فَصَّلۡنَٰهُ تَفۡصِيلٗا ﴿١٢﴾", "w": [["للتي هي أقوم", "للطريقة التي هي أعدل وأصوب."], ["أن لهم أجراً كبيراً", "إنه الجنة دار السلام."], ["أعتدنا لهم عذاباً أليماً", "إنه عذاب النار يوم القيامة."], ["ويدع الإنسان بالشر", "على نفسه وأهله إذا هو ضجر وغضب."], ["وكان الإنسان عجولاً", "سريع التأثر بما يخطر على باله فلا يتروّى ولا يتأمل."], ["آيتين", "علامتين دالتين على وجود الله وقدرته وعلمه ورحمته."], ["فمحونا آية الليل", "طمسنا نورها بالظلام الذي يعقب غياب الشمس."], ["مبصرة", "يبصر الإنسان بسبب ضوء النهار فيها."], ["عدد السنين والحساب", "عدد السنين وانقضاءها، وحساب ساعات النهار والليل والأيام والأسابيع والشهور."]], "m": "يخبر تعالى أن هذا القرآن يهدي بما فيه من الدلائل والشرائع والمواعظ للطريقة التي هي أعدل وأقصد، الإسلام، سبيل السعادة والكمال في الدارين، ويبشّر الذين آمنوا وعملوا الصالحات بأن لهم الجنة، ويخبر أن الذين لا يؤمنون بالآخرة أعدّ لهم عذاباً أليماً في جهنم. ويخبر عن ضعف الإنسان وقلة إدراكه للعواقب: إذا ضجر أو غضب دعا على نفسه وأهله بالشر كدعائه بالخير، غير مفكّر لو استجيب له، وكان كثير العجلة، هذا طبعه ما لم يتأدّب بآداب القرآن، فإن استقام عليه أصبح ذا تؤدة وحلم وصبر وأناة. وجعلنا الليل والنهار علامتين على وجودنا وقدرتنا، فطمسنا نور الليل، وجعلنا النهار مضيئاً لتطلبوا رزقكم بالسعي فيه، ولتعلموا عدد السنين والحساب لتوقّف مصالحكم الدينية والدنيوية عليه، وكل شيء يحتاج إليه الإنسان في كماله وسعادته بيّنّاه في هذا الكتاب تبييناً.", "h": ["بيان فضل القرآن الكريم بهدايته إلى الإسلام الذي هو سبيل السعادة للإنسان.", "الوعد والوعيد: بشارة المؤمنين العاملين للصالحات، ونذارة الكافرين باليوم الآخر.", "بيان طبع الإنسان قبل تهذيبه بالآداب القرآنية والأخلاق النبوية.", "الليل والنهار آيتان تدلان على الله تعالى وتقرّران علمه وقدرته وتدبيره.", "مشروعية علم الحساب وتعلّمه."], "k": "«ويدع الإنسان بالشر دعاءه بالخير»… في ساعة الغضب، هل أمسك لساني عن الدعاء على نفسي وأهلي؟"}, {"lbl": "الآيات ١٣ – ١٧", "q": "وَكُلَّ إِنسَٰنٍ أَلۡزَمۡنَٰهُ طَـٰٓئِرَهُۥ فِي عُنُقِهِۦۖ وَنُخۡرِجُ لَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ كِتَٰبٗا يَلۡقَىٰهُ مَنشُورًا ﴿١٣﴾ ٱقۡرَأۡ كِتَٰبَكَ كَفَىٰ بِنَفۡسِكَ ٱلۡيَوۡمَ عَلَيۡكَ حَسِيبٗا ﴿١٤﴾ مَّنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۗ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبۡعَثَ رَسُولٗا ﴿١٥﴾ وَإِذَآ أَرَدۡنَآ أَن نُّهۡلِكَ قَرۡيَةً أَمَرۡنَا مُتۡرَفِيهَا فَفَسَقُواْ فِيهَا فَحَقَّ عَلَيۡهَا ٱلۡقَوۡلُ فَدَمَّرۡنَٰهَا تَدۡمِيرٗا ﴿١٦﴾ وَكَمۡ أَهۡلَكۡنَا مِنَ ٱلۡقُرُونِ مِنۢ بَعۡدِ نُوحٖۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرَۢا بَصِيرٗا ﴿١٧﴾", "w": [["طائره", "عمله وما قُدّر له من سعادة وشقاء."], ["في عنقه", "ملازم له لا يفارقه حتى يفرغ منه."], ["ولا تزر وازرة وزر أخرى", "لا تحمل نفس آثمة إثم نفس أخرى."], ["مترفيها", "منعّميها من أغنياء ورؤساء."], ["فحقّ عليها القول", "وجب عليها العذاب."], ["وكم أهلكنا", "أهلكنا كثيراً."], ["من القرون", "من أهل القرون السابقة."], ["خبيراً بصيراً", "عليماً بصيراً بذنوب العباد."]], "m": "يخبر تعالى أنه ألزم كل إنسان ما قضى به له من عمل، وما يترتّب عليه من سعادة أو شقاء، فلا يتخلّف عنه حتى كأنه مربوط بعنقه، ويخرج له يوم القيامة كتاب عمله يلقاه منشوراً أمامه، ويقال له: اقرأ كتابك، كفى بنفسك اليوم عليك حسيباً. فمن اهتدى فآمن وعمل صالحاً وتخلّى عن الشرك والمعاصي فإنما عائد ذلك له، ومن ضلّ فإنما يشقى به هو، ولا تحمل يوم القيامة نفس آثمة إثم نفس أخرى. وما كان من شأن الله، وهو العدل الرحيم، أن يهلك أمة بعذاب استئصال قبل أن يبعث فيها رسولاً يعرّفها بربها ومحابّه ومساخطه. وإذا أردنا أن نهلك أهل قرية أمرنا منعّميها من الأغنياء والرؤساء بطاعتنا وإقامة الشرع، فلم يستجيبوا، ففسقوا فيها، فوجب عليها العذاب، فدمّرناها تدميراً. وكم أهلكنا من الأمم من بعد نوح كعاد وثمود وقوم لوط وآل فرعون، وكفى بربك بذنوب عباده خبيراً بصيراً، وفيه وعيد شديد؛ فإنه تعالى يمهل لعل القوم يستفيقون، فإذا استمرّوا بعد الإعذار أخذهم أخذ عزيز مقتدر.", "h": ["تقرير عقيدة القضاء والقدر.", "تقرير عقيدة البعث والجزاء.", "تقرير العدالة الإلهية يوم القيامة، فلا تُظلم نفس شيئاً.", "بيان سنة الله تعالى في إهلاك الأمم، وأنها لا تهلك إلا بعد الإنذار والإعذار إليها.", "التحذير من كثرة التنعّم والترف، فإنه يؤدّي إلى الفسق بترك الطاعة، ثم يؤدّي الفسق إلى الهلاك."], "k": "«اقرأ كتابك كفى بنفسك اليوم عليك حسيباً»… ماذا كُتب في صفحة يومي حتى الآن؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 187;
