ماله وسعادته بيّنّاه في هذا الكتاب تبييناً.", "h": ["بيان فضل القرآن الكريم بهدايته إلى الإسلام الذي هو سبيل السعادة للإنسان.", "الوعد والوعيد: بشارة المؤمنين العاملين للصالحات، ونذارة الكافرين باليوم الآخر.", "بيان طبع الإنسان قبل تهذيبه بالآداب القرآنية والأخلاق النبوية.", "الليل والنهار آيتان تدلان على الله تعالى وتقرّران علمه وقدرته وتدبيره.", "مشروعية علم الحساب وتعلّمه."], "k": "«ويدع الإنسان بالشر دعاءه بالخير»… في ساعة الغضب، هل أمسك لساني عن الدعاء على نفسي وأهلي؟"}, {"lbl": "الآيات ١٣ – ١٧", "q": "وَكُلَّ إِنسَٰنٍ أَلۡزَمۡنَٰهُ طَـٰٓئِرَهُۥ فِي عُنُقِهِۦۖ وَنُخۡرِجُ لَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ كِتَٰبٗا يَلۡقَىٰهُ مَنشُورًا ﴿١٣﴾ ٱقۡرَأۡ كِتَٰبَكَ كَفَىٰ بِنَفۡسِكَ ٱلۡيَوۡمَ عَلَيۡكَ حَسِيبٗا ﴿١٤﴾ مَّنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةٞ وِزۡرَ أُخۡرَىٰۗ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبۡعَثَ رَسُولٗا ﴿١٥﴾ وَإِذَآ أَرَدۡنَآ أَن نُّهۡلِكَ قَرۡيَةً أَمَرۡنَا مُتۡرَفِيهَا فَفَسَقُواْ فِيهَا فَحَقَّ عَلَيۡهَا ٱلۡقَوۡلُ فَدَمَّرۡنَٰهَا تَدۡمِيرٗا ﴿١٦﴾ وَكَمۡ أَهۡلَكۡنَا مِنَ ٱلۡقُرُونِ مِنۢ بَعۡدِ نُوحٖۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرَۢا بَصِيرٗا ﴿١٧﴾", "w": [["طائره", "عمله وما قُدّر له من سعادة وشقاء."], ["في عنقه", "ملازم له لا يفارقه حتى يفرغ منه."], ["ولا تزر وازرة وزر أخرى", "لا تحمل نفس آثمة إثم نفس أخرى."], ["مترفيها", "منعّميها من أغنياء ورؤساء."], ["فحقّ عليها القول", "وجب عليها العذاب."], ["وكم أهلكنا", "أهلكنا كثيراً."], ["من القرون", "من أهل القرون السابقة."], ["خبيراً بصيراً", "عليماً بصيراً بذنوب العباد."]], "m": "يخبر تعالى أنه ألزم كل إنسان ما قضى به له من عمل، وما يترتّب عليه من سعادة أو شقاء، فلا يتخلّف عنه حتى كأنه مربوط بعنقه، ويخرج له يوم القيامة كتاب عمله يلقاه منشوراً أمامه، ويقال له: اقرأ كتابك، كفى بنفسك اليوم عليك حسيباً. فمن اهتدى فآمن وعمل صالحاً وتخلّى عن الشرك والمعاصي فإنما عائد ذلك له، ومن ضلّ فإنما يشقى به هو، ولا تحمل يوم القيامة نفس آثمة إثم نفس أخرى. وما كان من شأن الله، وهو العدل الرحيم، أن يهلك أمة بعذاب استئصال قبل أن يبعث فيها رسولاً يعرّفها بربها ومحابّه ومساخطه. وإذا أردنا أن نهلك أهل قرية أمرنا منعّميها من الأغنياء والرؤساء بطاعتنا وإقامة الشرع، فلم يستجيبوا، ففسقوا فيها، فوجب عليها العذاب، فدمّرناها تدميراً. وكم أهلكنا من الأمم من بعد نوح كعاد وثمود وقوم لوط وآل فرعون، وكفى بربك بذنوب عباده خبيراً بصيراً، وفيه وعيد شديد؛ فإنه تعالى يمهل لعل القوم يستفيقون، فإذا استمرّوا بعد الإعذار أخذهم أخذ عزيز مقتدر.", "h": ["تقرير عقيدة القضاء والقدر.", "تقرير عقيدة البعث والجزاء.", "تقرير العدالة الإلهية يوم القيامة، فلا تُظلم نفس شيئاً.", "بيان سنة الله تعالى في إهلاك الأمم، وأنها لا تهلك إلا بعد الإنذار والإعذار إليها.", "التحذير من كثرة التنعّم والترف، فإنه يؤدّي إلى الفسق بترك الطاعة، ثم يؤدّي الفسق إلى الهلاك."], "k": "«اقرأ كتابك كفى بنفسك اليوم عليك حسيباً»… ماذا كُتب في صفحة يومي حتى الآن؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (188, 17, 18, 27, 'سورة الإسراء ١٨ – ٢٧', 'من أراد العاجلة ومن أراد الآخرة، و«وقضى ربك ألا تعبدوا إلا إياه وبالوالدين إحساناً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 188) = $j$[{"lbl": "الآيات ١٨ – ٢٢", "q": "مَّن كَانَ يُرِيدُ ٱلۡعَاجِلَةَ عَجَّلۡنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلۡنَا لَهُۥ جَهَنَّمَ يَصۡلَىٰهَا مَذۡمُومٗا مَّدۡحُورٗا ﴿١٨﴾ وَمَنۡ أَرَادَ ٱلۡأٓخِرَةَ وَسَعَىٰ لَهَا سَعۡيَهَا وَهُوَ مُؤۡمِنٞ فَأُوْلَـٰٓئِكَ كَانَ سَعۡيُهُم مَّشۡكُورٗا ﴿١٩﴾ كُلّٗا نُّمِدُّ هَـٰٓؤُلَآءِ وَهَـٰٓؤُلَآءِ مِنۡ عَطَآءِ رَبِّكَۚ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحۡظُورًا ﴿٢٠﴾ ٱنظُرۡ كَيۡفَ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۚ وَلَلۡأٓخِرَةُ أَكۡبَرُ دَرَجَٰتٖ وَأَكۡبَرُ تَفۡضِيلٗا ﴿٢١﴾ لَّا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقۡعُدَ مَذۡمُومٗا مَّخۡذُولٗا ﴿٢٢﴾", "w": [["العاجلة", "الدنيا لسرعة انقضائها."], ["يصلاها مذموماً مدحوراً", "يدخلها ملوماً مبعداً من الجنة."], ["وسعى لها سعيها", "عمل لها العمل المطلوب لدخولها، وهو الإيمان والعمل الصالح."], ["كان سعيهم مشكوراً", "عملهم مقبولاً مثاباً عليه من قبل الله تعالى."], ["كلاً نمدّ هؤلاء وهؤلاء", "كل فريق من الفريقين نعطي."], ["وما كان عطاء ربك محظوراً", "لم يكن عطاء الله في الدنيا ممنوعاً عن أحد."], ["كيف فضّلنا بعضهم على بعض", "في الرزق والجاه."], ["لا تجعل مع الله إلهاً آخر", "لا تعبد مع الله غيره من سائر المعبودات الباطلة."], ["فتقعد مذموماً مخذولاً", "فتصير مذموماً من الملائكة والمؤمنين، مخذولاً من الله تعالى."]], "m": "من كان يريد الدنيا عجّلنا له فيها ما نشاء، لا ما يشاؤه العبد، لمن نريد، فالأمر كله لنا، ثم جعلنا له جهنم يدخلها ملوماً مطروداً من رحمتنا. ومن أراد سعادة الآخرة وعمل لها عملها اللائق بها، الإيمان الصحيح والعمل الصالح الموافق للشرع، واجتنب الشرك والمعاصي، وهو مؤمن، وهذا قيد في قبول العمل، فأولئك كان عملهم متقبّلاً يثابون عليه بالجنة ورضوان الله. وكلاً من مريدي الدنيا ومريدي الآخرة يمدّ الله من فضله الواسع، فالكل يأكل ويشرب ويكتسي بحسب ما قُدّر له، ومن أراد الله إعطاءه شيئاً لم يستطع أحد أن يحرمه منه. انظر كيف فضّلنا بعض الناس على بعض في الرزق والصحة والمال والذرية والجاه، فاعلم أن الآخرة أكبر درجات وأكبر تفضيلاً، وذلك عائد إلى فضل الله ثم إلى الكسب صلاحاً وفساداً. ولا تجعل مع الله إلهاً آخر تعبده، فتقعد ملوماً يلومك المؤمنون والملائكة، مخذولاً لا ناصر لك، والخطاب للرسول ﷺ والمراد به كل إنسان.", "h": ["كلا الدارين، السعادة فيها أو الشقاء، متوقّف على الكسب والعمل، وهذه سنة الله تعالى في العباد.", "سعي الدنيا التجارة والفلاحة والصناعة.", "سعي الآخرة الإيمان وصالح الأعمال والتخلّي عن الشرك والمعاصي.", "يعطي الله تعالى الدنيا من يحب ومن لا يحب، وعطاؤه قائم على سنن له في الحياة يجب معرفتها والعمل بمقتضاها لمن أراد الدنيا والآخرة.", "ما أعطاه الله لا يمنعه أحد، فوجب التوكل على الله والإعراض عما سواه.", "تحريم الشرك والوعيد عليه بالخلود في نار جهنم."], "k": "«وسعى لها سعيها وهو مؤمن»… كم من سعيي اليوم للعاجلة، وكم منه للآخرة؟"}, {"lbl": "الآيات ٢٣ – ٢٧", "q": "۞وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنًاۚ إِمَّا يَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَآ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفّٖ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلٗا كَرِيمٗا ﴿٢٣﴾ وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا ﴿٢٤﴾ رَّبُّكُمۡ أَعۡلَمُ بِمَا فِي نُفُوسِكُمۡۚ إِن تَكُونُواْ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلۡأَوَّـٰبِينَ غَفُورٗا ﴿٢٥﴾ وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَلَا تُبَذِّرۡ تَبۡذِيرًا ﴿٢٦﴾ إِنَّ ٱلۡمُبَذِّرِينَ كَانُوٓاْ إِخۡوَٰنَ ٱلشَّيَٰطِينِۖ وَكَانَ ٱلشَّيۡطَٰنُ لِرَبِّهِۦ كَفُورٗا ﴿٢٧﴾", "w": [["وقضى ربك", "أمر ووصّى."], ["وبالوالدين إحساناً", "وأن تحسنوا بالوالدين إحساناً ببرّهما."], ["فلا تقل لهما أفّ", "كلمة تضجّر."], ["ولا تنهرهما", "لا تزجرهما بالكلمة القاسية."], ["قولاً كريماً", "جميلاً ليّناً."], ["واخفض لهما جناح الذل", "ألن لهما جانبك وتواضع لهما."], ["للأوّابين", "الرجّاعين إلى الطاعة بعد المعصية."], ["وآت ذا القربى", "أعط أصحاب القرابات حقوقهم من البر والصلة."], ["ولا تبذّر تبذيراً", "لا تنفق المال في غير طاعة الله ورسوله."], ["لربه كفوراً", "كثير الكفر لنعم ربه، فكذلك المبذّر أخوه."]], "m": "لما حرّم الشرك أمر بالتوحيد: وحكم ربك ووصّى ألا تعبدوا إلا إياه، وأوصى بالوالدين إحساناً، بإيصال الخير إليهما وكفّ الأذى عنهما في غير معصية الله. إن بلغ الكبر عندك أحدهما أو كلاهما وأنت حي بينهما، وجب أن تخدمهما كما خدماك وأنت طفل، فتغسل بولهما وتطهّر نجاستهما وتقدّم لهما ما يحتاجان، ولا تتضجّر ولا تتأفّف كما لم يتضجّرا منك، ولا تزجرهما بالكلمة العالية، وقل لهما قولاً جميلاً ليّناً يشعران معه بالكرامة، وألن لهما جانبك وتعطّف عليهما، وادع لهما طوال حياتك بالمغفرة والرحمة إن كانا موحّدين، فقل: رب ارحمهما كما ربّياني صغيراً. ربكم أعلم بما في نفوسكم من الرضا عنهما أو السخط عليهما، وقد يضمر الإنسان مرة السوء أو تبدر منه البادرة وهو صالح مؤدٍّ للحقوق، فهو غفور له متى تاب. وآت ذا القربى حقه من البر والصلة، والمسكين بالإحسان إليه بالكساء أو الغذاء والكلمة الطيبة، وابن السبيل بالضيافة والمساعدة على سفره، ولا تنفق مالك في غير طاعة الله، إن المبذّرين في المعاصي كانوا إخوان الشياطين لأنهم فسقوا عن أمر ربهم، وكان الشيطان لربه كفوراً، فهل يرضى المسلم أن يكون شيطاناً؟", "h": ["وجوب عبادة الله تعالى وحده، ووجوب برّ الوالدين، وهو الإحسان بهما، وكفّ الأذى عنهما، وطاعتهما في المعروف.", "وجوب الدعاء للوالدين بالمغفرة والرحمة.", "وجوب مراقبة الله تعالى وعدم إضمار أي سوء في النفس.", "من كان صالحاً وبدرت منه البادرة وتاب منها فإن الله يغفر له ذلك.", "وجوب إعطاء ذوي القربى حقوقهم من البر والصلة، وكذا المساكين وابن السبيل.", "حرمة التبذير، وحقيقته إنفاق المال في المعاصي والمحرّمات."], "k": "«وقل رب ارحمهما كما ربياني صغيراً»… متى دعوت لوالديّ آخر مرة، وماذا أقدّم لهما اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 188;
insert into public.tdb_cards(topic, i, body) select 188, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٨ – ٢٢", "q": "مَّن كَانَ يُرِيدُ ٱلۡعَاجِلَةَ عَجَّلۡنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلۡنَا لَهُۥ جَهَنَّمَ يَصۡلَىٰهَا مَذۡمُومٗا مَّدۡحُورٗا ﴿١٨﴾ وَمَنۡ أَرَادَ ٱلۡأٓخِرَةَ وَسَعَىٰ لَهَا سَعۡيَهَا وَهُوَ مُؤۡمِنٞ فَأُوْلَـٰٓئِكَ كَانَ سَعۡيُهُم مَّشۡكُورٗا ﴿١٩﴾ كُلّٗا نُّمِدُّ هَـٰٓؤُلَآءِ وَهَـٰٓؤُلَآءِ مِنۡ عَطَآءِ رَبِّكَۚ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحۡظُورًا ﴿٢٠﴾ ٱنظُرۡ كَيۡفَ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۚ وَلَلۡأٓخِرَةُ أَكۡبَرُ دَرَجَٰتٖ وَأَكۡبَرُ تَفۡضِيلٗا ﴿٢١﴾ لَّا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقۡعُدَ مَذۡمُومٗا مَّخۡذُولٗا ﴿٢٢﴾", "w": [["العاجلة", "الدنيا لسرعة انقضائها."], ["يصلاها مذموماً مدحوراً", "يدخلها ملوماً مبعداً من الجنة."], ["وسعى لها سعيها", "عمل لها العمل المطلوب لدخولها، وهو الإيمان والعمل الصالح."], ["كان سعيهم مشكوراً", "عملهم مقبولاً مثاباً عليه من قبل الله تعالى."], ["كلاً نمدّ هؤلاء وهؤلاء", "كل فريق من الفريقين نعطي."], ["وما كان عطاء ربك محظوراً", "لم يكن عطاء الله في الدنيا ممنوعاً عن أحد."], ["كيف فضّلنا بعضهم على بعض", "في الرزق والجاه."], ["لا تجعل مع الله إلهاً آخر", "لا تعبد مع الله غيره من سائر المعبودات الباطلة."], ["فتقعد مذموماً مخذولاً", "فتصير مذموماً من الملائكة والمؤمنين، مخذولاً من الله تعالى."]], "m": "من كان يريد الدنيا عجّلنا له فيها ما نشاء، لا ما يشاؤه العبد، لمن نريد، فالأمر كله لنا، ثم جعلنا له جهنم يدخلها ملوماً مطروداً من رحمتنا. ومن أراد سعادة الآخرة وعمل لها عملها اللائق بها، الإيمان الصحيح والعمل الصالح الموافق للشرع، واجتنب الشرك والمعاصي، وهو مؤمن، وهذا قيد في قبول العمل، فأولئك كان عملهم متقبّلاً يثابون عليه بالجنة ورضوان الله. وكلاً من مريدي الدنيا ومريدي الآخرة يمدّ الله من فضله الواسع، فالكل يأكل ويشرب ويكتسي بحسب ما قُدّر له، ومن أراد الله إعطاءه شيئاً لم يستطع أحد أن يحرمه منه. انظر كيف فضّلنا بعض الناس على بعض في الرزق والصحة والمال والذرية والجاه، فاعلم أن الآخرة أكبر درجات وأكبر تفضيلاً، وذلك عائد إلى فضل الله ثم إلى الكسب صلاحاً وفساداً. ولا تجعل مع الله إلهاً آخر تعبده، فتقعد ملوماً يلومك المؤمنون والملائكة، مخذولاً لا ناصر لك، والخطاب للرسول ﷺ والمراد به كل إنسان.", "h": ["كلا الدارين، السعادة فيها أو الشقاء، متوقّف على الكسب والعمل، وهذه سنة الله تعالى في العباد.", "سعي الدنيا التجارة والفلاحة والصناعة.", "سعي الآخرة الإيمان وصالح الأعمال والتخلّي عن الشرك والمعاصي.", "يعطي الله تعالى الدنيا من يحب ومن لا يحب، وعطاؤه قائم على سنن له في الحياة يجب معرفتها والعمل بمقتضاها لمن أراد الدنيا والآخرة.", "ما أعطاه الله لا يمنعه أحد، فوجب التوكل على الله والإعراض عما سواه.", "تحريم الشرك والوعيد عليه بالخلود في نار جهنم."], "k": "«وسعى لها سعيها وهو مؤمن»… كم من سعيي اليوم للعاجلة، وكم منه للآخرة؟"}, {"lbl": "الآيات ٢٣ – ٢٧", "q": "۞وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنًاۚ إِمَّا يَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَآ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفّٖ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلٗا كَرِيمٗا ﴿٢٣﴾ وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرٗا ﴿٢٤﴾ رَّبُّكُمۡ أَعۡلَمُ بِمَا فِي نُفُوسِكُمۡۚ إِن تَكُونُواْ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلۡأَوَّـٰبِينَ غَفُورٗا ﴿٢٥﴾ وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَلَا تُبَذِّرۡ تَبۡذِيرًا ﴿٢٦﴾ إِنَّ ٱلۡمُبَذِّرِينَ كَانُوٓاْ إِخۡوَٰنَ ٱلشَّيَٰطِينِۖ وَكَانَ ٱلشَّيۡطَٰنُ لِرَبِّهِۦ كَفُورٗا ﴿٢٧﴾", "w": [["وقضى ربك", "أمر ووصّى."], ["وبالوالدين إحساناً", "وأن تحسنوا بالوالدين إحساناً ببرّهما."], ["فلا تقل لهما أفّ", "كلمة تضجّر."], ["ولا تنهرهما", "لا تزجرهما بالكلمة القاسية."], ["قولاً كريماً", "جميلاً ليّناً."], ["واخفض لهما جناح الذل", "ألن لهما جانبك وتواضع لهما."], ["للأوّابين", "الرجّاعين إلى الطاعة بعد المعصية."], ["وآت ذا القربى", "أعط أصحاب القرابات حقوقهم من البر والصلة."], ["ولا تبذّر تبذيراً", "لا تنفق المال في غير طاعة الله ورسوله."], ["لربه كفوراً", "كثير الكفر لنعم ربه، فكذلك المبذّر أخوه."]], "m": "لما حرّم الشرك أمر بالتوحيد: وحكم ربك ووصّى ألا تعبدوا إلا إياه، وأوصى بالوالدين إحساناً، بإيصال الخير إليهما وكفّ الأذى عنهما في غير معصية الله. إن بلغ الكبر عندك أحدهما أو كلاهما وأنت حي بينهما، وجب أن تخدمهما كما خدماك وأنت طفل، فتغسل بولهما وتطهّر نجاستهما وتقدّم لهما ما يحتاجان، ولا تتضجّر ولا تتأفّف كما لم يتضجّرا منك، ولا تزجرهما بالكلمة العالية، وقل لهما قولاً جميلاً ليّناً يشعران معه بالكرامة، وألن لهما جانبك وتعطّف عليهما، وادع لهما طوال حياتك بالمغفرة والرحمة إن كانا موحّدين، فقل: رب ارحمهما كما ربّياني صغيراً. ربكم أعلم بما في نفوسكم من الرضا عنهما أو السخط عليهما، وقد يضمر الإنسان مرة السوء أو تبدر منه البادرة وهو صالح مؤدٍّ للحقوق، فهو غفور له متى تاب. وآت ذا القربى حقه من البر والصلة، والمسكين بالإحسان إليه بالكساء أو الغذاء والكلمة الطيبة، وابن السبيل بالضيافة والمساعدة على سفره، ولا تنفق مالك في غير طاعة الله، إن المبذّرين في المعاصي كانوا إخوان الشياطين لأنهم فسقوا عن أمر ربهم، وكان الشيطان لربه كفوراً، فهل يرضى المسلم أن يكون شيطاناً؟", "h": ["وجوب عبادة الله تعالى وحده، ووجوب برّ الوالدين، وهو الإحسان بهما، وكفّ الأذى عنهما، وطاعتهما في المعروف.", "وجوب الدعاء للوالدين بالمغفرة والرحمة.", "وجوب مراقبة الله تعالى وعدم إضمار أي سوء في النفس.", "من كان صالحاً وبدرت منه البادرة وتاب منها فإن الله يغفر له ذلك.", "وجوب إعطاء ذوي القربى حقوقهم من البر والصلة، وكذا المساكين وابن السبيل.", "حرمة التبذير، وحقيقته إنفاق المال في المعاصي والمحرّمات."], "k": "«وقل رب ارحمهما كما ربياني صغيراً»… متى دعوت لوالديّ آخر مرة، وماذا أقدّم لهما اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (189, 17, 28, 39, 'سورة الإسراء ٢٨ – ٣٩', 'وصايا «وقضى ربك»: القول الميسور، والاعتدال في الإنفاق، وتحريم قتل الأولاد والزنا والنفس، ومال اليتيم، والوفاء بالعهد والكيل، و«ولا تقف ما ليس لك به علم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 189) = $j$[{"lbl": "الآيات ٢٨ – ٣٣", "q": "وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَآءَ رَحۡمَةٖ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلٗا مَّيۡسُورٗا ﴿٢٨﴾ وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومٗا مَّحۡسُورًا ﴿٢٩﴾ إِنَّ رَبَّكَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا ﴿٣٠﴾ وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُمۡ خَشۡيَةَ إِمۡلَٰقٖۖ نَّحۡنُ نَرۡزُقُهُمۡ وَإِيَّاكُمۡۚ إِنَّ قَتۡلَهُمۡ كَانَ خِطۡـٔٗا كَبِيرٗا ﴿٣١﴾ وَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَسَآءَ سَبِيلٗا ﴿٣٢﴾ وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۗ وَمَن قُتِلَ مَظۡلُومٗا فَقَدۡ جَعَلۡنَا لِوَلِيِّهِۦ سُلۡطَٰنٗا فَلَا يُسۡرِف فِّي ٱلۡقَتۡلِۖ إِنَّهُۥ كَانَ مَنصُورٗا ﴿٣٣﴾", "w": [["وإما تعرضنّ عنهم", "عن المذكورين من ذي القربى والمساكين وابن السبيل، فلم تعطهم."], ["ابتغاء رحمة من ربك ترجوها", "طلباً لرزق ترجوه من الله تعالى."], ["قولاً ميسوراً", "ليّناً سهلاً بأن تعدهم بالعطاء عند وجود الرزق."], ["مغلولة إلى عنقك", "لا تمسك عن النفقة كأن يدك مربوطة إلى عنقك فلا تستطيع الإنفاق."], ["ولا تبسطها كل البسط", "لا تنفق كل ما بيدك ولا تبق شيئاً."], ["ملوماً", "يلومك من حرمتهم من الإنفاق."], ["محسوراً", "منقطعاً عن سيرك في الحياة إذ لم تبق لك شيئاً."], ["يبسط الرزق ويقدر", "يوسّعه ويضيّقه امتحاناً وابتلاءً."], ["خشية إملاق", "خوف الفقر وشدّته."], ["خطئاً كبيراً", "إثماً عظيماً."], ["فاحشة وساء سبيلاً", "خصلة قبيحة شديدة القبح، وبئس السبيل سبيلها."], ["لوليه سلطاناً", "لوارثه تسلّطاً على القاتل."], ["فلا يسرف في القتل", "لا يقتل غير القاتل."]], "m": "ما زال السياق في وصايا الرب تعالى: إن أعرضت عن قريب أو مسكين أو ابن سبيل سألك ولم تجد ما تعطيه، طلباً لرزق ترجوه من ربك، فقل لهم قولاً سهلاً ليّناً، هو العدة الحسنة، كقولك: إن رزقني الله أعطيتك، فيكون ذلك عطاءً عاجلاً يسرّون به. ولا تبخل فتمنع ذوي الحقوق حقوقهم كأن يدك مشدودة إلى عنقك، ولا تفتحها بالعطاء فتخرج كل ما عندك فلا تبقي لك ولأهلك شيئاً، فإن أمسكت لامك سائلوك، وإن أنفقت الكل انقطعت بك الحياة كالبعير الذي أعياه السير فتُرك في الطريق. إن ربك يوسّع الرزق على من يشاء امتحاناً أيشكر، ويضيّقه على من يشاء ابتلاءً أيصبر، بحسب علمه وحكمته، إذ من عباده من لا يصلحه إلا السعة ومنهم من لا يصلحه إلا الضيق. ولا تقتلوا أولادكم خوف الفقر، كما كان العرب يفعلون، نحن نرزقهم وإياكم، إن قتلهم كان إثماً عظيماً. ولا تقربوا الزنا مجرد قرب، إنه كان خصلة قبيحة طبعاً وعقلاً وشرعاً، وبئس الطريق طريقه، أوله أذية المؤمنين في أعراضهم وآخره جهنم. ولا تقتلوا النفس التي حرّم الله إلا بالحق، وقد بيّنه رسول الله ﷺ: القتل العمد العدوان، والزنا بعد الإحصان، والكفر بعد الإيمان. ومن قُتل ظلماً فقد جعلنا لوليه سلطة على القاتل، إن شاء قتله، وإن شاء أخذ الدية، وإن شاء عفا لوجه الله، فلا يسرف في القتل فيقتل أكثر من واحد أو غير القاتل كما كانوا يفعلون في الجاهلية.", "h": ["العدة الحسنة تقوم مقام الصدقة لمن لم يجد ما يتصدّق به على من سأله.", "حرمة البخل والإسراف معاً، وفضيلة الاعتدال والقصد.", "تجلّي حكمة الله تعالى في التوسعة على أناس والتضييق على آخرين.", "حرمة قتل الأولاد بعد الولادة، أو إجهاضاً قبلها، خوفاً من الفقر أو العار.", "حرمة مقدّمات الزنا كالنظر بشهوة والكلام مع الأجنبية ومسّها، وحرمة الزنا وهو أشد.", "حرمة قتل النفس التي حرّم الله قتلها إلا بالحق، والحق قتل عمد عدواناً، وزناً بعد إحصان، وكفر بعد إيمان."], "k": "«فقل لهم قولاً ميسوراً»… إن لم أجد ما أعطيه، فهل أجد الكلمة الطيبة؟"}, {"lbl": "الآيات ٣٤ – ٣٩", "q": "وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ بِٱلۡعَهۡدِۖ إِنَّ ٱلۡعَهۡدَ كَانَ مَسۡـُٔولٗا ﴿٣٤﴾ وَأَوۡفُواْ ٱلۡكَيۡلَ إِذَا كِلۡتُمۡ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلٗا ﴿٣٥﴾ وَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُوْلَـٰٓئِكَ كَانَ عَنۡهُ مَسۡـُٔولٗا ﴿٣٦﴾ وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّكَ لَن تَخۡرِقَ ٱلۡأَرۡضَ وَلَن تَبۡلُغَ ٱلۡجِبَالَ طُولٗا ﴿٣٧﴾ كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكۡرُوهٗا ﴿٣٨﴾ ذَٰلِكَ مِمَّآ أَوۡحَىٰٓ إِلَيۡكَ رَبُّكَ مِنَ ٱلۡحِكۡمَةِۗ وَلَا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتُلۡقَىٰ فِي جَهَنَّمَ مَلُومٗا مَّدۡحُورًا ﴿٣٩﴾", "w": [["إلا بالتي هي أحسن", "بالخصلة التي هي أحسن من غيرها، وهي تنميته والإنفاق عليه منه بالمعروف."], ["حتى يبلغ أشدّه", "بلوغه سن التكليف وهو عاقل رشيد."], ["وأوفوا بالعهد", "إذا عاهدتم الله أو العباد فأوفوا بما عاهدتم عليه."], ["إن العهد كان مسئولاً", "يُسأل العبد عنه يوم القيامة: لِمَ نكثت عهدك؟"], ["أوفوا الكيل", "أتمّوه ولا تنقصوه."], ["بالقسطاس المستقيم", "الميزان السوي المعتدل."], ["وأحسن تأويلاً", "مآلاً وعاقبة."], ["ولا تقف", "لا تتّبع."], ["والفؤاد", "القلب."], ["كان عنه مسئولاً", "يُسأل عن كل واحد من هذه الحواس الثلاث يوم القيامة."], ["مرحاً", "ذا مرح بالكبر والخيلاء."], ["لن تخرق الأرض", "لن تثقبها أو تشقها بقدميك."], ["من الحكمة", "معرفة محابّ الله للتقرب بها إليه، ومعرفة مساخطه للبعد عنها."], ["ملوماً مدحوراً", "تلوم نفسك على شركك بربك، مبعداً من رحمة الله تعالى."]], "m": "ما زال السياق في وصايا الله لعباده المؤمنين: ولا تقربوا مال اليتيم إلا بالتصرّف الأجمل، بتثميره وإصلاحه والإنفاق منه عليه بالمعروف، لا أن تأكلوه إسرافاً وبداراً، حتى يبلغ سن الرشد فتعطوه ماله. وأوفوا بعهودكم مع ربكم ومع سائر الناس مؤمنهم وكافرهم، فإن العبد سيُسأل يوم القيامة عن عهده الذي لم يفِ به، ومثله سائر العقود من نكاح وبيع وإيجار. وأوفوا الكيل والوزن ولا تبخسوهما شيئاً ما دام في الإمكان، أما ما يعسر التحرّز منه فمعفوّ عنه، ذلك خير لبراءة الذمة، وأحسن عاقبة إذ يبارك الله في ذلك المال، ومن ترك المعصية وهو قادر عليها أثابه الله. ولا تتّبع بقول ولا عمل ما لا تعلم، فلا تقل رأيت وأنت لم تر، ولا سمعت وأنت لم تسمع، إن السمع والبصر والقلب كل أولئك يسأله الله يوم القيامة فيشهد على صاحبه. ولا تمش في الأرض خيلاء وتكبّراً، إنك لن تثقب الأرض برجليك مهما ضربتها، ولن تبلغ الجبال طولاً مهما تطاولت، فاترك مشية الخيلاء فإنها منقصة لا يأتيها إلا ذو سفه. كل ذلك من المنهيات، كالتبذير والبخل وقتل الأولاد والزنا وقتل النفس وأكل مال اليتيم وبخس الكيل والقول بلا علم والتكبّر، مكروه عند الله. ذلك مما أوحينا إليك من الحكمة، ثم ختم بما بدأ به: ولا تجعل مع الله إلهاً آخر فتُلقى في جهنم ملوماً من نفسك مبعداً من رحمة ربك، إن مات قبل أن يتوب، فالتوبة إذا صحّت جبّت ما قبلها.", "h": ["حرمة مال اليتيم أكلاً أو إفساداً أو تضييعاً وإهمالاً.", "وجوب الوفاء بالعهود وسائر العقود.", "وجوب توفية الكيل والوزن، وحرمة بخس الكيل والوزن.", "حصول البركة لمن يمتثل أمر الله في كيله ووزنه.", "حرمة القول أو العمل بدون علم، لما يفضي إليه ذلك من المفاسد، ولأن الله تعالى سائل كل الجوارح ومستشهدها على صاحبها يوم القيامة.", "حرمة الكبر ومقت المتكبّرين.", "انتظام هذا السياق لخمس وعشرين حكمة، الأخذ بها خير من الدنيا وما فيها، والتفريط فيها سبب خسران الدنيا والآخرة."], "k": "«ولا تقف ما ليس لك به علم»… كلمة أنقلها عن غيري، هل تثبّتُّ منها قبل أن أقولها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 189;
insert into public.tdb_cards(topic, i, body) select 189, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٨ – ٣٣", "q": "وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَآءَ رَحۡمَةٖ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلٗا مَّيۡسُورٗا ﴿٢٨﴾ وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومٗا مَّحۡسُورًا ﴿٢٩﴾ إِنَّ رَبَّكَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا ﴿٣٠﴾ وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُمۡ خَشۡيَةَ إِمۡلَٰقٖۖ نَّحۡنُ نَرۡزُقُهُمۡ وَإِيَّاكُمۡۚ إِنَّ قَتۡلَهُمۡ كَانَ خِطۡـٔٗا كَبِيرٗا ﴿٣١﴾ وَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَسَآءَ سَبِيلٗا ﴿٣٢﴾ وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۗ وَمَن قُتِلَ مَظۡلُومٗا فَقَدۡ جَعَلۡنَا لِوَلِيِّهِۦ سُلۡطَٰنٗا فَلَا يُسۡرِف فِّي ٱلۡقَتۡلِۖ إِنَّهُۥ كَانَ مَنصُورٗا ﴿٣٣﴾", "w": [["وإما تعرضنّ عنهم", "عن المذكورين من ذي القربى والمساكين وابن السبيل، فلم تعطهم."], ["ابتغاء رحمة من ربك ترجوها", "طلباً لرزق ترجوه من الله تعالى."], ["قولاً ميسوراً", "ليّناً سهلاً بأن تعدهم بالعطاء عند وجود الرزق."], ["مغلولة إلى عنقك", "لا تمسك عن النفقة كأن يدك مربوطة إلى عنقك فلا تستطيع الإنفاق."], ["ولا تبسطها كل البسط", "لا تنفق كل ما بيدك ولا تبق شيئاً."], ["ملوماً", "يلومك من حرمتهم من الإنفاق."], ["محسوراً", "منقطعاً عن سيرك في الحياة إذ لم تبق لك شيئاً."], ["يبسط الرزق ويقدر", "يوسّعه ويضيّقه امتحاناً وابتلاءً."], ["خشية إملاق", "خوف الفقر وشدّته."], ["خطئاً كبيراً", "إثماً عظيماً."], ["فاحشة وساء سبيلاً", "خصلة قبيحة شديدة القبح، وبئس السبيل سبيلها."], ["لوليه سلطاناً", "لوارثه تسلّطاً على القاتل."], ["فلا يسرف في القتل", "لا يقتل غير القاتل."]], "m": "ما زال السياق في وصايا الرب تعالى: إن أعرضت عن قريب أو مسكين أو ابن سبيل سألك ولم تجد ما تعطيه، طلباً لرزق ترجوه من ربك، فقل لهم قولاً سهلاً ليّناً، هو العدة الحسنة، كقولك: إن رزقني الله أعطيتك، فيكون ذلك عطاءً عاجلاً يسرّون به. ولا تبخل فتمنع ذوي الحقوق حقوقهم كأن يدك مشدودة إلى عنقك، ولا تفتحها بالعطاء فتخرج كل ما عندك فلا تبقي لك ولأهلك شيئاً، فإن أمسكت لامك سائلوك، وإن أنفقت الكل انقطعت بك الحياة كالبعير الذي أعياه السير فتُرك في الطريق. إن ربك يوسّع الرزق على من يشاء امتحاناً أيشكر، ويضيّقه على من يشاء ابتلاءً أيصبر، بحسب علمه وحكمته، إذ من عباده من لا يصلحه إلا السعة ومنهم من لا يصلحه إلا الضيق. ولا تقتلوا أولادكم خوف الفقر، كما كان العرب يفعلون، نحن نرزقهم وإياكم، إن قتلهم كان إثماً عظيماً. ولا تقربوا الزنا مجرد قرب، إنه كان خصلة قبيحة طبعاً وعقلاً وشرعاً، وبئس الطريق طريقه، أوله أذية المؤمنين في أعراضهم وآخره جهنم. ولا تقتلوا النفس التي حرّم الله إلا بالحق، وقد بيّنه رسول الله ﷺ: القتل العمد العدوان، والزنا بعد الإحصان، والكفر بعد الإيمان. ومن قُتل ظلماً فقد جعلنا لوليه سلطة على القاتل، إن شاء قتله، وإن شاء أخذ الدية، وإن شاء عفا لوجه الله، فلا يسرف في القتل فيقتل أكثر من واحد أو غير القاتل كما كانوا يفعلون في الجاهلية.", "h": ["العدة الحسنة تقوم مقام الصدقة لمن لم يجد ما يتصدّق به على من سأله.", "حرمة البخل والإسراف معاً، وفضيلة الاعتدال والقصد.", "تجلّي حكمة الله تعالى في التوسعة على أناس والتضييق على آخرين.", "حرمة قتل الأولاد بعد الولادة، أو إجهاضاً قبلها، خوفاً من الفقر أو العار.", "حرمة مقدّمات الزنا كالنظر بشهوة والكلام مع الأجنبية ومسّها، وحرمة الزنا وهو أشد.", "حرمة قتل النفس التي حرّم الله قتلها إلا بالحق، والحق قتل عمد عدواناً، وزناً بعد إحصان، وكفر بعد إيمان."], "k": "«فقل لهم قولاً ميسوراً»… إن لم أجد ما أعطيه، فهل أجد الكلمة الطيبة؟"}, {"lbl": "الآيات ٣٤ – ٣٩", "q": "وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ بِٱلۡعَهۡدِۖ إِنَّ ٱلۡعَهۡدَ كَانَ مَسۡـُٔولٗا ﴿٣٤﴾ وَأَوۡفُواْ ٱلۡكَيۡلَ إِذَا كِلۡتُمۡ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلٗا ﴿٣٥﴾ وَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُوْلَـٰٓئِكَ كَانَ عَنۡهُ مَسۡـُٔولٗا ﴿٣٦﴾ وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّكَ لَن تَخۡرِقَ ٱلۡأَرۡضَ وَلَن تَبۡلُغَ ٱلۡجِبَالَ طُولٗا ﴿٣٧﴾ كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكۡرُوهٗا ﴿٣٨﴾ ذَٰلِكَ مِمَّآ أَوۡحَىٰٓ إِلَيۡكَ رَبُّكَ مِنَ ٱلۡحِكۡمَةِۗ وَلَا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتُلۡقَىٰ فِي جَهَنَّمَ مَلُومٗا مَّدۡحُورًا ﴿٣٩﴾", "w": [["إلا بالتي هي أحسن", "بالخصلة التي هي أحسن من غيرها، وهي تنميته والإنفاق عليه منه بالمعروف."], ["حتى يبلغ أشدّه", "بلوغه سن التكليف وهو عاقل رشيد."], ["وأوفوا بالعهد", "إذا عاهدتم الله أو العباد فأوفوا بما عاهدتم عليه."], ["إن العهد كان مسئولاً", "يُسأل العبد عنه يوم القيامة: لِمَ نكثت عهدك؟"], ["أوفوا الكيل", "أتمّوه ولا تنقصوه."], ["بالقسطاس المستقيم", "الميزان السوي المعتدل."], ["وأحسن تأويلاً", "مآلاً وعاقبة."], ["ولا تقف", "لا تتّبع."], ["والفؤاد", "القلب."], ["كان عنه مسئولاً", "يُسأل عن كل واحد من هذه الحواس الثلاث يوم القيامة."], ["مرحاً", "ذا مرح بالكبر والخيلاء."], ["لن تخرق الأرض", "لن تثقبها أو تشقها بقدميك."], ["من الحكمة", "معرفة محابّ الله للتقرب بها إليه، ومعرفة مساخطه للبعد عنها."], ["ملوماً مدحوراً", "تلوم نفسك على شركك بربك، مبعداً من رحمة الله تعالى."]], "m": "ما زال السياق في وصايا الله لعباده المؤمنين: ولا تقربوا مال اليتيم إلا بالتصرّف الأجمل، بتثميره وإصلاحه والإنفاق منه عليه بالمعروف، لا أن تأكلوه إسرافاً وبداراً، حتى يبلغ سن الرشد فتعطوه ماله. وأوفوا بعهودكم مع ربكم ومع سائر الناس مؤمنهم وكافرهم، فإن العبد سيُسأل يوم القيامة عن عهده الذي لم يفِ به، ومثله سائر العقود من نكاح وبيع وإيجار. وأوفوا الكيل والوزن ولا تبخسوهما شيئاً ما دام في الإمكان، أما ما يعسر التحرّز منه فمعفوّ عنه، ذلك خير لبراءة الذمة، وأحسن عاقبة إذ يبارك الله في ذلك المال، ومن ترك المعصية وهو قادر عليها أثابه الله. ولا تتّبع بقول ولا عمل ما لا تعلم، فلا تقل رأيت وأنت لم تر، ولا سمعت وأنت لم تسمع، إن السمع والبصر والقلب كل أولئك يسأله الله يوم القيامة فيشهد على صاحبه. ولا تمش في الأرض خيلاء وتكبّراً، إنك لن تثقب الأرض برجليك مهما ضربتها، ولن تبلغ الجبال طولاً مهما تطاولت، فاترك مشية الخيلاء فإنها منقصة لا يأتيها إلا ذو سفه. كل ذلك من المنهيات، كالتبذير والبخل وقتل الأولاد والزنا وقتل النفس وأكل مال اليتيم وبخس الكيل والقول بلا علم والتكبّر، مكروه عند الله. ذلك مما أوحينا إليك من الحكمة، ثم ختم بما بدأ به: ولا تجعل مع الله إلهاً آخر فتُلقى في جهنم ملوماً من نفسك مبعداً من رحمة ربك، إن مات قبل أن يتوب، فالتوبة إذا صحّت جبّت ما قبلها.", "h": ["حرمة مال اليتيم أكلاً أو إفساداً أو تضييعاً وإهمالاً.", "وجوب الوفاء بالعهود وسائر العقود.", "وجوب توفية الكيل والوزن، وحرمة بخس الكيل والوزن.", "حصول البركة لمن يمتثل أمر الله في كيله ووزنه.", "حرمة القول أو العمل بدون علم، لما يفضي إليه ذلك من المفاسد، ولأن الله تعالى سائل كل الجوارح ومستشهدها على صاحبها يوم القيامة.", "حرمة الكبر ومقت المتكبّرين.", "انتظام هذا السياق لخمس وعشرين حكمة، الأخذ بها خير من الدنيا وما فيها، والتفريط فيها سبب خسران الدنيا والآخرة."], "k": "«ولا تقف ما ليس لك به علم»… كلمة أنقلها عن غيري، هل تثبّتُّ منها قبل أن أقولها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (190, 17, 40, 52, 'سورة الإسراء ٤٠ – ٥٢', '«تسبّح له السماوات السبع والأرض ومن فيهن»، والحجاب المستور عن سماع القرآن، و«قل الذي فطركم أول مرة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 190) = $j$[{"lbl": "الآيات ٤٠ – ٤٤", "q": "أَفَأَصۡفَىٰكُمۡ رَبُّكُم بِٱلۡبَنِينَ وَٱتَّخَذَ مِنَ ٱلۡمَلَـٰٓئِكَةِ إِنَٰثًاۚ إِنَّكُمۡ لَتَقُولُونَ قَوۡلًا عَظِيمٗا ﴿٤٠﴾ وَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِيَذَّكَّرُواْ وَمَا يَزِيدُهُمۡ إِلَّا نُفُورٗا ﴿٤١﴾ قُل لَّوۡ كَانَ مَعَهُۥٓ ءَالِهَةٞ كَمَا يَقُولُونَ إِذٗا لَّٱبۡتَغَوۡاْ إِلَىٰ ذِي ٱلۡعَرۡشِ سَبِيلٗا ﴿٤٢﴾ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَقُولُونَ عُلُوّٗا كَبِيرٗا ﴿٤٣﴾ تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا ﴿٤٤﴾", "w": [["أفأصفاكم", "الاستفهام للتوبيخ والتقريع، ومعنى أصفاكم: خصّكم بالبنين."], ["ولقد صرّفنا في هذا القرآن", "بيّنا فيه من الوعد والوعيد والأمثال والعظات والأحكام."], ["ليذّكّروا", "ليتذكّروا فيتّعظوا فيؤمنوا ويطيعوا."], ["لابتغوا إلى ذي العرش سبيلاً", "لطلبوا طريقاً إلى الله تعالى للتقرّب إليه وطلب المنزلة عنده."], ["ومن فيهن", "في السماوات من الملائكة، والأرض من إنس وجان."], ["وإن من شيء إلا يسبّح", "ما من شيء من سائر المخلوقات إلا يسبّح بحمده."], ["حليماً غفوراً", "حيث لم يعاجلكم بالعقوبة على معصيتكم إياه."]], "m": "يقول تعالى مقرّعاً المشركين الذين يئدون البنات ويكرهونهن ثم يجعلون الملائكة إناثاً: أفخصّكم ربكم بالبنين واتخذ من الملائكة إناثاً؟ إنكم لتقولون قولاً عظيماً، إذ تجعلون لله ما تكرهون افتراءً عليه. ولقد صرّفنا في هذا القرآن من الحجج والأمثال والمواعظ الشيء الكثير ليتذكّروا فيتّعظوا ويوحّدوا ربهم، وما يزيدهم إلا نفوراً عن الحق لغلبة التقليد والعناد عليهم. قل لهم: لو كان مع الله آلهة كما تقولون، والواقع يكذّبكم، لطلبوا طريقاً إلى ذي العرش يلتمسون رضاه والقرب منه لجلاله وكماله وحاجتهم إليه. سبحانه وتعالى عما يقولون علواً كبيراً. تسبّح له السماوات السبع والأرض ومن فيهن، وما من شيء من المخلوقات إلا يسبّح بحمده بلسان قاله وحاله معاً، ولكن لا تفقهون تسبيحهم لاختلاف لغاتهم، إنه كان حليماً لا يعاجل بالعقوبة من عصاه، غفوراً لذنوب من تاب إليه وأناب.", "h": ["حرمة القول على الله تعالى بالباطل، ونسبة النقص إليه تعالى كاتخاذه ولداً أو شريكاً.", "مشروعية الاستدلال بالعقليات على إحقاق الحق وإبطال الباطل.", "فضيلة التسبيح، وهو قول: سبحان الله وبحمده، حتى إن من قالها مائة مرة غُفرت ذنوبه ولو كانت في الكثرة مثل زبد البحر.", "كل المخلوقات في العوالم كلها تسبّح الله تعالى، أي تنزّهه عن الشريك والولد والنقص والعجز ومشابهة الحوادث؛ إذ ليس كمثله شيء وهو السميع البصير.", "حلم الله يتجلّى في عدم تعجيل عقوبة من عصاه، ولولا حلمه لعجّل عقوبة مشركي مكة وأكابر مجرميها، ولكن الله أمهلهم حتى تاب أكثرهم."], "k": "«وإن من شيء إلا يسبّح بحمده»… كل ما حولي يسبّح الآن؛ فهل أسبّح معه: سبحان الله وبحمده؟"}, {"lbl": "الآيات ٤٥ – ٤٨", "q": "وَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ جَعَلۡنَا بَيۡنَكَ وَبَيۡنَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ حِجَابٗا مَّسۡتُورٗا ﴿٤٥﴾ وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِذَا ذَكَرۡتَ رَبَّكَ فِي ٱلۡقُرۡءَانِ وَحۡدَهُۥ وَلَّوۡاْ عَلَىٰٓ أَدۡبَٰرِهِمۡ نُفُورٗا ﴿٤٦﴾ نَّحۡنُ أَعۡلَمُ بِمَا يَسۡتَمِعُونَ بِهِۦٓ إِذۡ يَسۡتَمِعُونَ إِلَيۡكَ وَإِذۡ هُمۡ نَجۡوَىٰٓ إِذۡ يَقُولُ ٱلظَّـٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلٗا مَّسۡحُورًا ﴿٤٧﴾ ٱنظُرۡ كَيۡفَ ضَرَبُواْ لَكَ ٱلۡأَمۡثَالَ فَضَلُّواْ فَلَا يَسۡتَطِيعُونَ سَبِيلٗا ﴿٤٨﴾", "w": [["حجاباً مستوراً", "ساتراً لهم فلا يسمعون كلام الله تعالى."], ["أكنّة", "أغطية على القلوب فلا تعي ولا تفهم."], ["وفي آذانهم وقراً", "ثقلاً فلا يسمعون القرآن ومواعظه."], ["ولّوا على أدبارهم نفوراً", "فراراً من السماع حتى لا يسمعوا."], ["بما يستمعون به", "بسببه، وهو الهزء بالنبي ﷺ."], ["وإذ هم نجوى", "يتناجون بينهم يتحدّثون سراً."], ["رجلاً مسحوراً", "مغلوباً على عقله مخدوعاً."], ["ضربوا لك الأمثال", "قالوا: ساحر، وقالوا: كاهن، وقالوا: شاعر."], ["فضلّوا", "عن الهدى فلا يستطيعون سبيلاً."]], "m": "إذا قرأ الرسول ﷺ القرآن على المشركين ليدعوهم إلى الله، جعل الله بينه وبينهم حجاباً ساتراً لا يُرى، يحول بينهم وبين الانتفاع بما يُقرأ عليهم، وهذا الحجاب ناتج عن شدة بغضهم للرسول ﷺ وكراهيتهم لدعوته. وجعل على قلوبهم أغطية حتى لا يصل المعنى إليها فيفقهوه، وفي آذانهم ثقلاً فلا يسمعونه، عقوبة من الله حرمهم بها الهداية لسابقة الشر لهم، وما ظلمهم الله ولكن كانوا هم الظالمين. وإذا ذكرت ربك في القرآن وحده، بأن قلت: لا إله إلا الله، ولّوا على أدبارهم نفوراً من سماع التوحيد لحبّهم الوثنية. نحن أعلم بما يستمعون به: إنهم يستمعون من أجل الاستهزاء والسخرية، لا لطلب الحق، وإذ هم يتناجون فيقول الظالمون: ما تتبعون إلا رجلاً مسحوراً مغلوباً على أمره. انظر كيف ضربوا لك الأمثال فقالوا: ساحر وشاعر وكاهن ومجنون، فضلّوا في طريقهم فلا يستطيعون الخروج من حيرتهم التي أوقعهم فيها كفرهم.", "h": ["تقرير قاعدة: حبّك الشيء يُعمي ويُصمّ؛ فإن الحجاب والأكنّة والثقل في الآذان حالت دون سماع القرآن من أجل بغضهم للرسول ﷺ وللقرآن وما جاء به من الدعوة إلى التوحيد.", "بيان مدى كراهية المشركين للتوحيد وكلمة الإخلاص لا إله إلا الله.", "بيان مدى ما كان عليه المشركون من السخرية والاستهزاء بالرسول والقرآن.", "تنقّل المشركين في اتهاماتهم للرسول ﷺ بالسحر مرة والكهانة ثانية والجنون ثالثة بحثاً عن الخلاص من دعوة التوحيد، فلم يعثروا على شيء."], "k": "«وإذا قرأت القرآن جعلنا بينك وبين الذين لا يؤمنون بالآخرة حجاباً»… هل في قلبي ما يحجبني عن تدبّر ما أقرأ؟"}, {"lbl": "الآيات ٤٩ – ٥٢", "q": "وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمٗا وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقٗا جَدِيدٗا ﴿٤٩﴾ ۞قُلۡ كُونُواْ حِجَارَةً أَوۡ حَدِيدًا ﴿٥٠﴾ أَوۡ خَلۡقٗا مِّمَّا يَكۡبُرُ فِي صُدُورِكُمۡۚ فَسَيَقُولُونَ مَن يُعِيدُنَاۖ قُلِ ٱلَّذِي فَطَرَكُمۡ أَوَّلَ مَرَّةٖۚ فَسَيُنۡغِضُونَ إِلَيۡكَ رُءُوسَهُمۡ وَيَقُولُونَ مَتَىٰ هُوَۖ قُلۡ عَسَىٰٓ أَن يَكُونَ قَرِيبٗا ﴿٥١﴾ يَوۡمَ يَدۡعُوكُمۡ فَتَسۡتَجِيبُونَ بِحَمۡدِهِۦ وَتَظُنُّونَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗا ﴿٥٢﴾", "w": [["عظاماً ورفاتاً", "الاستفهام للإنكار والاستبعاد، والرفات: الأجزاء المتفرّقة."], ["مما يكبر في صدوركم", "يعظم عن قبول الحياة في اعتقادكم."], ["فسينغضون", "يحرّكون رؤوسهم تعجّباً."], ["متى هو؟", "الاستفهام للاستهزاء، أي: متى هذا البعث الذي تعدنا؟"], ["يوم يدعوكم", "يناديكم من قبوركم على لسان إسرافيل."], ["فتستجيبون بحمده", "تجيبون دعوته قائلين: سبحانك اللهم وبحمدك."], ["وتظنّون إن لبثتم إلا قليلاً", "تظنّون أنكم ما لبثتم في قبوركم إلا قليلاً."]], "m": "ما زال السياق في تقرير العقيدة، فبعد تقرير التوحيد والوحي يقرّر البعث والجزاء: قال المشركون منكرين: أئذا كنا عظاماً وأجزاء متفرّقة كالحطام أئنا لمبعوثون خلقاً جديداً؟ فأمر رسوله أن يقول لهم: كونوا ما شئتم، حجارة أو حديداً أو خلقاً مما يعظم في نفوسكم أن يقبل الحياة، فإن الله سيحييكم ويبعثكم. فسيقولون: من يعيدنا؟ قل: الذي خلقكم أول مرة، وهو جواب مسكت، فالذي خلقكم ثم أماتكم هو الذي يعيدكم وهو أهون عليه. فسيحرّكون إليك رؤوسهم استهزاءً ويقولون: متى هو؟ قل: عسى أن يكون قريباً، يوم يدعوكم إسرافيل بأمر الله من قبوركم فتجيبونه بحمد الله، وتظنّون أنكم ما لبثتم في قبوركم إلا قليلاً، لما تعاينون من الأهوال المفزعة.", "h": ["تقرير عقيدة البعث والجزاء وبيان حتميّتها.", "بيان ما كان عليه المشركون من شدة إنكارهم للبعث الآخر.", "تعليم الله تعالى لرسوله كيف يجيب المنكرين المستهزئين بالتي هي أحسن.", "بيان الأسلوب الحواري الهادئ الخالي من الغلظة والشدة.", "استقصار مدة اللبث في القبور مع طولها، لما يُشاهد من أهوال البعث."], "k": "«وتظنّون إن لبثتم إلا قليلاً»… عمري كله سيبدو قليلاً؛ فبماذا أملأ ما بقي منه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 190;
insert into public.tdb_cards(topic, i, body) select 190, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٠ – ٤٤", "q": "أَفَأَصۡفَىٰكُمۡ رَبُّكُم بِٱلۡبَنِينَ وَٱتَّخَذَ مِنَ ٱلۡمَلَـٰٓئِكَةِ إِنَٰثًاۚ إِنَّكُمۡ لَتَقُولُونَ قَوۡلًا عَظِيمٗا ﴿٤٠﴾ وَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِيَذَّكَّرُواْ وَمَا يَزِيدُهُمۡ إِلَّا نُفُورٗا ﴿٤١﴾ قُل لَّوۡ كَانَ مَعَهُۥٓ ءَالِهَةٞ كَمَا يَقُولُونَ إِذٗا لَّٱبۡتَغَوۡاْ إِلَىٰ ذِي ٱلۡعَرۡشِ سَبِيلٗا ﴿٤٢﴾ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَقُولُونَ عُلُوّٗا كَبِيرٗا ﴿٤٣﴾ تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورٗا ﴿٤٤﴾", "w": [["أفأصفاكم", "الاستفهام للتوبيخ والتقريع، ومعنى أصفاكم: خصّكم بالبنين."], ["ولقد صرّفنا في هذا القرآن", "بيّنا فيه من الوعد والوعيد والأمثال والعظات والأحكام."], ["ليذّكّروا", "ليتذكّروا فيتّعظوا فيؤمنوا ويطيعوا."], ["لابتغوا إلى ذي العرش سبيلاً", "لطلبوا طريقاً إلى الله تعالى للتقرّب إليه وطلب المنزلة عنده."], ["ومن فيهن", "في السماوات من الملائكة، والأرض من إنس وجان."], ["وإن من شيء إلا يسبّح", "ما من شيء من سائر المخلوقات إلا يسبّح بحمده."], ["حليماً غفوراً", "حيث لم يعاجلكم بالعقوبة على معصيتكم إياه."]], "m": "يقول تعالى مقرّعاً المشركين الذين يئدون البنات ويكرهونهن ثم يجعلون الملائكة إناثاً: أفخصّكم ربكم بالبنين واتخذ من الملائكة إناثاً؟ إنكم لتقولون قولاً عظيماً، إذ تجعلون لله ما تكرهون افتراءً عليه. ولقد صرّفنا في هذا القرآن من الحجج والأمثال والمواعظ الشيء الكثير ليتذكّروا فيتّعظوا ويوحّدوا ربهم، وما يزيدهم إلا نفوراً عن الحق لغلبة التقليد والعناد عليهم. قل لهم: لو كان مع الله آلهة كما تقولون، والواقع يكذّبكم، لطلبوا طريقاً إلى ذي العرش يلتمسون رضاه والقرب منه لجلاله وكماله وحاجتهم إليه. سبحانه وتعالى عما يقولون علواً كبيراً. تسبّح له السماوات السبع والأرض ومن فيهن، وما من شيء من المخلوقات إلا يسبّح بحمده بلسان قاله وحاله معاً، ولكن لا تفقهون تسبيحهم لاختلاف لغاتهم، إنه كان حليماً لا يعاجل بالعقوبة من عصاه، غفوراً لذنوب من تاب إليه وأناب.", "h": ["حرمة القول على الله تعالى بالباطل، ونسبة النقص إليه تعالى كاتخاذه ولداً أو شريكاً.", "مشروعية الاستدلال بالعقليات على إحقاق الحق وإبطال الباطل.", "فضيلة التسبيح، وهو قول: سبحان الله وبحمده، حتى إن من قالها مائة مرة غُفرت ذنوبه ولو كانت في الكثرة مثل زبد البحر.", "كل المخلوقات في العوالم كلها تسبّح الله تعالى، أي تنزّهه عن الشريك والولد والنقص والعجز ومشابهة الحوادث؛ إذ ليس كمثله شيء وهو السميع البصير.", "حلم الله يتجلّى في عدم تعجيل عقوبة من عصاه، ولولا حلمه لعجّل عقوبة مشركي مكة وأكابر مجرميها، ولكن الله أمهلهم حتى تاب أكثرهم."], "k": "«وإن من شيء إلا يسبّح بحمده»… كل ما حولي يسبّح الآن؛ فهل أسبّح معه: سبحان الله وبحمده؟"}, {"lbl": "الآيات ٤٥ – ٤٨", "q": "وَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ جَعَلۡنَا بَيۡنَكَ وَبَيۡنَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ حِجَابٗا مَّسۡتُورٗا ﴿٤٥﴾ وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۚ وَإِذَا ذَكَرۡتَ رَبَّكَ فِي ٱلۡقُرۡءَانِ وَحۡدَهُۥ وَلَّوۡاْ عَلَىٰٓ أَدۡبَٰرِهِمۡ نُفُورٗا ﴿٤٦﴾ نَّحۡنُ أَعۡلَمُ بِمَا يَسۡتَمِعُونَ بِهِۦٓ إِذۡ يَسۡتَمِعُونَ إِلَيۡكَ وَإِذۡ هُمۡ نَجۡوَىٰٓ إِذۡ يَقُولُ ٱلظَّـٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلٗا مَّسۡحُورًا ﴿٤٧﴾ ٱنظُرۡ كَيۡفَ ضَرَبُواْ لَكَ ٱلۡأَمۡثَالَ فَضَلُّواْ فَلَا يَسۡتَطِيعُونَ سَبِيلٗا ﴿٤٨﴾", "w": [["حجاباً مستوراً", "ساتراً لهم فلا يسمعون كلام الله تعالى."], ["أكنّة", "أغطية على القلوب فلا تعي ولا تفهم."], ["وفي آذانهم وقراً", "ثقلاً فلا يسمعون القرآن ومواعظه."], ["ولّوا على أدبارهم نفوراً", "فراراً من السماع حتى لا يسمعوا."], ["بما يستمعون به", "بسببه، وهو الهزء بالنبي ﷺ."], ["وإذ هم نجوى", "يتناجون بينهم يتحدّثون سراً."], ["رجلاً مسحوراً", "مغلوباً على عقله مخدوعاً."], ["ضربوا لك الأمثال", "قالوا: ساحر، وقالوا: كاهن، وقالوا: شاعر."], ["فضلّوا", "عن الهدى فلا يستطيعون سبيلاً."]], "m": "إذا قرأ الرسول ﷺ القرآن على المشركين ليدعوهم إلى الله، جعل الله بينه وبينهم حجاباً ساتراً لا يُرى، يحول بينهم وبين الانتفاع بما يُقرأ عليهم، وهذا الحجاب ناتج عن شدة بغضهم للرسول ﷺ وكراهيتهم لدعوته. وجعل على قلوبهم أغطية حتى لا يصل المعنى إليها فيفقهوه، وفي آذانهم ثقلاً فلا يسمعونه، عقوبة من الله حرمهم بها الهداية لسابقة الشر لهم، وما ظلمهم الله ولكن كانوا هم الظالمين. وإذا ذكرت ربك في القرآن وحده، بأن قلت: لا إله إلا الله، ولّوا على أدبارهم نفوراً من سماع التوحيد لحبّهم الوثنية. نحن أعلم بما يستمعون به: إنهم يستمعون من أجل الاستهزاء والسخرية، لا لطلب الحق، وإذ هم يتناجون فيقول الظالمون: ما تتبعون إلا رجلاً مسحوراً مغلوباً على أمره. انظر كيف ضربوا لك الأمثال فقالوا: ساحر وشاعر وكاهن ومجنون، فضلّوا في طريقهم فلا يستطيعون الخروج من حيرتهم التي أوقعهم فيها كفرهم.", "h": ["تقرير قاعدة: حبّك الشيء يُعمي ويُصمّ؛ فإن الحجاب والأكنّة والثقل في الآذان حالت دون سماع القرآن من أجل بغضهم للرسول ﷺ وللقرآن وما جاء به من الدعوة إلى التوحيد.", "بيان مدى كراهية المشركين للتوحيد وكلمة الإخلاص لا إله إلا الله.", "بيان مدى ما كان عليه المشركون من السخرية والاستهزاء بالرسول والقرآن.", "تنقّل المشركين في اتهاماتهم للرسول ﷺ بالسحر مرة والكهانة ثانية والجنون ثالثة بحثاً عن الخلاص من دعوة التوحيد، فلم يعثروا على شيء."], "k": "«وإذا قرأت القرآن جعلنا بينك وبين الذين لا يؤمنون بالآخرة حجاباً»… هل في قلبي ما يحجبني عن تدبّر ما أقرأ؟"}, {"lbl": "الآيات ٤٩ – ٥٢", "q": "وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمٗا وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقٗا جَدِيدٗا ﴿٤٩﴾ ۞قُلۡ كُونُواْ حِجَارَةً أَوۡ حَدِيدًا ﴿٥٠﴾ أَوۡ خَلۡقٗا مِّمَّا يَكۡبُرُ فِي صُدُورِكُمۡۚ فَسَيَقُولُونَ مَن يُعِيدُنَاۖ قُلِ ٱلَّذِي فَطَرَكُمۡ أَوَّلَ مَرَّةٖۚ فَسَيُنۡغِضُونَ إِلَيۡكَ رُءُوسَهُمۡ وَيَقُولُونَ مَتَىٰ هُوَۖ قُلۡ عَسَىٰٓ أَن يَكُونَ قَرِيبٗا ﴿٥١﴾ يَوۡمَ يَدۡعُوكُمۡ فَتَسۡتَجِيبُونَ بِحَمۡدِهِۦ وَتَظُنُّونَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلٗا ﴿٥٢﴾", "w": [["عظاماً ورفاتاً", "الاستفهام للإنكار والاستبعاد، والرفات: الأجزاء المتفرّقة."], ["مما يكبر في صدوركم", "يعظم عن قبول الحياة في اعتقادكم."], ["فسينغضون", "يحرّكون رؤوسهم تعجّباً."], ["متى هو؟", "الاستفهام للاستهزاء، أي: متى هذا البعث الذي تعدنا؟"], ["يوم يدعوكم", "يناديكم من قبوركم على لسان إسرافيل."], ["فتستجيبون بحمده", "تجيبون دعوته قائلين: سبحانك اللهم وبحمدك."], ["وتظنّون إن لبثتم إلا قليلاً", "تظنّون أنكم ما لبثتم في قبوركم إلا قليلاً."]], "m": "ما زال السياق في تقرير العقيدة، فبعد تقرير التوحيد والوحي يقرّر البعث والجزاء: قال المشركون منكرين: أئذا كنا عظاماً وأجزاء متفرّقة كالحطام أئنا لمبعوثون خلقاً جديداً؟ فأمر رسوله أن يقول لهم: كونوا ما شئتم، حجارة أو حديداً أو خلقاً مما يعظم في نفوسكم أن يقبل الحياة، فإن الله سيحييكم ويبعثكم. فسيقولون: من يعيدنا؟ قل: الذي خلقكم أول مرة، وهو جواب مسكت، فالذي خلقكم ثم أماتكم هو الذي يعيدكم وهو أهون عليه. فسيحرّكون إليك رؤوسهم استهزاءً ويقولون: متى هو؟ قل: عسى أن يكون قريباً، يوم يدعوكم إسرافيل بأمر الله من قبوركم فتجيبونه بحمد الله، وتظنّون أنكم ما لبثتم في قبوركم إلا قليلاً، لما تعاينون من الأهوال المفزعة.", "h": ["تقرير عقيدة البعث والجزاء وبيان حتميّتها.", "بيان ما كان عليه المشركون من شدة إنكارهم للبعث الآخر.", "تعليم الله تعالى لرسوله كيف يجيب المنكرين المستهزئين بالتي هي أحسن.", "بيان الأسلوب الحواري الهادئ الخالي من الغلظة والشدة.", "استقصار مدة اللبث في القبور مع طولها، لما يُشاهد من أهوال البعث."], "k": "«وتظنّون إن لبثتم إلا قليلاً»… عمري كله سيبدو قليلاً؛ فبماذا أملأ ما بقي منه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (191, 17, 53, 60, 'سورة الإسراء ٥٣ – ٦٠', '«وقل لعبادي يقولوا التي هي أحسن»، والذين يدعون يبتغون إلى ربهم الوسيلة، والمانع من إرسال الآيات', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 191) = $j$[{"lbl": "الآيات ٥٣ – ٥٥", "q": "وَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ ٱلشَّيۡطَٰنَ يَنزَغُ بَيۡنَهُمۡۚ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلۡإِنسَٰنِ عَدُوّٗا مُّبِينٗا ﴿٥٣﴾ رَّبُّكُمۡ أَعۡلَمُ بِكُمۡۖ إِن يَشَأۡ يَرۡحَمۡكُمۡ أَوۡ إِن يَشَأۡ يُعَذِّبۡكُمۡۚ وَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ وَكِيلٗا ﴿٥٤﴾ وَرَبُّكَ أَعۡلَمُ بِمَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَلَقَدۡ فَضَّلۡنَا بَعۡضَ ٱلنَّبِيِّـۧنَ عَلَىٰ بَعۡضٖۖ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا ﴿٥٥﴾", "w": [["التي هي أحسن", "الكلمة التي هي أحسن من غيرها للطفها وحسنها."], ["ينزغ", "يفسد بينهم."], ["عدواً مبيناً", "بيّن العداوة ظاهرها."], ["ربكم أعلم بكم", "هذه هي الكلمة التي هي أحسن."], ["وما أرسلناك عليهم وكيلاً", "فيلزمك إجبارهم على الإيمان."], ["فضّلنا بعض النبيين", "بتخصيص كل منهم بفضائل أو فضيلة خاصة به."], ["وآتينا داود زبوراً", "كتاباً هو الزبور، وهذا نوع من التفضيل."]], "m": "ما زال السياق في طلب هداية أهل مكة بطريق الحوار، وحدث أن بعض المؤمنين واجه بعض الكافرين في الجدال بغلظة لفظ، كأن يتوعّده بالنار، فأثار ذلك حفائظهم، فأمر تعالى رسوله أن يقول للمؤمنين: قولوا التي هي أحسن من الكلمات لتجد طريقاً إلى قلوب الكافرين، إن الشيطان يفسد بالوسوسة العلائق التي يمكن التوصّل بها إلى هداية الضالين، وهو عدو بيّن العداوة لا يريد للكافر أن يُسلم ولا للمسلم أن يؤجر في دعوته. ومثال الكلمة الحسنة: ربكم أعلم بكم، إن يشأ يرحمكم فيتوب عليكم، أو إن يشأ يعذبكم، لا أن يحكموا عليهم بأنهم أهل النار فيتمادوا في العناد. وما أرسلناك رقيباً عليهم تجبرهم على الإسلام، وإنما مبلّغاً بالأسلوب الحسن. وربك أعلم بمن في السماوات والأرض وبما يصلحهم وما كُتب لهم من سعادة أو شقاء، فلا تحزنوا على تكذيبهم، ولا تيأسوا من إيمانهم، ولا تتكلّفوا ما لا تطيقون. ولقد فضّلنا بعض النبيين على بعض: إبراهيم بالخلّة، وموسى بالتكليم، وداود بالزبور الحافل بالتسابيح والمواعظ، ومحمداً ﷺ بمغفرة ما تقدّم من ذنبه وما تأخّر وإرساله إلى الناس كافة، فإذا علمتم أن الله أعلم بمن يستحق الهداية والرحمة ففوّضوا الأمر إليه، وادعوا عباده برفق ولين.", "h": ["النهي عن الكلمة الخشنة المسيئة إلى المدعوّ إلى الإسلام.", "بيان أن الشيطان يسعى للإفساد دائماً، فلا يُمكَّن من ذلك بالكلمات المثيرة للغضب والحاملة على اللجاج والخصومة الشديدة.", "بيان نوع الكلمة التي هي أحسن، مثل: «ربكم أعلم بكم إن يشأ يرحمكم أو إن يشأ يعذبكم».", "بيان أن الله تعالى أعلم بخلقه، فهو يهب كل عبد ما أهّله له، حتى إنه فاضل بين أنبيائه ورسله ﵈ في الكمالات الروحية والدرجات العالية."], "k": "«وقل لعبادي يقولوا التي هي أحسن»… في نقاشي القادم، هل أبحث عن الكلمة الأحسن أم الأقسى؟"}, {"lbl": "الآيات ٥٦ – ٦٠", "q": "قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن دُونِهِۦ فَلَا يَمۡلِكُونَ كَشۡفَ ٱلضُّرِّ عَنكُمۡ وَلَا تَحۡوِيلًا ﴿٥٦﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ يَدۡعُونَ يَبۡتَغُونَ إِلَىٰ رَبِّهِمُ ٱلۡوَسِيلَةَ أَيُّهُمۡ أَقۡرَبُ وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحۡذُورٗا ﴿٥٧﴾ وَإِن مِّن قَرۡيَةٍ إِلَّا نَحۡنُ مُهۡلِكُوهَا قَبۡلَ يَوۡمِ ٱلۡقِيَٰمَةِ أَوۡ مُعَذِّبُوهَا عَذَابٗا شَدِيدٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا ﴿٥٨﴾ وَمَا مَنَعَنَآ أَن نُّرۡسِلَ بِٱلۡأٓيَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلۡأَوَّلُونَۚ وَءَاتَيۡنَا ثَمُودَ ٱلنَّاقَةَ مُبۡصِرَةٗ فَظَلَمُواْ بِهَاۚ وَمَا نُرۡسِلُ بِٱلۡأٓيَٰتِ إِلَّا تَخۡوِيفٗا ﴿٥٩﴾ وَإِذۡ قُلۡنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِۚ وَمَا جَعَلۡنَا ٱلرُّءۡيَا ٱلَّتِيٓ أَرَيۡنَٰكَ إِلَّا فِتۡنَةٗ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ فِي ٱلۡقُرۡءَانِۚ وَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنٗا كَبِيرٗا ﴿٦٠﴾", "w": [["فلا يملكون", "لا يستطيعون."], ["كشف الضر", "إزالته بشفاء المريض."], ["ولا تحويلاً", "للمرض من شخص مريض إلى آخر صحيح."], ["يدعون", "ينادونهم طالبين منهم أو متوسّلين بهم."], ["يبتغون إلى ربهم الوسيلة", "يطلبون القرب منه بالطاعات وأنواع القربات."], ["كان محذوراً", "يحذره المؤمنون ويحترسون منه بترك معاصي الله تعالى."], ["في الكتاب مسطوراً", "في كتاب المقادير، اللوح المحفوظ، مكتوباً."], ["أن نرسل بالآيات", "بالآيات التي طلبها أهل مكة، كتحويل الصفا إلى جبل ذهب."], ["إلا أن كذّب بها الأولون", "إذ طالب قوم صالح بالآية، ولما جاءتهم كفروا بها فأهلكهم الله."], ["الناقة مبصرة", "آية واضحة بيّنة."], ["فظلموا بها", "كفروا بها وكذّبوا فأهلكهم الله."], ["إلا تخويفاً", "إلا من أجل تخويف العباد."], ["أحاط بالناس", "قدرةً وعلماً، فهم في قبضته وتحت سلطانه فلا تخفهم."], ["وما جعلنا الرؤيا", "ما رآه الرسول ﷺ ليلة الإسراء والمعراج من عجائب خلق الله."], ["والشجرة الملعونة", "شجرة الزقوم."], ["فما يزيدهم", "التخويف إلا طغياناً وكفراً."]], "m": "ما زال السياق في تقرير التوحيد: قل للمشركين: ادعوا الذين زعمتم أنهم آلهة من دون الله، فإنهم لا يملكون كشف الضر عن مريض ولا تحويله إلى غيره. أولئك الذين يدعونهم من الجن أو الملائكة أو الأنبياء أو الصالحين هم أنفسهم يدعون ربهم ويطلبون القرب منه بأنواع الطاعات، يتنافسون أيّهم أقرب، ويرجون رحمته ويخافون عذابه، فالذي يَعبُد لا يُعبَد، والذي يتقرّب لا يُتقرّب إليه، فكيف يُدعى ويُرجى من هو يدعو ويرجو ويخاف؟ وما من قرية إلا نحن مهلكوها بعذاب إبادة قبل يوم القيامة، أو معذّبوها بمرض أو قحط أو خوف، كان ذلك في اللوح المحفوظ مكتوباً، فلا يستعجل أهل مكة العذاب. وما منعنا أن نرسل بالمعجزات التي طلبوها إلا أن كذّب بها الأولون فأهلكناهم، ولو أرسلناها وكذّبت بها قريش لأهلكناهم، والله يريد هدايتهم ليهتدي على أيديهم خلق كثير. وآتينا ثمود الناقة آية بيّنة فعقروها فظلموا أنفسهم فأُبيدوا، وما نرسل بالآيات إلا تخويفاً من عاقبة الكفر. واذكر إذ قلنا لك: إن ربك أحاط بالناس، فلا تخش منهم أحداً، فإن الله ناصرك. وما جعلنا رؤيا الإسراء والمعراج إلا اختباراً لأهل مكة أيصدّقون أم يكذّبون، وكذا شجرة الزقوم، إذ قالوا: كيف تكون شجرة في النار لا تحرقها؟ قياساً فاسداً للغائب على الشاهد. ونخوّفهم بها وبأنواع العذاب، فما يزيدهم إلا طغياناً كبيراً، فاصبر وامض في دعوتك فإن العاقبة لك.", "h": ["تقرير التوحيد بالحكم على عدم استجابة الآلهة المدّعاة لعابديها.", "دعاء الأولياء والاستغاثة بهم والتوسّل إليهم بالذبح والنذر أمر باطل؛ إذ الأولياء كانوا قبل موتهم يطلبون الوسيلة إلى ربهم بأنواع الطاعات، ومن كان يَعبُد لا يُعبَد، ومن كان يتقرّب لا يُتقرّب إليه، بل يُعبد الذي كان يَعبده، وهو الله سبحانه وتعالى.", "تقرير عقيدة القضاء والقدر.", "بيان المانع من إعطاء الرسول ﷺ الآيات التي طلبتها قريش.", "بيان علّة الإسراء والمعراج، وذكر شجرة الزقوم في القرآن الكريم."], "k": "«يبتغون إلى ربهم الوسيلة أيهم أقرب»… الصالحون أنفسهم يتسابقون إلى الله؛ فبأي قربة أسابقهم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 191;
insert into public.tdb_cards(topic, i, body) select 191, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٣ – ٥٥", "q": "وَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ ٱلشَّيۡطَٰنَ يَنزَغُ بَيۡنَهُمۡۚ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلۡإِنسَٰنِ عَدُوّٗا مُّبِينٗا ﴿٥٣﴾ رَّبُّكُمۡ أَعۡلَمُ بِكُمۡۖ إِن يَشَأۡ يَرۡحَمۡكُمۡ أَوۡ إِن يَشَأۡ يُعَذِّبۡكُمۡۚ وَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ وَكِيلٗا ﴿٥٤﴾ وَرَبُّكَ أَعۡلَمُ بِمَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَلَقَدۡ فَضَّلۡنَا بَعۡضَ ٱلنَّبِيِّـۧنَ عَلَىٰ بَعۡضٖۖ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا ﴿٥٥﴾", "w": [["التي هي أحسن", "الكلمة التي هي أحسن من غيرها للطفها وحسنها."], ["ينزغ", "يفسد بينهم."], ["عدواً مبيناً", "بيّن العداوة ظاهرها."], ["ربكم أعلم بكم", "هذه هي الكلمة التي هي أحسن."], ["وما أرسلناك عليهم وكيلاً", "فيلزمك إجبارهم على الإيمان."], ["فضّلنا بعض النبيين", "بتخصيص كل منهم بفضائل أو فضيلة خاصة به."], ["وآتينا داود زبوراً", "كتاباً هو الزبور، وهذا نوع من التفضيل."]], "m": "ما زال السياق في طلب هداية أهل مكة بطريق الحوار، وحدث أن بعض المؤمنين واجه بعض الكافرين في الجدال بغلظة لفظ، كأن يتوعّده بالنار، فأثار ذلك حفائظهم، فأمر تعالى رسوله أن يقول للمؤمنين: قولوا التي هي أحسن من الكلمات لتجد طريقاً إلى قلوب الكافرين، إن الشيطان يفسد بالوسوسة العلائق التي يمكن التوصّل بها إلى هداية الضالين، وهو عدو بيّن العداوة لا يريد للكافر أن يُسلم ولا للمسلم أن يؤجر في دعوته. ومثال الكلمة الحسنة: ربكم أعلم بكم، إن يشأ يرحمكم فيتوب عليكم، أو إن يشأ يعذبكم، لا أن يحكموا عليهم بأنهم أهل النار فيتمادوا في العناد. وما أرسلناك رقيباً عليهم تجبرهم على الإسلام، وإنما مبلّغاً بالأسلوب الحسن. وربك أعلم بمن في السماوات والأرض وبما يصلحهم وما كُتب لهم من سعادة أو شقاء، فلا تحزنوا على تكذيبهم، ولا تيأسوا من إيمانهم، ولا تتكلّفوا ما لا تطيقون. ولقد فضّلنا بعض النبيين على بعض: إبراهيم بالخلّة، وموسى بالتكليم، وداود بالزبور الحافل بالتسابيح والمواعظ، ومحمداً ﷺ بمغفرة ما تقدّم من ذنبه وما تأخّر وإرساله إلى الناس كافة، فإذا علمتم أن الله أعلم بمن يستحق الهداية والرحمة ففوّضوا الأمر إليه، وادعوا عباده برفق ولين.", "h": ["النهي عن الكلمة الخشنة المسيئة إلى المدعوّ إلى الإسلام.", "بيان أن الشيطان يسعى للإفساد دائماً، فلا يُمكَّن من ذلك بالكلمات المثيرة للغضب والحاملة على اللجاج والخصومة الشديدة.", "بيان نوع الكلمة التي هي أحسن، مثل: «ربكم أعلم بكم إن يشأ يرحمكم أو إن يشأ يعذبكم».", "بيان أن الله تعالى أعلم بخلقه، فهو يهب كل عبد ما أهّله له، حتى إنه فاضل بين أنبيائه ورسله ﵈ في الكمالات الروحية والدرجات العالية."], "k": "«وقل لعبادي يقولوا التي هي أحسن»… في نقاشي القادم، هل أبحث عن الكلمة الأحسن أم الأقسى؟"}, {"lbl": "الآيات ٥٦ – ٦٠", "q": "قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن دُونِهِۦ فَلَا يَمۡلِكُونَ كَشۡفَ ٱلضُّرِّ عَنكُمۡ وَلَا تَحۡوِيلًا ﴿٥٦﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ يَدۡعُونَ يَبۡتَغُونَ إِلَىٰ رَبِّهِمُ ٱلۡوَسِيلَةَ أَيُّهُمۡ أَقۡرَبُ وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحۡذُورٗا ﴿٥٧﴾ وَإِن مِّن قَرۡيَةٍ إِلَّا نَحۡنُ مُهۡلِكُوهَا قَبۡلَ يَوۡمِ ٱلۡقِيَٰمَةِ أَوۡ مُعَذِّبُوهَا عَذَابٗا شَدِيدٗاۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورٗا ﴿٥٨﴾ وَمَا مَنَعَنَآ أَن نُّرۡسِلَ بِٱلۡأٓيَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلۡأَوَّلُونَۚ وَءَاتَيۡنَا ثَمُودَ ٱلنَّاقَةَ مُبۡصِرَةٗ فَظَلَمُواْ بِهَاۚ وَمَا نُرۡسِلُ بِٱلۡأٓيَٰتِ إِلَّا تَخۡوِيفٗا ﴿٥٩﴾ وَإِذۡ قُلۡنَا لَكَ إِنَّ رَبَّكَ أَحَاطَ بِٱلنَّاسِۚ وَمَا جَعَلۡنَا ٱلرُّءۡيَا ٱلَّتِيٓ أَرَيۡنَٰكَ إِلَّا فِتۡنَةٗ لِّلنَّاسِ وَٱلشَّجَرَةَ ٱلۡمَلۡعُونَةَ فِي ٱلۡقُرۡءَانِۚ وَنُخَوِّفُهُمۡ فَمَا يَزِيدُهُمۡ إِلَّا طُغۡيَٰنٗا كَبِيرٗا ﴿٦٠﴾", "w": [["فلا يملكون", "لا يستطيعون."], ["كشف الضر", "إزالته بشفاء المريض."], ["ولا تحويلاً", "للمرض من شخص مريض إلى آخر صحيح."], ["يدعون", "ينادونهم طالبين منهم أو متوسّلين بهم."], ["يبتغون إلى ربهم الوسيلة", "يطلبون القرب منه بالطاعات وأنواع القربات."], ["كان محذوراً", "يحذره المؤمنون ويحترسون منه بترك معاصي الله تعالى."], ["في الكتاب مسطوراً", "في كتاب المقادير، اللوح المحفوظ، مكتوباً."], ["أن نرسل بالآيات", "بالآيات التي طلبها أهل مكة، كتحويل الصفا إلى جبل ذهب."], ["إلا أن كذّب بها الأولون", "إذ طالب قوم صالح بالآية، ولما جاءتهم كفروا بها فأهلكهم الله."], ["الناقة مبصرة", "آية واضحة بيّنة."], ["فظلموا بها", "كفروا بها وكذّبوا فأهلكهم الله."], ["إلا تخويفاً", "إلا من أجل تخويف العباد."], ["أحاط بالناس", "قدرةً وعلماً، فهم في قبضته وتحت سلطانه فلا تخفهم."], ["وما جعلنا الرؤيا", "ما رآه الرسول ﷺ ليلة الإسراء والمعراج من عجائب خلق الله."], ["والشجرة الملعونة", "شجرة الزقوم."], ["فما يزيدهم", "التخويف إلا طغياناً وكفراً."]], "m": "ما زال السياق في تقرير التوحيد: قل للمشركين: ادعوا الذين زعمتم أنهم آلهة من دون الله، فإنهم لا يملكون كشف الضر عن مريض ولا تحويله إلى غيره. أولئك الذين يدعونهم من الجن أو الملائكة أو الأنبياء أو الصالحين هم أنفسهم يدعون ربهم ويطلبون القرب منه بأنواع الطاعات، يتنافسون أيّهم أقرب، ويرجون رحمته ويخافون عذابه، فالذي يَعبُد لا يُعبَد، والذي يتقرّب لا يُتقرّب إليه، فكيف يُدعى ويُرجى من هو يدعو ويرجو ويخاف؟ وما من قرية إلا نحن مهلكوها بعذاب إبادة قبل يوم القيامة، أو معذّبوها بمرض أو قحط أو خوف، كان ذلك في اللوح المحفوظ مكتوباً، فلا يستعجل أهل مكة العذاب. وما منعنا أن نرسل بالمعجزات التي طلبوها إلا أن كذّب بها الأولون فأهلكناهم، ولو أرسلناها وكذّبت بها قريش لأهلكناهم، والله يريد هدايتهم ليهتدي على أيديهم خلق كثير. وآتينا ثمود الناقة آية بيّنة فعقروها فظلموا أنفسهم فأُبيدوا، وما نرسل بالآيات إلا تخويفاً من عاقبة الكفر. واذكر إذ قلنا لك: إن ربك أحاط بالناس، فلا تخش منهم أحداً، فإن الله ناصرك. وما جعلنا رؤيا الإسراء والمعراج إلا اختباراً لأهل مكة أيصدّقون أم يكذّبون، وكذا شجرة الزقوم، إذ قالوا: كيف تكون شجرة في النار لا تحرقها؟ قياساً فاسداً للغائب على الشاهد. ونخوّفهم بها وبأنواع العذاب، فما يزيدهم إلا طغياناً كبيراً، فاصبر وامض في دعوتك فإن العاقبة لك.", "h": ["تقرير التوحيد بالحكم على عدم استجابة الآلهة المدّعاة لعابديها.", "دعاء الأولياء والاستغاثة بهم والتوسّل إليهم بالذبح والنذر أمر باطل؛ إذ الأولياء كانوا قبل موتهم يطلبون الوسيلة إلى ربهم بأنواع الطاعات، ومن كان يَعبُد لا يُعبَد، ومن كان يتقرّب لا يُتقرّب إليه، بل يُعبد الذي كان يَعبده، وهو الله سبحانه وتعالى.", "تقرير عقيدة القضاء والقدر.", "بيان المانع من إعطاء الرسول ﷺ الآيات التي طلبتها قريش.", "بيان علّة الإسراء والمعراج، وذكر شجرة الزقوم في القرآن الكريم."], "k": "«يبتغون إلى ربهم الوسيلة أيهم أقرب»… الصالحون أنفسهم يتسابقون إلى الله؛ فبأي قربة أسابقهم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (192, 17, 61, 70, 'سورة الإسراء ٦١ – ٧٠', 'إبليس: «أأسجد لمن خلقت طيناً»، و«إن عبادي ليس لك عليهم سلطان»، و«ولقد كرّمنا بني آدم»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 192) = $j$[{"lbl": "الآيات ٦١ – ٦٥", "q": "وَإِذۡ قُلۡنَا لِلۡمَلَـٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ قَالَ ءَأَسۡجُدُ لِمَنۡ خَلَقۡتَ طِينٗا ﴿٦١﴾ قَالَ أَرَءَيۡتَكَ هَٰذَا ٱلَّذِي كَرَّمۡتَ عَلَيَّ لَئِنۡ أَخَّرۡتَنِ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَأَحۡتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلٗا ﴿٦٢﴾ قَالَ ٱذۡهَبۡ فَمَن تَبِعَكَ مِنۡهُمۡ فَإِنَّ جَهَنَّمَ جَزَآؤُكُمۡ جَزَآءٗ مَّوۡفُورٗا ﴿٦٣﴾ وَٱسۡتَفۡزِزۡ مَنِ ٱسۡتَطَعۡتَ مِنۡهُم بِصَوۡتِكَ وَأَجۡلِبۡ عَلَيۡهِم بِخَيۡلِكَ وَرَجِلِكَ وَشَارِكۡهُمۡ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِ وَعِدۡهُمۡۚ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا ﴿٦٤﴾ إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٞۚ وَكَفَىٰ بِرَبِّكَ وَكِيلٗا ﴿٦٥﴾", "w": [["لمن خلقت طيناً", "لمن خلقته من الطين."], ["أرأيتك", "أخبرني."], ["كرّمت عليّ", "فضّلته عليّ بالأمر بالسجود له."], ["لأحتنكنّ", "لأستولينّ عليهم فأقودهم إلى الغواية كالدابة إذا جُعل الرسن في حنكها."], ["اذهب", "منظَراً إلى وقت النفخة الأولى."], ["جزاءً موفوراً", "وافراً كاملاً."], ["واستفزز", "واستخفف."], ["بصوتك", "بدعائك إياهم إلى طاعتك ومعصيتي بأصوات المزامير والأغاني."], ["وأجلب عليهم", "صِح فيهم بركبانك ومشاتك."], ["وشاركهم في الأموال", "بحملهم على أكل الربا وتعاطيه."], ["والأولاد", "بتزيين الزنا ودفعهم إليه."], ["وعدهم", "بأن لا بعث ولا حساب ولا جزاء."], ["إلا غروراً", "باطلاً."], ["ليس لك عليهم سلطان", "عبادي المؤمنون ليس لك قوة تتسلّط عليهم بها."], ["وكفى بربك وكيلاً", "حافظاً لهم منك أيها العدو."]], "m": "اذكر لهؤلاء المشركين الذين أطاعوا عدوهم وعدو أبيهم وعصوا ربهم، كيف صدّقوا ظن إبليس فيهم: إذ قلنا للملائكة اسجدوا لآدم فسجدوا إلا إبليس، قال منكراً مستكبراً: أأسجد لمن خلقته من الطين؟ ثم قال في صلفه مستصغراً لآدم: أخبرني، أهذا الذي فضّلته عليّ؟ لئن أخّرت موتي إلى يوم القيامة لأستولينّ على ذريته وأسوقهم إلى أودية الغواية حتى يهلكوا مثلي، إلا قليلاً ممن تستخلصهم لعبادتك. قال: اذهب منظَراً إلى وقت النفخة الأولى، فمن أطاعك منهم وعصاني فإن جهنم جزاؤكم جزاءً وافراً. واستخفف من استطعت منهم بدعائك إلى الباطل بأصوات المزامير والأغاني وصور الملاهي وأنديتها، وصِح عليهم بخيلك ورجلك لإغوائهم، وشاركهم في الأموال بحملهم على الربا وجمع المال من الحرام، وفي الأولاد بتزيين الزنا والفجور، وعدهم بالأماني الكاذبة وأن لا بعث ولا حساب، وما يعدهم الشيطان إلا باطلاً وزوراً. إن عبادي المؤمنين المصدّقين بلقائي ووعدي ووعيدي ليس لك عليهم قوة تتسلّط بها، وكفى بربك حافظاً لهم منك.", "h": ["مشروعية التذكير بالأحداث الماضية للتحذير من الوقوع في الهلاك.", "ذم الكبر، وأنه من شر الصفات.", "تقرير عداوة إبليس والتحذير منها.", "بيان مشاركة إبليس أتباعه في أموالهم وأولادهم ونسائهم.", "بيان أن أصوات الأغاني والمزامير والملاهي وأنديتها وجمعياتها، الجميع من جند إبليس الذي يحارب به الآدمي الضعيف.", "بيان حفظ الله تعالى لأوليائه، وهم المؤمنون المتقون."], "k": "«إن عبادي ليس لك عليهم سلطان وكفى بربك وكيلاً»… هل أحتمي بالعبودية الصادقة من سلطان الشيطان؟"}, {"lbl": "الآيات ٦٦ – ٧٠", "q": "رَّبُّكُمُ ٱلَّذِي يُزۡجِي لَكُمُ ٱلۡفُلۡكَ فِي ٱلۡبَحۡرِ لِتَبۡتَغُواْ مِن فَضۡلِهِۦٓۚ إِنَّهُۥ كَانَ بِكُمۡ رَحِيمٗا ﴿٦٦﴾ وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِي ٱلۡبَحۡرِ ضَلَّ مَن تَدۡعُونَ إِلَّآ إِيَّاهُۖ فَلَمَّا نَجَّىٰكُمۡ إِلَى ٱلۡبَرِّ أَعۡرَضۡتُمۡۚ وَكَانَ ٱلۡإِنسَٰنُ كَفُورًا ﴿٦٧﴾ أَفَأَمِنتُمۡ أَن يَخۡسِفَ بِكُمۡ جَانِبَ ٱلۡبَرِّ أَوۡ يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗا ثُمَّ لَا تَجِدُواْ لَكُمۡ وَكِيلًا ﴿٦٨﴾ أَمۡ أَمِنتُمۡ أَن يُعِيدَكُمۡ فِيهِ تَارَةً أُخۡرَىٰ فَيُرۡسِلَ عَلَيۡكُمۡ قَاصِفٗا مِّنَ ٱلرِّيحِ فَيُغۡرِقَكُم بِمَا كَفَرۡتُمۡ ثُمَّ لَا تَجِدُواْ لَكُمۡ عَلَيۡنَا بِهِۦ تَبِيعٗا ﴿٦٩﴾ ۞وَلَقَدۡ كَرَّمۡنَا بَنِيٓ ءَادَمَ وَحَمَلۡنَٰهُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلۡنَٰهُمۡ عَلَىٰ كَثِيرٖ مِّمَّنۡ خَلَقۡنَا تَفۡضِيلٗا ﴿٧٠﴾", "w": [["يزجي لكم الفلك", "يسوقها فتسير فيه."], ["لتبتغوا من فضله", "لتطلبوا رزق الله بالتجارة من إقليم إلى آخر."], ["وإذا مسّكم الضر", "الشدة والبلاء والخوف من الغرق."], ["ضلّ من تدعون إلا إياه", "غاب عنكم من كنتم تدعونهم من آلهتكم."], ["أعرضتم", "عن دعاء الله وتوحيده."], ["حاصباً", "ريحاً ترمي بالحصباء لشدّتها."], ["ثم لا تجدوا لكم وكيلاً", "حافظاً منه، أي من الخسف أو الريح."], ["قاصفاً من الريح", "ريحاً شديدة تقصف الأشجار وتكسرها لقوّتها."], ["علينا به تبيعاً", "نصيراً ومعيناً يتبعنا ليثأر لكم منا."], ["ولقد كرّمنا بني آدم", "فضّلناهم بالعلم والنطق واعتدال الخلق."], ["وحملناهم في البر والبحر", "في البر على البهائم، وفي البحر على السفن."]], "m": "ما زال السياق في تقرير التوحيد: ربكم الحق الذي يجب أن تعبدوه هو الذي يسوق لكم السفن في البحر لتطلبوا رزقه بالتجارة من إقليم لآخر، أما الأصنام فمخلوقة لا تملك لنفسها نفعاً فضلاً عن غيرها، إنه كان بكم رحيماً. وإذا أصابتكم شدة في البحر، من عواصف تضطرب لها السفن وخفتم الغرق، غاب عنكم كل من تدعون إلا الله، فلما نجّاكم إلى البر أعرضتم عن ذكره وذكرتم آلهتكم، وكان الإنسان كفوراً، هذا طبعه: سرعة النسيان وشدة الكفران. أفأمنتم أن يخسف بكم جانب البر الذي نزلتموه، أو يرسل عليكم ريحاً تحمل الحصباء فيهلككم كما أهلك عاداً، ثم لا تجدون من يدفع عنكم؟ أم أمنتم أن يعيدكم في البحر مرة أخرى فيرسل عليكم ريحاً تقصف الأشجار فيغرقكم بسبب كفركم، ثم لا تجدوا من يثأر لكم منا؟ ولقد كرّمنا بني آدم بالنطق والعقل والعلم واعتدال الخلق، وحملناهم في البر والبحر على ما سخّرنا لهم من المراكب، ورزقناهم من المستلذّات من اللحوم والحبوب والفواكه والمياه العذبة، وفضّلناهم على كثير ممن خلقنا، ومع هذا فإن الآدمي إذا كفر ربه وأشرك به وترك عبادته أصبح شر الخليقة كلها.", "h": ["تعريف الله تعالى بذكر صفاته الفعلية والذاتية.", "تذكير المشركين بحالهم في الشدة والرخاء، حيث يعرفون الله في الشدة ويخلصون له الدعاء، وينكرونه في الرخاء ويشركون به سواه.", "تخويف المشركين بأن الله تعالى قادر على أن يخسف بهم الأرض، أو يرسل عليهم حاصباً من الريح فيهلكهم، أو يردّهم إلى البحر مرة أخرى فيغرقهم بسبب كفرهم وعودتهم إلى الشرك بعد دعائه حال الشدة.", "بيان منن الله تعالى على الإنسان وأفضاله عليه في تكريمه وتفضيله.", "حال الرخاء أصعب على الناس من حال الشدة بالقحط والمرض أو غيرهما من المصائب.", "الإعلان عن كرامة الآدمي وشرفه على سائر المخلوقات الأرضية."], "k": "«فلما نجّاكم إلى البر أعرضتم»… الدعاء الذي ألححت به في شدتي، هل بقيت عليه بعد أن فُرجت؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 192;
insert into public.tdb_cards(topic, i, body) select 192, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦١ – ٦٥", "q": "وَإِذۡ قُلۡنَا لِلۡمَلَـٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ قَالَ ءَأَسۡجُدُ لِمَنۡ خَلَقۡتَ طِينٗا ﴿٦١﴾ قَالَ أَرَءَيۡتَكَ هَٰذَا ٱلَّذِي كَرَّمۡتَ عَلَيَّ لَئِنۡ أَخَّرۡتَنِ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَأَحۡتَنِكَنَّ ذُرِّيَّتَهُۥٓ إِلَّا قَلِيلٗا ﴿٦٢﴾ قَالَ ٱذۡهَبۡ فَمَن تَبِعَكَ مِنۡهُمۡ فَإِنَّ جَهَنَّمَ جَزَآؤُكُمۡ جَزَآءٗ مَّوۡفُورٗا ﴿٦٣﴾ وَٱسۡتَفۡزِزۡ مَنِ ٱسۡتَطَعۡتَ مِنۡهُم بِصَوۡتِكَ وَأَجۡلِبۡ عَلَيۡهِم بِخَيۡلِكَ وَرَجِلِكَ وَشَارِكۡهُمۡ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِ وَعِدۡهُمۡۚ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا ﴿٦٤﴾ إِنَّ عِبَادِي لَيۡسَ لَكَ عَلَيۡهِمۡ سُلۡطَٰنٞۚ وَكَفَىٰ بِرَبِّكَ وَكِيلٗا ﴿٦٥﴾", "w": [["لمن خلقت طيناً", "لمن خلقته من الطين."], ["أرأيتك", "أخبرني."], ["كرّمت عليّ", "فضّلته عليّ بالأمر بالسجود له."], ["لأحتنكنّ", "لأستولينّ عليهم فأقودهم إلى الغواية كالدابة إذا جُعل الرسن في حنكها."], ["اذهب", "منظَراً إلى وقت النفخة الأولى."], ["جزاءً موفوراً", "وافراً كاملاً."], ["واستفزز", "واستخفف."], ["بصوتك", "بدعائك إياهم إلى طاعتك ومعصيتي بأصوات المزامير والأغاني."], ["وأجلب عليهم", "صِح فيهم بركبانك ومشاتك."], ["وشاركهم في الأموال", "بحملهم على أكل الربا وتعاطيه."], ["والأولاد", "بتزيين الزنا ودفعهم إليه."], ["وعدهم", "بأن لا بعث ولا حساب ولا جزاء."], ["إلا غروراً", "باطلاً."], ["ليس لك عليهم سلطان", "عبادي المؤمنون ليس لك قوة تتسلّط عليهم بها."], ["وكفى بربك وكيلاً", "حافظاً لهم منك أيها العدو."]], "m": "اذكر لهؤلاء المشركين الذين أطاعوا عدوهم وعدو أبيهم وعصوا ربهم، كيف صدّقوا ظن إبليس فيهم: إذ قلنا للملائكة اسجدوا لآدم فسجدوا إلا إبليس، قال منكراً مستكبراً: أأسجد لمن خلقته من الطين؟ ثم قال في صلفه مستصغراً لآدم: أخبرني، أهذا الذي فضّلته عليّ؟ لئن أخّرت موتي إلى يوم القيامة لأستولينّ على ذريته وأسوقهم إلى أودية الغواية حتى يهلكوا مثلي، إلا قليلاً ممن تستخلصهم لعبادتك. قال: اذهب منظَراً إلى وقت النفخة الأولى، فمن أطاعك منهم وعصاني فإن جهنم جزاؤكم جزاءً وافراً. واستخفف من استطعت منهم بدعائك إلى الباطل بأصوات المزامير والأغاني وصور الملاهي وأنديتها، وصِح عليهم بخيلك ورجلك لإغوائهم، وشاركهم في الأموال بحملهم على الربا وجمع المال من الحرام، وفي الأولاد بتزيين الزنا والفجور، وعدهم بالأماني الكاذبة وأن لا بعث ولا حساب، وما يعدهم الشيطان إلا باطلاً وزوراً. إن عبادي المؤمنين المصدّقين بلقائي ووعدي ووعيدي ليس لك عليهم قوة تتسلّط بها، وكفى بربك حافظاً لهم منك.", "h": ["مشروعية التذكير بالأحداث الماضية للتحذير من الوقوع في الهلاك.", "ذم الكبر، وأنه من شر الصفات.", "تقرير عداوة إبليس والتحذير منها.", "بيان مشاركة إبليس أتباعه في أموالهم وأولادهم ونسائهم.", "بيان أن أصوات الأغاني والمزامير والملاهي وأنديتها وجمعياتها، الجميع من جند إبليس الذي يحارب به الآدمي الضعيف.", "بيان حفظ الله تعالى لأوليائه، وهم المؤمنون المتقون."], "k": "«إن عبادي ليس لك عليهم سلطان وكفى بربك وكيلاً»… هل أحتمي بالعبودية الصادقة من سلطان الشيطان؟"}, {"lbl": "الآيات ٦٦ – ٧٠", "q": "رَّبُّكُمُ ٱلَّذِي يُزۡجِي لَكُمُ ٱلۡفُلۡكَ فِي ٱلۡبَحۡرِ لِتَبۡتَغُواْ مِن فَضۡلِهِۦٓۚ إِنَّهُۥ كَانَ بِكُمۡ رَحِيمٗا ﴿٦٦﴾ وَإِذَا مَسَّكُمُ ٱلضُّرُّ فِي ٱلۡبَحۡرِ ضَلَّ مَن تَدۡعُونَ إِلَّآ إِيَّاهُۖ فَلَمَّا نَجَّىٰكُمۡ إِلَى ٱلۡبَرِّ أَعۡرَضۡتُمۡۚ وَكَانَ ٱلۡإِنسَٰنُ كَفُورًا ﴿٦٧﴾ أَفَأَمِنتُمۡ أَن يَخۡسِفَ بِكُمۡ جَانِبَ ٱلۡبَرِّ أَوۡ يُرۡسِلَ عَلَيۡكُمۡ حَاصِبٗا ثُمَّ لَا تَجِدُواْ لَكُمۡ وَكِيلًا ﴿٦٨﴾ أَمۡ أَمِنتُمۡ أَن يُعِيدَكُمۡ فِيهِ تَارَةً أُخۡرَىٰ فَيُرۡسِلَ عَلَيۡكُمۡ قَاصِفٗا مِّنَ ٱلرِّيحِ فَيُغۡرِقَكُم بِمَا كَفَرۡتُمۡ ثُمَّ لَا تَجِدُواْ لَكُمۡ عَلَيۡنَا بِهِۦ تَبِيعٗا ﴿٦٩﴾ ۞وَلَقَدۡ كَرَّمۡنَا بَنِيٓ ءَادَمَ وَحَمَلۡنَٰهُمۡ فِي ٱلۡبَرِّ وَٱلۡبَحۡرِ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ وَفَضَّلۡنَٰهُمۡ عَلَىٰ كَثِيرٖ مِّمَّنۡ خَلَقۡنَا تَفۡضِيلٗا ﴿٧٠﴾", "w": [["يزجي لكم الفلك", "يسوقها فتسير فيه."], ["لتبتغوا من فضله", "لتطلبوا رزق الله بالتجارة من إقليم إلى آخر."], ["وإذا مسّكم الضر", "الشدة والبلاء والخوف من الغرق."], ["ضلّ من تدعون إلا إياه", "غاب عنكم من كنتم تدعونهم من آلهتكم."], ["أعرضتم", "عن دعاء الله وتوحيده."], ["حاصباً", "ريحاً ترمي بالحصباء لشدّتها."], ["ثم لا تجدوا لكم وكيلاً", "حافظاً منه، أي من الخسف أو الريح."], ["قاصفاً من الريح", "ريحاً شديدة تقصف الأشجار وتكسرها لقوّتها."], ["علينا به تبيعاً", "نصيراً ومعيناً يتبعنا ليثأر لكم منا."], ["ولقد كرّمنا بني آدم", "فضّلناهم بالعلم والنطق واعتدال الخلق."], ["وحملناهم في البر والبحر", "في البر على البهائم، وفي البحر على السفن."]], "m": "ما زال السياق في تقرير التوحيد: ربكم الحق الذي يجب أن تعبدوه هو الذي يسوق لكم السفن في البحر لتطلبوا رزقه بالتجارة من إقليم لآخر، أما الأصنام فمخلوقة لا تملك لنفسها نفعاً فضلاً عن غيرها، إنه كان بكم رحيماً. وإذا أصابتكم شدة في البحر، من عواصف تضطرب لها السفن وخفتم الغرق، غاب عنكم كل من تدعون إلا الله، فلما نجّاكم إلى البر أعرضتم عن ذكره وذكرتم آلهتكم، وكان الإنسان كفوراً، هذا طبعه: سرعة النسيان وشدة الكفران. أفأمنتم أن يخسف بكم جانب البر الذي نزلتموه، أو يرسل عليكم ريحاً تحمل الحصباء فيهلككم كما أهلك عاداً، ثم لا تجدون من يدفع عنكم؟ أم أمنتم أن يعيدكم في البحر مرة أخرى فيرسل عليكم ريحاً تقصف الأشجار فيغرقكم بسبب كفركم، ثم لا تجدوا من يثأر لكم منا؟ ولقد كرّمنا بني آدم بالنطق والعقل والعلم واعتدال الخلق، وحملناهم في البر والبحر على ما سخّرنا لهم من المراكب، ورزقناهم من المستلذّات من اللحوم والحبوب والفواكه والمياه العذبة، وفضّلناهم على كثير ممن خلقنا، ومع هذا فإن الآدمي إذا كفر ربه وأشرك به وترك عبادته أصبح شر الخليقة كلها.", "h": ["تعريف الله تعالى بذكر صفاته الفعلية والذاتية.", "تذكير المشركين بحالهم في الشدة والرخاء، حيث يعرفون الله في الشدة ويخلصون له الدعاء، وينكرونه في الرخاء ويشركون به سواه.", "تخويف المشركين بأن الله تعالى قادر على أن يخسف بهم الأرض، أو يرسل عليهم حاصباً من الريح فيهلكهم، أو يردّهم إلى البحر مرة أخرى فيغرقهم بسبب كفرهم وعودتهم إلى الشرك بعد دعائه حال الشدة.", "بيان منن الله تعالى على الإنسان وأفضاله عليه في تكريمه وتفضيله.", "حال الرخاء أصعب على الناس من حال الشدة بالقحط والمرض أو غيرهما من المصائب.", "الإعلان عن كرامة الآدمي وشرفه على سائر المخلوقات الأرضية."], "k": "«فلما نجّاكم إلى البر أعرضتم»… الدعاء الذي ألححت به في شدتي، هل بقيت عليه بعد أن فُرجت؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (193, 17, 71, 84, 'سورة الإسراء ٧١ – ٨٤', '«يوم ندعو كل أناس بإمامهم»، ومحاولة فتنة الرسول ﷺ عن الوحي، و«أقم الصلاة لدلوك الشمس»، و«وننزّل من القرآن ما هو شفاء ورحمة»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 193) = $j$[{"lbl": "الآيات ٧١ – ٧٧", "q": "يَوۡمَ نَدۡعُواْ كُلَّ أُنَاسِۭ بِإِمَٰمِهِمۡۖ فَمَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُوْلَـٰٓئِكَ يَقۡرَءُونَ كِتَٰبَهُمۡ وَلَا يُظۡلَمُونَ فَتِيلٗا ﴿٧١﴾ وَمَن كَانَ فِي هَٰذِهِۦٓ أَعۡمَىٰ فَهُوَ فِي ٱلۡأٓخِرَةِ أَعۡمَىٰ وَأَضَلُّ سَبِيلٗا ﴿٧٢﴾ وَإِن كَادُواْ لَيَفۡتِنُونَكَ عَنِ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ لِتَفۡتَرِيَ عَلَيۡنَا غَيۡرَهُۥۖ وَإِذٗا لَّٱتَّخَذُوكَ خَلِيلٗا ﴿٧٣﴾ وَلَوۡلَآ أَن ثَبَّتۡنَٰكَ لَقَدۡ كِدتَّ تَرۡكَنُ إِلَيۡهِمۡ شَيۡـٔٗا قَلِيلًا ﴿٧٤﴾ إِذٗا لَّأَذَقۡنَٰكَ ضِعۡفَ ٱلۡحَيَوٰةِ وَضِعۡفَ ٱلۡمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيۡنَا نَصِيرٗا ﴿٧٥﴾ وَإِن كَادُواْ لَيَسۡتَفِزُّونَكَ مِنَ ٱلۡأَرۡضِ لِيُخۡرِجُوكَ مِنۡهَاۖ وَإِذٗا لَّا يَلۡبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلٗا ﴿٧٦﴾ سُنَّةَ مَن قَدۡ أَرۡسَلۡنَا قَبۡلَكَ مِن رُّسُلِنَاۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحۡوِيلًا ﴿٧٧﴾", "w": [["بإمامهم", "الذي كانوا يقتدون به ويتبعونه في الخير أو الشر."], ["فتيلاً", "مقدار فتيل، وهو الخيط الذي يوجد وسط النواة."], ["ومن كان في هذه أعمى", "من كان في الدنيا أعمى عن حجج الله الدالة على وجوده وعلمه وقدرته فلم يؤمن به، فهو في الآخرة أشد عمى."], ["وإن كادوا", "قاربوا."], ["ليفتنونك", "يستنزلونك عن الحق، أي يطلبون نزولك عنه."], ["لتفتري علينا غيره", "لتقول علينا افتراءً غير الذي أوحينا إليك."], ["إذاً لاتخذوك خليلاً", "لو فعلت الذي طلبوا منك لاتخذوك خليلاً لهم."], ["تركن", "تميل."], ["ضعف الحياة وضعف الممات", "لعذّبناك عذاب الدنيا مضاعفاً، وعذاب الآخرة كذلك."], ["ليستفزّونك من الأرض", "ليستخفّونك من أرض مكة."], ["لا يلبثون خلافك", "لا يبقون بعدك إلا قليلاً ويهلكهم الله."], ["سنّة من قد أرسلنا قبلك", "لو أخرجوك لعذّبناهم بعد خروجك بقليل، سنّتنا في الأمم."], ["ولا تجد لسنّتنا تحويلاً", "عما جرت به في الأمم السابقة."]], "m": "في تقرير البعث والجزاء: اذكر يوم ندعو كل أناس بإمامهم الذي كانوا يتبعونه، فيتقدّم الإمام ووراءه أتباعه، وتوزّع الكتب عليهم، فمن أُعطي كتابه بيمينه تشريفاً له فأولئك يقرءون كتابهم ويحاسبون بما فيه ولا يُنقصون مقدار فتيل. ومن كان في الدنيا أعمى لا يبصر الحجج والآيات وأصرّ على الشرك والمعاصي، فهو في الآخرة أشد عمى وأضلّ سبيلاً، لا يرى طريق النجاة حتى يقع في جهنم. وإن كادوا ليصرفونك عن الذي أوحينا إليك من التوحيد لتقول علينا غيره، ولو وافقتهم على الإغضاء عن شركهم ولو مؤقتاً لاتخذوك خليلاً، وذلك أن المشركين في مكة والطائف واليهود في المدينة كانوا يحاولون أن يستنزلوه ﷺ عن شيء من الحق مكراً وخديعة، إذ لو وافقهم على شيء لطالبوا بآخر، ولقالوا: رجع إلينا، فليس بالذي يوحى إليه. ولولا أن ثبّتناك على الحق بعصمتنا لقد قاربت أن تميل إليهم شيئاً قليلاً، ولو ملت لضاعفنا عليك العذاب في الدنيا والآخرة ثم لا تجد لك نصيراً. ولما فشلوا في المحاولات السلمية أرادوا القوة، فكادوا يستخفّونك من أرض مكة ليخرجوك منها، ولو فعلوا لم يلبثوا بعدك إلا قليلاً ثم نهلكهم، سنّتنا في الأمم التي أخرجت أنبياءها أو قتلتهم، ولا تجد لسنّتنا تحويلاً.", "h": ["الترغيب في الاقتداء بالصالحين ومتابعتهم، والترهيب من الاقتداء بأهل الفساد ومتابعتهم.", "عدالة الله تعالى في الموقف بإقامة الحجة على العبد وعدم ظلمه شيئاً.", "عمى الدنيا عن الحق وشواهده سبب عمى الآخرة وموجباته من السقوط في جهنم.", "حرمة الركون، أي الميل، لأهل الباطل بالتنازل عن شيء من الحق الثابت إرضاءً لهم.", "الوعيد الشديد لمن يرضي أهل الباطل تملّقاً لهم طمعاً في دنياهم فيترك الحق لأجلهم.", "إمضاء سنن الله تعالى وعدم تخلّفها بحال من الأحوال."], "k": "«يوم ندعو كل أناس بإمامهم»… من الذي أقتدي به وأتبعه، وإلى أين يقودني؟"}, {"lbl": "الآيات ٧٨ – ٨٤", "q": "أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمۡسِ إِلَىٰ غَسَقِ ٱلَّيۡلِ وَقُرۡءَانَ ٱلۡفَجۡرِۖ إِنَّ قُرۡءَانَ ٱلۡفَجۡرِ كَانَ مَشۡهُودٗا ﴿٧٨﴾ وَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةٗ لَّكَ عَسَىٰٓ أَن يَبۡعَثَكَ رَبُّكَ مَقَامٗا مَّحۡمُودٗا ﴿٧٩﴾ وَقُل رَّبِّ أَدۡخِلۡنِي مُدۡخَلَ صِدۡقٖ وَأَخۡرِجۡنِي مُخۡرَجَ صِدۡقٖ وَٱجۡعَل لِّي مِن لَّدُنكَ سُلۡطَٰنٗا نَّصِيرٗا ﴿٨٠﴾ وَقُلۡ جَآءَ ٱلۡحَقُّ وَزَهَقَ ٱلۡبَٰطِلُۚ إِنَّ ٱلۡبَٰطِلَ كَانَ زَهُوقٗا ﴿٨١﴾ وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَآءٞ وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ وَلَا يَزِيدُ ٱلظَّـٰلِمِينَ إِلَّا خَسَارٗا ﴿٨٢﴾ وَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ يَـُٔوسٗا ﴿٨٣﴾ قُلۡ كُلّٞ يَعۡمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمۡ أَعۡلَمُ بِمَنۡ هُوَ أَهۡدَىٰ سَبِيلٗا ﴿٨٤﴾", "w": [["لدلوك الشمس", "زوالها من كبد السماء وميلها إلى جهة الغرب."], ["إلى غسق الليل", "إلى ظلمة الليل، إذ الغسق الظلمة."], ["وقرآن الفجر", "صلاة الصبح."], ["كان مشهوداً", "تشهده الملائكة، ملائكة الليل وملائكة النهار."], ["فتهجّد به", "بالقرآن."], ["نافلة", "زائدة عن الفرض، وهي التهجّد بالليل."], ["مقاماً محموداً", "هو الشفاعة العظمى يوم القيامة حيث يحمده الأولون والآخرون."], ["أدخلني مدخل صدق", "المدينة، إدخالاً مرضياً لا أرى فيه مكروهاً."], ["وأخرجني مخرج صدق", "من مكة إخراجاً لا ألتفت بقلبي إليها."], ["وقل جاء الحق وزهق الباطل", "عند دخولك مكة فاتحاً لها بإذن الله تعالى."], ["أعرض ونأى بجانبه", "أعرض عن الشكر فلم يشكر، وثنى عطفه متبختراً في كبرياء."], ["على شاكلته", "طريقته ومذهبه الذي يشاكل حاله في الهدى والضلال."]], "m": "بعد ذلك العرض الهائل أمر رسوله بإقام الصلاة، فإنها أمان الخائفين، ومنار السالكين، ومعراج الأرواح: أقم الصلاة من زوال الشمس، وقت الظهر، إلى ظلمة الليل، فدخلت العصر بينهما، والمغرب والعشاء في الظلمة، وصلاة الصبح، فهذه الصلوات الخمس المفروضة، إن صلاة الفجر تحضرها ملائكة النهار وملائكة الليل، لحديث: «يتعاقبون فيكم ملائكة بالليل وملائكة بالنهار». ومن الليل فتهجّد بالقرآن صلاة زائدة لك، واجبة عليه ﷺ، مندوبة لأمته. عسى ربك أن يقيمك يوم القيامة مقاماً يحمدك عليه الأولون والآخرون، وهو الشفاعة العظمى، حين يتخلّى عنها آدم فمن دونه حتى تنتهي إليه ﷺ فيقول: أنا لها، فيشفع للخليقة في فصل القضاء. وقل في دعائك: رب أدخلني المدينة دار هجرتي إدخالاً لا أرى فيه مكروهاً، وأخرجني من مكة غير ملتفت إليها بقلبي، واجعل لي من لدنك سلطاناً تنصرني به على من بغاني بسوء، وهي بشارة بالإذن بالهجرة. وقل: جاء الحق وزهق الباطل، بشارة بفتح مكة يدخلها منتصراً يكسر الأصنام حول الكعبة وهو يقولها، إن الباطل لا بقاء له إذا صاوله الحق. وننزّل من القرآن ما يُستشفى به من مرض الجهل والضلال والشك والوساوس، ورحمة للمؤمنين لعملهم به، ولا يزيد الظالمين المعاندين إلا خساراً. وإذا أنعمنا على الإنسان الكافر بالنجاة من الهلاك أعرض عن ذكرنا وتباعد بقلبه في كبريائه، وإذا مسّه الشر كان كثير اليأس لعدم إيمانه برحمة الله. قل: كل منا ومنكم يعمل على طريقته، وربكم أعلم بمن هو أهدى سبيلاً، وهذه مفاصلة قاطعة للنزاع.", "h": ["وجوب إقامة الصلاة، وبيان أوقاتها المحدّدة لها.", "الترغيب في النوافل، وخاصة التهجّد، أي نافلة الليل.", "تقرير الشفاعة العظمى للنبي ﷺ.", "ضعف الباطل وسرعة تلاشيه إذا صاوله الحق ووقف في وجهه.", "القرآن شفاء لأمراض القلوب عامة، ورحمة بالمؤمنين خاصة.", "بيان طبع المرء الكافر، وبيان حال الضعف الملازم له.", "تعليم الرسول ﷺ والمؤمنين كيف يتخلّصون من الجدال الفارغ والحوار غير المثمر."], "k": "«ومن الليل فتهجّد به نافلة لك»… ركعتان في جوف الليل؛ متى أبدأ بهما؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 193;
insert into public.tdb_cards(topic, i, body) select 193, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧١ – ٧٧", "q": "يَوۡمَ نَدۡعُواْ كُلَّ أُنَاسِۭ بِإِمَٰمِهِمۡۖ فَمَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ فَأُوْلَـٰٓئِكَ يَقۡرَءُونَ كِتَٰبَهُمۡ وَلَا يُظۡلَمُونَ فَتِيلٗا ﴿٧١﴾ وَمَن كَانَ فِي هَٰذِهِۦٓ أَعۡمَىٰ فَهُوَ فِي ٱلۡأٓخِرَةِ أَعۡمَىٰ وَأَضَلُّ سَبِيلٗا ﴿٧٢﴾ وَإِن كَادُواْ لَيَفۡتِنُونَكَ عَنِ ٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ لِتَفۡتَرِيَ عَلَيۡنَا غَيۡرَهُۥۖ وَإِذٗا لَّٱتَّخَذُوكَ خَلِيلٗا ﴿٧٣﴾ وَلَوۡلَآ أَن ثَبَّتۡنَٰكَ لَقَدۡ كِدتَّ تَرۡكَنُ إِلَيۡهِمۡ شَيۡـٔٗا قَلِيلًا ﴿٧٤﴾ إِذٗا لَّأَذَقۡنَٰكَ ضِعۡفَ ٱلۡحَيَوٰةِ وَضِعۡفَ ٱلۡمَمَاتِ ثُمَّ لَا تَجِدُ لَكَ عَلَيۡنَا نَصِيرٗا ﴿٧٥﴾ وَإِن كَادُواْ لَيَسۡتَفِزُّونَكَ مِنَ ٱلۡأَرۡضِ لِيُخۡرِجُوكَ مِنۡهَاۖ وَإِذٗا لَّا يَلۡبَثُونَ خِلَٰفَكَ إِلَّا قَلِيلٗا ﴿٧٦﴾ سُنَّةَ مَن قَدۡ أَرۡسَلۡنَا قَبۡلَكَ مِن رُّسُلِنَاۖ وَلَا تَجِدُ لِسُنَّتِنَا تَحۡوِيلًا ﴿٧٧﴾", "w": [["بإمامهم", "الذي كانوا يقتدون به ويتبعونه في الخير أو الشر."], ["فتيلاً", "مقدار فتيل، وهو الخيط الذي يوجد وسط النواة."], ["ومن كان في هذه أعمى", "من كان في الدنيا أعمى عن حجج الله الدالة على وجوده وعلمه وقدرته فلم يؤمن به، فهو في الآخرة أشد عمى."], ["وإن كادوا", "قاربوا."], ["ليفتنونك", "يستنزلونك عن الحق، أي يطلبون نزولك عنه."], ["لتفتري علينا غيره", "لتقول علينا افتراءً غير الذي أوحينا إليك."], ["إذاً لاتخذوك خليلاً", "لو فعلت الذي طلبوا منك لاتخذوك خليلاً لهم."], ["تركن", "تميل."], ["ضعف الحياة وضعف الممات", "لعذّبناك عذاب الدنيا مضاعفاً، وعذاب الآخرة كذلك."], ["ليستفزّونك من الأرض", "ليستخفّونك من أرض مكة."], ["لا يلبثون خلافك", "لا يبقون بعدك إلا قليلاً ويهلكهم الله."], ["سنّة من قد أرسلنا قبلك", "لو أخرجوك لعذّبناهم بعد خروجك بقليل، سنّتنا في الأمم."], ["ولا تجد لسنّتنا تحويلاً", "عما جرت به في الأمم السابقة."]], "m": "في تقرير البعث والجزاء: اذكر يوم ندعو كل أناس بإمامهم الذي كانوا يتبعونه، فيتقدّم الإمام ووراءه أتباعه، وتوزّع الكتب عليهم، فمن أُعطي كتابه بيمينه تشريفاً له فأولئك يقرءون كتابهم ويحاسبون بما فيه ولا يُنقصون مقدار فتيل. ومن كان في الدنيا أعمى لا يبصر الحجج والآيات وأصرّ على الشرك والمعاصي، فهو في الآخرة أشد عمى وأضلّ سبيلاً، لا يرى طريق النجاة حتى يقع في جهنم. وإن كادوا ليصرفونك عن الذي أوحينا إليك من التوحيد لتقول علينا غيره، ولو وافقتهم على الإغضاء عن شركهم ولو مؤقتاً لاتخذوك خليلاً، وذلك أن المشركين في مكة والطائف واليهود في المدينة كانوا يحاولون أن يستنزلوه ﷺ عن شيء من الحق مكراً وخديعة، إذ لو وافقهم على شيء لطالبوا بآخر، ولقالوا: رجع إلينا، فليس بالذي يوحى إليه. ولولا أن ثبّتناك على الحق بعصمتنا لقد قاربت أن تميل إليهم شيئاً قليلاً، ولو ملت لضاعفنا عليك العذاب في الدنيا والآخرة ثم لا تجد لك نصيراً. ولما فشلوا في المحاولات السلمية أرادوا القوة، فكادوا يستخفّونك من أرض مكة ليخرجوك منها، ولو فعلوا لم يلبثوا بعدك إلا قليلاً ثم نهلكهم، سنّتنا في الأمم التي أخرجت أنبياءها أو قتلتهم، ولا تجد لسنّتنا تحويلاً.", "h": ["الترغيب في الاقتداء بالصالحين ومتابعتهم، والترهيب من الاقتداء بأهل الفساد ومتابعتهم.", "عدالة الله تعالى في الموقف بإقامة الحجة على العبد وعدم ظلمه شيئاً.", "عمى الدنيا عن الحق وشواهده سبب عمى الآخرة وموجباته من السقوط في جهنم.", "حرمة الركون، أي الميل، لأهل الباطل بالتنازل عن شيء من الحق الثابت إرضاءً لهم.", "الوعيد الشديد لمن يرضي أهل الباطل تملّقاً لهم طمعاً في دنياهم فيترك الحق لأجلهم.", "إمضاء سنن الله تعالى وعدم تخلّفها بحال من الأحوال."], "k": "«يوم ندعو كل أناس بإمامهم»… من الذي أقتدي به وأتبعه، وإلى أين يقودني؟"}, {"lbl": "الآيات ٧٨ – ٨٤", "q": "أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمۡسِ إِلَىٰ غَسَقِ ٱلَّيۡلِ وَقُرۡءَانَ ٱلۡفَجۡرِۖ إِنَّ قُرۡءَانَ ٱلۡفَجۡرِ كَانَ مَشۡهُودٗا ﴿٧٨﴾ وَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةٗ لَّكَ عَسَىٰٓ أَن يَبۡعَثَكَ رَبُّكَ مَقَامٗا مَّحۡمُودٗا ﴿٧٩﴾ وَقُل رَّبِّ أَدۡخِلۡنِي مُدۡخَلَ صِدۡقٖ وَأَخۡرِجۡنِي مُخۡرَجَ صِدۡقٖ وَٱجۡعَل لِّي مِن لَّدُنكَ سُلۡطَٰنٗا نَّصِيرٗا ﴿٨٠﴾ وَقُلۡ جَآءَ ٱلۡحَقُّ وَزَهَقَ ٱلۡبَٰطِلُۚ إِنَّ ٱلۡبَٰطِلَ كَانَ زَهُوقٗا ﴿٨١﴾ وَنُنَزِّلُ مِنَ ٱلۡقُرۡءَانِ مَا هُوَ شِفَآءٞ وَرَحۡمَةٞ لِّلۡمُؤۡمِنِينَ وَلَا يَزِيدُ ٱلظَّـٰلِمِينَ إِلَّا خَسَارٗا ﴿٨٢﴾ وَإِذَآ أَنۡعَمۡنَا عَلَى ٱلۡإِنسَٰنِ أَعۡرَضَ وَنَـَٔا بِجَانِبِهِۦ وَإِذَا مَسَّهُ ٱلشَّرُّ كَانَ يَـُٔوسٗا ﴿٨٣﴾ قُلۡ كُلّٞ يَعۡمَلُ عَلَىٰ شَاكِلَتِهِۦ فَرَبُّكُمۡ أَعۡلَمُ بِمَنۡ هُوَ أَهۡدَىٰ سَبِيلٗا ﴿٨٤﴾", "w": [["لدلوك الشمس", "زوالها من كبد السماء وميلها إلى جهة الغرب."], ["إلى غسق الليل", "إلى ظلمة الليل، إذ الغسق الظلمة."], ["وقرآن الفجر", "صلاة الصبح."], ["كان مشهوداً", "تشهده الملائكة، ملائكة الليل وملائكة النهار."], ["فتهجّد به", "بالقرآن."], ["نافلة", "زائدة عن الفرض، وهي التهجّد بالليل."], ["مقاماً محموداً", "هو الشفاعة العظمى يوم القيامة حيث يحمده الأولون والآخرون."], ["أدخلني مدخل صدق", "المدينة، إدخالاً مرضياً لا أرى فيه مكروهاً."], ["وأخرجني مخرج صدق", "من مكة إخراجاً لا ألتفت بقلبي إليها."], ["وقل جاء الحق وزهق الباطل", "عند دخولك مكة فاتحاً لها بإذن الله تعالى."], ["أعرض ونأى بجانبه", "أعرض عن الشكر فلم يشكر، وثنى عطفه متبختراً في كبرياء."], ["على شاكلته", "طريقته ومذهبه الذي يشاكل حاله في الهدى والضلال."]], "m": "بعد ذلك العرض الهائل أمر رسوله بإقام الصلاة، فإنها أمان الخائفين، ومنار السالكين، ومعراج الأرواح: أقم الصلاة من زوال الشمس، وقت الظهر، إلى ظلمة الليل، فدخلت العصر بينهما، والمغرب والعشاء في الظلمة، وصلاة الصبح، فهذه الصلوات الخمس المفروضة، إن صلاة الفجر تحضرها ملائكة النهار وملائكة الليل، لحديث: «يتعاقبون فيكم ملائكة بالليل وملائكة بالنهار». ومن الليل فتهجّد بالقرآن صلاة زائدة لك، واجبة عليه ﷺ، مندوبة لأمته. عسى ربك أن يقيمك يوم القيامة مقاماً يحمدك عليه الأولون والآخرون، وهو الشفاعة العظمى، حين يتخلّى عنها آدم فمن دونه حتى تنتهي إليه ﷺ فيقول: أنا لها، فيشفع للخليقة في فصل القضاء. وقل في دعائك: رب أدخلني المدينة دار هجرتي إدخالاً لا أرى فيه مكروهاً، وأخرجني من مكة غير ملتفت إليها بقلبي، واجعل لي من لدنك سلطاناً تنصرني به على من بغاني بسوء، وهي بشارة بالإذن بالهجرة. وقل: جاء الحق وزهق الباطل، بشارة بفتح مكة يدخلها منتصراً يكسر الأصنام حول الكعبة وهو يقولها، إن الباطل لا بقاء له إذا صاوله الحق. وننزّل من القرآن ما يُستشفى به من مرض الجهل والضلال والشك والوساوس، ورحمة للمؤمنين لعملهم به، ولا يزيد الظالمين المعاندين إلا خساراً. وإذا أنعمنا على الإنسان الكافر بالنجاة من الهلاك أعرض عن ذكرنا وتباعد بقلبه في كبريائه، وإذا مسّه الشر كان كثير اليأس لعدم إيمانه برحمة الله. قل: كل منا ومنكم يعمل على طريقته، وربكم أعلم بمن هو أهدى سبيلاً، وهذه مفاصلة قاطعة للنزاع.", "h": ["وجوب إقامة الصلاة، وبيان أوقاتها المحدّدة لها.", "الترغيب في النوافل، وخاصة التهجّد، أي نافلة الليل.", "تقرير الشفاعة العظمى للنبي ﷺ.", "ضعف الباطل وسرعة تلاشيه إذا صاوله الحق ووقف في وجهه.", "القرآن شفاء لأمراض القلوب عامة، ورحمة بالمؤمنين خاصة.", "بيان طبع المرء الكافر، وبيان حال الضعف الملازم له.", "تعليم الرسول ﷺ والمؤمنين كيف يتخلّصون من الجدال الفارغ والحوار غير المثمر."], "k": "«ومن الليل فتهجّد به نافلة لك»… ركعتان في جوف الليل؛ متى أبدأ بهما؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (194, 17, 85, 95, 'سورة الإسراء ٨٥ – ٩٥', '«قل الروح من أمر ربي»، وتحدّي الإنس والجن بمثل القرآن، وطلبات المشركين الست، و«هل كنت إلا بشراً رسولاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 194) = $j$[{"lbl": "الآيات ٨٥ – ٨٩", "q": "وَيَسۡـَٔلُونَكَ عَنِ ٱلرُّوحِۖ قُلِ ٱلرُّوحُ مِنۡ أَمۡرِ رَبِّي وَمَآ أُوتِيتُم مِّنَ ٱلۡعِلۡمِ إِلَّا قَلِيلٗا ﴿٨٥﴾ وَلَئِن شِئۡنَا لَنَذۡهَبَنَّ بِٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيۡنَا وَكِيلًا ﴿٨٦﴾ إِلَّا رَحۡمَةٗ مِّن رَّبِّكَۚ إِنَّ فَضۡلَهُۥ كَانَ عَلَيۡكَ كَبِيرٗا ﴿٨٧﴾ قُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٖ ظَهِيرٗا ﴿٨٨﴾ وَلَقَدۡ صَرَّفۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖ فَأَبَىٰٓ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورٗا ﴿٨٩﴾", "w": [["يسألونك عن الروح", "يسألك المشركون، بواسطة أهل الكتاب، عن الروح الذي يحيا به البدن."], ["من أمر ربي", "من شأنه وعلمه الذي استأثر به ولم يعلمه غيره."], ["لنذهبنّ بالذي أوحينا إليك", "القرآن، بأن نمحوه من الصدور والمصاحف."], ["لك به علينا وكيلاً", "يمنع ذلك منا ويحول دون ما أردناه منك."], ["إلا رحمة من ربك", "لكن أبقيناه عليك رحمة من ربك فلم نذهب به."], ["بمثل هذا القرآن", "في فصاحته وبلاغته ومحتواه من الغيوب والشرائع والأحكام."], ["ظهيراً", "معيناً ونصيراً."], ["صرّفنا", "بيّنا للناس مثلاً من جنس كل مثل ليتّعظوا به فيؤمنوا ويوحّدوا."], ["فأبى أكثر الناس إلا كفوراً", "جحوداً للحق وعناداً فيه."]], "m": "سأل المشركون الرسول ﷺ عن الروح، وعن أصحاب الكهف، وذي القرنين، بإيعاز من يهود المدينة، فعلّمه الرد: قل الروح من أمر ربي وعلمه الذي لا يعلمه إلا هو، وما أوتيتم من العلم إلا قليلاً بجانب علم الله، لأن سؤالهم دالّ على ادّعائهم العلم. ولئن شئنا لمحونا القرآن من صدرك وسطره فلا تبقى منه آية، ثم لا تجد من يمنعنا، ولكن رحمة منه تعالى أبقاه إلى قرب قيام الساعة حجةً على عباده وآيةً على نبوة محمد ﷺ، إن فضله كان عليك كبيراً، ومنه عموم رسالته، وكونه خاتم الأنبياء، والعروج به، وإمامته للأنبياء، والشفاعة العظمى، والمقام المحمود. ولما ادّعى بعضهم أن في إمكانه أن يأتي بمثل هذا القرآن، أمره أن يقول: لئن اجتمعت الإنس والجن متعاونين على أن يأتوا بمثله لا يأتون بمثله، لأنه وحي الله وكتابه وحجته على خلقه. ولقد بيّنا في هذا القرآن مثلاً من جنس كل مثل لعلهم يتذكّرون فيؤمنون، فأبى أكثر الناس إلا جحوداً بالحق وتكذيباً به.", "h": ["علم الروح مما استأثر الله تعالى به.", "ما علم أهل العلم إلى علم الله تعالى إلا كما يأخذ الطائر بمنقاره من ماء المحيط.", "حفظ القرآن في الصدور والسطور إلى قرب الساعة.", "عجز الإنس والجن عن الإتيان بقرآن كالقرآن الكريم."], "k": "«وما أوتيتم من العلم إلا قليلاً»… كل ما عرفته قطرة؛ فهل يزيدني علمي تواضعاً؟"}, {"lbl": "الآيات ٩٠ – ٩٥", "q": "وَقَالُواْ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ ٱلۡأَرۡضِ يَنۢبُوعًا ﴿٩٠﴾ أَوۡ تَكُونَ لَكَ جَنَّةٞ مِّن نَّخِيلٖ وَعِنَبٖ فَتُفَجِّرَ ٱلۡأَنۡهَٰرَ خِلَٰلَهَا تَفۡجِيرًا ﴿٩١﴾ أَوۡ تُسۡقِطَ ٱلسَّمَآءَ كَمَا زَعَمۡتَ عَلَيۡنَا كِسَفًا أَوۡ تَأۡتِيَ بِٱللَّهِ وَٱلۡمَلَـٰٓئِكَةِ قَبِيلًا ﴿٩٢﴾ أَوۡ يَكُونَ لَكَ بَيۡتٞ مِّن زُخۡرُفٍ أَوۡ تَرۡقَىٰ فِي ٱلسَّمَآءِ وَلَن نُّؤۡمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيۡنَا كِتَٰبٗا نَّقۡرَؤُهُۥۗ قُلۡ سُبۡحَانَ رَبِّي هَلۡ كُنتُ إِلَّا بَشَرٗا رَّسُولٗا ﴿٩٣﴾ وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤۡمِنُوٓاْ إِذۡ جَآءَهُمُ ٱلۡهُدَىٰٓ إِلَّآ أَن قَالُوٓاْ أَبَعَثَ ٱللَّهُ بَشَرٗا رَّسُولٗا ﴿٩٤﴾ قُل لَّوۡ كَانَ فِي ٱلۡأَرۡضِ مَلَـٰٓئِكَةٞ يَمۡشُونَ مُطۡمَئِنِّينَ لَنَزَّلۡنَا عَلَيۡهِم مِّنَ ٱلسَّمَآءِ مَلَكٗا رَّسُولٗا ﴿٩٥﴾", "w": [["ينبوعاً", "عيناً لا ينضب ماؤها، فهي دائمة الجريان."], ["جنة", "بستان كثير الأشجار."], ["كسفاً", "قطعاً."], ["قبيلاً", "مقابلة لنراهم عياناً."], ["من زخرف", "من ذهب."], ["ترقى", "تصعد في السماء."], ["مطمئنين", "ساكنين في الأرض لا يبرحون منها."]], "m": "ما زال السياق في الدعوة إلى التوحيد والنبوة والبعث، فأخبر عن قول المشركين وهم يجادلون في نبوته ﷺ: لن نتابعك حتى تفجّر لنا من الأرض عيناً يجري ماؤها لا ينقطع، أو تكون لك جنة من نخيل وعنب تتفجّر الأنهار خلالها، أو تسقط السماء علينا قطعاً كما زعمت، أو تأتي بالله والملائكة مقابلة نراهم معاينة، أو يكون لك بيت من ذهب تسكنه، أو تصعد في السماء بسلّم، ولن نصدّق صعودك حتى تنزل علينا كتاباً من عند الله نقرؤه يأمرنا فيه باتباعك. هذه ست طلبات زعموا أنهم يؤمنون متى شاهدوها، والله يعلم أنهم لا يؤمنون، فلم يستجب لهم، وقال لرسوله: قل متعجّباً من طلباتهم: سبحان ربي، هل كنت إلا بشراً رسولاً؟ إن ما تطلبونه لا يقدر عليه عبد مأمور مثلي، وإنما يقدر عليه رب قادر يقول للشيء كن فيكون، وأنا ما ادّعيت ربوبية، وإنما أنا عبد الله ورسوله إليكم. وما منع أهل مكة أن يؤمنوا إذ جاءهم الهدى إلا قولهم منكرين: أبعث الله بشراً رسولاً؟ قل: لو كان في الأرض ملائكة يمشون ساكنين فيها لنزّلنا عليهم من السماء ملكاً رسولاً يفهمون عنه لرابطة الجنس، ولذا بعثنا إليكم رسولاً من جنسكم تفهمون ما يقول، فكيف تنكرون الرسالة للبشر وهي أمر لا بد منه؟", "h": ["تقرير نبوة الرسول ﷺ.", "بيان شدة عناد مشركي قريش وتصلّبهم وتحزّبهم إزاء دعوة التوحيد.", "بيان سخف عقول المشركين برضاهم بالألوهية لحجر وإنكارهم الرسالة للبشر.", "تقرير أن التفاهم حسب سنة الله لا يتم إلا بين المتجانسين، فإذا اختلفت الأجناس فلا تفاهم إلا أن يشاء الله."], "k": "«وما منع الناس أن يؤمنوا إذ جاءهم الهدى»… حين يأتيني الحق من بشر مثلي، هل أطلب له شروطاً قبل أن أتبعه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 194;
insert into public.tdb_cards(topic, i, body) select 194, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٨٥ – ٨٩", "q": "وَيَسۡـَٔلُونَكَ عَنِ ٱلرُّوحِۖ قُلِ ٱلرُّوحُ مِنۡ أَمۡرِ رَبِّي وَمَآ أُوتِيتُم مِّنَ ٱلۡعِلۡمِ إِلَّا قَلِيلٗا ﴿٨٥﴾ وَلَئِن شِئۡنَا لَنَذۡهَبَنَّ بِٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ ثُمَّ لَا تَجِدُ لَكَ بِهِۦ عَلَيۡنَا وَكِيلًا ﴿٨٦﴾ إِلَّا رَحۡمَةٗ مِّن رَّبِّكَۚ إِنَّ فَضۡلَهُۥ كَانَ عَلَيۡكَ كَبِيرٗا ﴿٨٧﴾ قُل لَّئِنِ ٱجۡتَمَعَتِ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَىٰٓ أَن يَأۡتُواْ بِمِثۡلِ هَٰذَا ٱلۡقُرۡءَانِ لَا يَأۡتُونَ بِمِثۡلِهِۦ وَلَوۡ كَانَ بَعۡضُهُمۡ لِبَعۡضٖ ظَهِيرٗا ﴿٨٨﴾ وَلَقَدۡ صَرَّفۡنَا لِلنَّاسِ فِي هَٰذَا ٱلۡقُرۡءَانِ مِن كُلِّ مَثَلٖ فَأَبَىٰٓ أَكۡثَرُ ٱلنَّاسِ إِلَّا كُفُورٗا ﴿٨٩﴾", "w": [["يسألونك عن الروح", "يسألك المشركون، بواسطة أهل الكتاب، عن الروح الذي يحيا به البدن."], ["من أمر ربي", "من شأنه وعلمه الذي استأثر به ولم يعلمه غيره."], ["لنذهبنّ بالذي أوحينا إليك", "القرآن، بأن نمحوه من الصدور والمصاحف."], ["لك به علينا وكيلاً", "يمنع ذلك منا ويحول دون ما أردناه منك."], ["إلا رحمة من ربك", "لكن أبقيناه عليك رحمة من ربك فلم نذهب به."], ["بمثل هذا القرآن", "في فصاحته وبلاغته ومحتواه من الغيوب والشرائع والأحكام."], ["ظهيراً", "معيناً ونصيراً."], ["صرّفنا", "بيّنا للناس مثلاً من جنس كل مثل ليتّعظوا به فيؤمنوا ويوحّدوا."], ["فأبى أكثر الناس إلا كفوراً", "جحوداً للحق وعناداً فيه."]], "m": "سأل المشركون الرسول ﷺ عن الروح، وعن أصحاب الكهف، وذي القرنين، بإيعاز من يهود المدينة، فعلّمه الرد: قل الروح من أمر ربي وعلمه الذي لا يعلمه إلا هو، وما أوتيتم من العلم إلا قليلاً بجانب علم الله، لأن سؤالهم دالّ على ادّعائهم العلم. ولئن شئنا لمحونا القرآن من صدرك وسطره فلا تبقى منه آية، ثم لا تجد من يمنعنا، ولكن رحمة منه تعالى أبقاه إلى قرب قيام الساعة حجةً على عباده وآيةً على نبوة محمد ﷺ، إن فضله كان عليك كبيراً، ومنه عموم رسالته، وكونه خاتم الأنبياء، والعروج به، وإمامته للأنبياء، والشفاعة العظمى، والمقام المحمود. ولما ادّعى بعضهم أن في إمكانه أن يأتي بمثل هذا القرآن، أمره أن يقول: لئن اجتمعت الإنس والجن متعاونين على أن يأتوا بمثله لا يأتون بمثله، لأنه وحي الله وكتابه وحجته على خلقه. ولقد بيّنا في هذا القرآن مثلاً من جنس كل مثل لعلهم يتذكّرون فيؤمنون، فأبى أكثر الناس إلا جحوداً بالحق وتكذيباً به.", "h": ["علم الروح مما استأثر الله تعالى به.", "ما علم أهل العلم إلى علم الله تعالى إلا كما يأخذ الطائر بمنقاره من ماء المحيط.", "حفظ القرآن في الصدور والسطور إلى قرب الساعة.", "عجز الإنس والجن عن الإتيان بقرآن كالقرآن الكريم."], "k": "«وما أوتيتم من العلم إلا قليلاً»… كل ما عرفته قطرة؛ فهل يزيدني علمي تواضعاً؟"}, {"lbl": "الآيات ٩٠ – ٩٥", "q": "وَقَالُواْ لَن نُّؤۡمِنَ لَكَ حَتَّىٰ تَفۡجُرَ لَنَا مِنَ ٱلۡأَرۡضِ يَنۢبُوعًا ﴿٩٠﴾ أَوۡ تَكُونَ لَكَ جَنَّةٞ مِّن نَّخِيلٖ وَعِنَبٖ فَتُفَجِّرَ ٱلۡأَنۡهَٰرَ خِلَٰلَهَا تَفۡجِيرًا ﴿٩١﴾ أَوۡ تُسۡقِطَ ٱلسَّمَآءَ كَمَا زَعَمۡتَ عَلَيۡنَا كِسَفًا أَوۡ تَأۡتِيَ بِٱللَّهِ وَٱلۡمَلَـٰٓئِكَةِ قَبِيلًا ﴿٩٢﴾ أَوۡ يَكُونَ لَكَ بَيۡتٞ مِّن زُخۡرُفٍ أَوۡ تَرۡقَىٰ فِي ٱلسَّمَآءِ وَلَن نُّؤۡمِنَ لِرُقِيِّكَ حَتَّىٰ تُنَزِّلَ عَلَيۡنَا كِتَٰبٗا نَّقۡرَؤُهُۥۗ قُلۡ سُبۡحَانَ رَبِّي هَلۡ كُنتُ إِلَّا بَشَرٗا رَّسُولٗا ﴿٩٣﴾ وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤۡمِنُوٓاْ إِذۡ جَآءَهُمُ ٱلۡهُدَىٰٓ إِلَّآ أَن قَالُوٓاْ أَبَعَثَ ٱللَّهُ بَشَرٗا رَّسُولٗا ﴿٩٤﴾ قُل لَّوۡ كَانَ فِي ٱلۡأَرۡضِ مَلَـٰٓئِكَةٞ يَمۡشُونَ مُطۡمَئِنِّينَ لَنَزَّلۡنَا عَلَيۡهِم مِّنَ ٱلسَّمَآءِ مَلَكٗا رَّسُولٗا ﴿٩٥﴾", "w": [["ينبوعاً", "عيناً لا ينضب ماؤها، فهي دائمة الجريان."], ["جنة", "بستان كثير الأشجار."], ["كسفاً", "قطعاً."], ["قبيلاً", "مقابلة لنراهم عياناً."], ["من زخرف", "من ذهب."], ["ترقى", "تصعد في السماء."], ["مطمئنين", "ساكنين في الأرض لا يبرحون منها."]], "m": "ما زال السياق في الدعوة إلى التوحيد والنبوة والبعث، فأخبر عن قول المشركين وهم يجادلون في نبوته ﷺ: لن نتابعك حتى تفجّر لنا من الأرض عيناً يجري ماؤها لا ينقطع، أو تكون لك جنة من نخيل وعنب تتفجّر الأنهار خلالها، أو تسقط السماء علينا قطعاً كما زعمت، أو تأتي بالله والملائكة مقابلة نراهم معاينة، أو يكون لك بيت من ذهب تسكنه، أو تصعد في السماء بسلّم، ولن نصدّق صعودك حتى تنزل علينا كتاباً من عند الله نقرؤه يأمرنا فيه باتباعك. هذه ست طلبات زعموا أنهم يؤمنون متى شاهدوها، والله يعلم أنهم لا يؤمنون، فلم يستجب لهم، وقال لرسوله: قل متعجّباً من طلباتهم: سبحان ربي، هل كنت إلا بشراً رسولاً؟ إن ما تطلبونه لا يقدر عليه عبد مأمور مثلي، وإنما يقدر عليه رب قادر يقول للشيء كن فيكون، وأنا ما ادّعيت ربوبية، وإنما أنا عبد الله ورسوله إليكم. وما منع أهل مكة أن يؤمنوا إذ جاءهم الهدى إلا قولهم منكرين: أبعث الله بشراً رسولاً؟ قل: لو كان في الأرض ملائكة يمشون ساكنين فيها لنزّلنا عليهم من السماء ملكاً رسولاً يفهمون عنه لرابطة الجنس، ولذا بعثنا إليكم رسولاً من جنسكم تفهمون ما يقول، فكيف تنكرون الرسالة للبشر وهي أمر لا بد منه؟", "h": ["تقرير نبوة الرسول ﷺ.", "بيان شدة عناد مشركي قريش وتصلّبهم وتحزّبهم إزاء دعوة التوحيد.", "بيان سخف عقول المشركين برضاهم بالألوهية لحجر وإنكارهم الرسالة للبشر.", "تقرير أن التفاهم حسب سنة الله لا يتم إلا بين المتجانسين، فإذا اختلفت الأجناس فلا تفاهم إلا أن يشاء الله."], "k": "«وما منع الناس أن يؤمنوا إذ جاءهم الهدى»… حين يأتيني الحق من بشر مثلي، هل أطلب له شروطاً قبل أن أتبعه؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (195, 17, 96, 104, 'سورة الإسراء ٩٦ – ١٠٤', '«ومن يهد الله فهو المهتد»، وحشر المكذّبين على وجوههم، والآيات التسع لموسى ﵇', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 195) = $j$[{"lbl": "الآيات ٩٦ – ٩٩", "q": "قُلۡ كَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا ﴿٩٦﴾ وَمَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن يُضۡلِلۡ فَلَن تَجِدَ لَهُمۡ أَوۡلِيَآءَ مِن دُونِهِۦۖ وَنَحۡشُرُهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡيٗا وَبُكۡمٗا وَصُمّٗاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ كُلَّمَا خَبَتۡ زِدۡنَٰهُمۡ سَعِيرٗا ﴿٩٧﴾ ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمۡ كَفَرُواْ بِـَٔايَٰتِنَا وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمٗا وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقٗا جَدِيدًا ﴿٩٨﴾ ۞أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ قَادِرٌ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۡ وَجَعَلَ لَهُمۡ أَجَلٗا لَّا رَيۡبَ فِيهِ فَأَبَى ٱلظَّـٰلِمُونَ إِلَّا كُفُورٗا ﴿٩٩﴾", "w": [["شهيداً", "على أني رسول الله إليكم وقد بلّغتكم، وعلى أنكم كفرتم وعاندتم."], ["فلن تجد لهم أولياء", "يهدونهم."], ["على وجوههم", "يمشون على وجوههم."], ["عمياً وبكماً وصماً", "لا يبصرون ولا ينطقون ولا يسمعون."], ["كلما خبت", "سكن لهبها."], ["زدناهم سعيراً", "تلهّباً واستعاراً."], ["مثلهم", "أناساً مثلهم."], ["أجلاً", "وقتاً محدّداً."]], "m": "ما زال السياق في تقرير النبوة المحمدية: قل لأولئك المنكرين أن يكون الرسول بشراً: كفى بالله شهيداً بيني وبينكم على أني رسوله، إنه كان بعباده خبيراً بصيراً يعلم المحق من المبطل وسيجزي كلاً بعدله. ومن يهده الله فهو المهتدي بحق، ومن يضلل فلن تجد لهم أولياء من دونه يهدونهم، وفي هذا تسلية للرسول ﷺ في قومه المصرّين. ونحشر المكذّبين الذين ماتوا على ضلالهم يوم القيامة يمشون على وجوههم عمياً لا يبصرون، بكماً لا ينطقون، صماً لا يسمعون، مأواهم جهنم كلما سكن لهبها زادهم الله تلهّباً. ذلك جزاؤهم بسبب كفرهم بآيات الله، وقولهم إنكاراً للبعث: أئذا كنا عظاماً وتراباً أئنا لمبعوثون خلقاً جديداً؟ أولم يروا بعيون قلوبهم أن الذي خلق السماوات والأرض قادر على أن يخلق مثلهم؟ بلى إنه لقادر، وجعل لهم وقتاً معيّناً لهلاكهم لا ريب فيه، فأبى الظالمون مع هذا البيان إلا الجحود والكفران.", "h": ["عظم شهادة الله تعالى ووجوب الاكتفاء بها.", "الهداية والإضلال بيد الله، فيجب طلب الهداية منه والاستعاذة به من الضلال.", "فظاعة عذاب يوم القيامة، إذ يُحشر الظالمون يمشون على وجوههم وهم صمّ بكم عمي، والعياذ بالله تعالى من حال أهل النار.", "جهنم جزاء الكفر بآيات الله والإنكار للبعث والجزاء يوم القيامة.", "دليل البعث عقلي كما هو نقلي، فالقادر على البدء قادر عقلاً على الإعادة، بل الإعادة عقلاً أهون من البدء للخلق من لا شيء."], "k": "«ومن يهد الله فهو المهتد»… الهداية بيده؛ فهل أطلبها منه في كل ركعة بصدق؟"}, {"lbl": "الآيات ١٠٠ – ١٠٤", "q": "قُل لَّوۡ أَنتُمۡ تَمۡلِكُونَ خَزَآئِنَ رَحۡمَةِ رَبِّيٓ إِذٗا لَّأَمۡسَكۡتُمۡ خَشۡيَةَ ٱلۡإِنفَاقِۚ وَكَانَ ٱلۡإِنسَٰنُ قَتُورٗا ﴿١٠٠﴾ وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ تِسۡعَ ءَايَٰتِۭ بَيِّنَٰتٖۖ فَسۡـَٔلۡ بَنِيٓ إِسۡرَـٰٓءِيلَ إِذۡ جَآءَهُمۡ فَقَالَ لَهُۥ فِرۡعَوۡنُ إِنِّي لَأَظُنُّكَ يَٰمُوسَىٰ مَسۡحُورٗا ﴿١٠١﴾ قَالَ لَقَدۡ عَلِمۡتَ مَآ أَنزَلَ هَـٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ بَصَآئِرَ وَإِنِّي لَأَظُنُّكَ يَٰفِرۡعَوۡنُ مَثۡبُورٗا ﴿١٠٢﴾ فَأَرَادَ أَن يَسۡتَفِزَّهُم مِّنَ ٱلۡأَرۡضِ فَأَغۡرَقۡنَٰهُ وَمَن مَّعَهُۥ جَمِيعٗا ﴿١٠٣﴾ وَقُلۡنَا مِنۢ بَعۡدِهِۦ لِبَنِيٓ إِسۡرَـٰٓءِيلَ ٱسۡكُنُواْ ٱلۡأَرۡضَ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ جِئۡنَا بِكُمۡ لَفِيفٗا ﴿١٠٤﴾", "w": [["خزائن رحمة ربي", "من المطر والأرزاق."], ["لأمسكتم", "منعتم الإنفاق."], ["خشية الإنفاق", "خوف النفاد."], ["قتوراً", "كثير الإقتار، أي البخل والمنع للمال."], ["تسع آيات بيّنات", "معجزات واضحات، كاليد والعصا والطمس."], ["مسحوراً", "مغلوباً على عقلك مخدوعاً."], ["ما أنزل هؤلاء", "الآيات التسع."], ["مثبوراً", "هالكاً بانصرافك عن الحق والخير."], ["فأراد أن يستفزّهم", "يستخفّهم ويخرجهم من ديار مصر."], ["اسكنوا الأرض", "أرض القدس والشام."], ["وعد الآخرة", "الساعة."], ["لفيفاً", "مختلطين من أحياء وقبائل شتى."]], "m": "قل لأولئك الذين يطالبون بتحويل الصفا ذهباً وما حول مكة بساتين: لو كنتم تملكون خزائن رحمة ربي من الأموال والأرزاق لأمسكتم بخلاً خوفاً من نفادها، وكان الإنسان قبل هدايته وإيمانه كثير التقتير، حتى يعالج هذا الشح بما وضع الله من دواء جاء بيانه في سورة المعارج. ولقد أعطينا موسى تسع آيات: اليد، والعصا، والسنين، وانفلاق البحر، والطمس على أموال آل فرعون، والطوفان، والجراد، والقمّل، والضفادع، فهل آمن آل فرعون؟ لا، فلو أعطيناك ما طلب قومك ما كانوا ليؤمنوا، فلا فائدة من إعطائك إياها. فاسأل علماء بني إسرائيل كعبد الله بن سلام: إذ جاءهم موسى يطالب فرعون بإرسالهم معه، وأراه الآيات، فقال فرعون: إني لأظنك يا موسى مسحوراً مغلوباً على عقلك. فرد موسى: لقد علمت ما أنزل هؤلاء الآيات إلا رب السماوات والأرض بصائر واضحات هاديات لمن طلب الهداية، فعميت عنها وأنت تعلم صدقها، وإني لأظنك يا فرعون هالكاً. فلما أعيته الحجج لجأ إلى القوة، فأراد أن يستخفّهم من أرض مصر بالقتل أو الطرد، فعامله الله بنقيض قصده فأغرقه وجنوده أجمعين، وقلنا لبني إسرائيل من بعده: اسكنوا أرض القدس والشام، فإذا جاء يوم القيامة جئنا بكم مختلطين من أحياء وقبائل شتى، حفاة عراة، لفصل القضاء.", "h": ["الشح من طبع الإنسان إلا أن يعالجه بالإيمان والتقوى.", "الآيات وحدها لا تكفي لهداية الإنسان، بل لا بد من توفيق إلهي.", "مظاهر قدرة الله تعالى وانتصاره لأوليائه وكبت أعدائه.", "بيان كيفية حشر الناس يوم القيامة."], "k": "«وكان الإنسان قتوراً»… الشحّ طبع؛ فبأي صدقة أعالجه اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 195;
insert into public.tdb_cards(topic, i, body) select 195, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٩٦ – ٩٩", "q": "قُلۡ كَفَىٰ بِٱللَّهِ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرٗا ﴿٩٦﴾ وَمَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن يُضۡلِلۡ فَلَن تَجِدَ لَهُمۡ أَوۡلِيَآءَ مِن دُونِهِۦۖ وَنَحۡشُرُهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ عَلَىٰ وُجُوهِهِمۡ عُمۡيٗا وَبُكۡمٗا وَصُمّٗاۖ مَّأۡوَىٰهُمۡ جَهَنَّمُۖ كُلَّمَا خَبَتۡ زِدۡنَٰهُمۡ سَعِيرٗا ﴿٩٧﴾ ذَٰلِكَ جَزَآؤُهُم بِأَنَّهُمۡ كَفَرُواْ بِـَٔايَٰتِنَا وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمٗا وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقٗا جَدِيدًا ﴿٩٨﴾ ۞أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ قَادِرٌ عَلَىٰٓ أَن يَخۡلُقَ مِثۡلَهُمۡ وَجَعَلَ لَهُمۡ أَجَلٗا لَّا رَيۡبَ فِيهِ فَأَبَى ٱلظَّـٰلِمُونَ إِلَّا كُفُورٗا ﴿٩٩﴾", "w": [["شهيداً", "على أني رسول الله إليكم وقد بلّغتكم، وعلى أنكم كفرتم وعاندتم."], ["فلن تجد لهم أولياء", "يهدونهم."], ["على وجوههم", "يمشون على وجوههم."], ["عمياً وبكماً وصماً", "لا يبصرون ولا ينطقون ولا يسمعون."], ["كلما خبت", "سكن لهبها."], ["زدناهم سعيراً", "تلهّباً واستعاراً."], ["مثلهم", "أناساً مثلهم."], ["أجلاً", "وقتاً محدّداً."]], "m": "ما زال السياق في تقرير النبوة المحمدية: قل لأولئك المنكرين أن يكون الرسول بشراً: كفى بالله شهيداً بيني وبينكم على أني رسوله، إنه كان بعباده خبيراً بصيراً يعلم المحق من المبطل وسيجزي كلاً بعدله. ومن يهده الله فهو المهتدي بحق، ومن يضلل فلن تجد لهم أولياء من دونه يهدونهم، وفي هذا تسلية للرسول ﷺ في قومه المصرّين. ونحشر المكذّبين الذين ماتوا على ضلالهم يوم القيامة يمشون على وجوههم عمياً لا يبصرون، بكماً لا ينطقون، صماً لا يسمعون، مأواهم جهنم كلما سكن لهبها زادهم الله تلهّباً. ذلك جزاؤهم بسبب كفرهم بآيات الله، وقولهم إنكاراً للبعث: أئذا كنا عظاماً وتراباً أئنا لمبعوثون خلقاً جديداً؟ أولم يروا بعيون قلوبهم أن الذي خلق السماوات والأرض قادر على أن يخلق مثلهم؟ بلى إنه لقادر، وجعل لهم وقتاً معيّناً لهلاكهم لا ريب فيه، فأبى الظالمون مع هذا البيان إلا الجحود والكفران.", "h": ["عظم شهادة الله تعالى ووجوب الاكتفاء بها.", "الهداية والإضلال بيد الله، فيجب طلب الهداية منه والاستعاذة به من الضلال.", "فظاعة عذاب يوم القيامة، إذ يُحشر الظالمون يمشون على وجوههم وهم صمّ بكم عمي، والعياذ بالله تعالى من حال أهل النار.", "جهنم جزاء الكفر بآيات الله والإنكار للبعث والجزاء يوم القيامة.", "دليل البعث عقلي كما هو نقلي، فالقادر على البدء قادر عقلاً على الإعادة، بل الإعادة عقلاً أهون من البدء للخلق من لا شيء."], "k": "«ومن يهد الله فهو المهتد»… الهداية بيده؛ فهل أطلبها منه في كل ركعة بصدق؟"}, {"lbl": "الآيات ١٠٠ – ١٠٤", "q": "قُل لَّوۡ أَنتُمۡ تَمۡلِكُونَ خَزَآئِنَ رَحۡمَةِ رَبِّيٓ إِذٗا لَّأَمۡسَكۡتُمۡ خَشۡيَةَ ٱلۡإِنفَاقِۚ وَكَانَ ٱلۡإِنسَٰنُ قَتُورٗا ﴿١٠٠﴾ وَلَقَدۡ ءَاتَيۡنَا مُوسَىٰ تِسۡعَ ءَايَٰتِۭ بَيِّنَٰتٖۖ فَسۡـَٔلۡ بَنِيٓ إِسۡرَـٰٓءِيلَ إِذۡ جَآءَهُمۡ فَقَالَ لَهُۥ فِرۡعَوۡنُ إِنِّي لَأَظُنُّكَ يَٰمُوسَىٰ مَسۡحُورٗا ﴿١٠١﴾ قَالَ لَقَدۡ عَلِمۡتَ مَآ أَنزَلَ هَـٰٓؤُلَآءِ إِلَّا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ بَصَآئِرَ وَإِنِّي لَأَظُنُّكَ يَٰفِرۡعَوۡنُ مَثۡبُورٗا ﴿١٠٢﴾ فَأَرَادَ أَن يَسۡتَفِزَّهُم مِّنَ ٱلۡأَرۡضِ فَأَغۡرَقۡنَٰهُ وَمَن مَّعَهُۥ جَمِيعٗا ﴿١٠٣﴾ وَقُلۡنَا مِنۢ بَعۡدِهِۦ لِبَنِيٓ إِسۡرَـٰٓءِيلَ ٱسۡكُنُواْ ٱلۡأَرۡضَ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ جِئۡنَا بِكُمۡ لَفِيفٗا ﴿١٠٤﴾", "w": [["خزائن رحمة ربي", "من المطر والأرزاق."], ["لأمسكتم", "منعتم الإنفاق."], ["خشية الإنفاق", "خوف النفاد."], ["قتوراً", "كثير الإقتار، أي البخل والمنع للمال."], ["تسع آيات بيّنات", "معجزات واضحات، كاليد والعصا والطمس."], ["مسحوراً", "مغلوباً على عقلك مخدوعاً."], ["ما أنزل هؤلاء", "الآيات التسع."], ["مثبوراً", "هالكاً بانصرافك عن الحق والخير."], ["فأراد أن يستفزّهم", "يستخفّهم ويخرجهم من ديار مصر."], ["اسكنوا الأرض", "أرض القدس والشام."], ["وعد الآخرة", "الساعة."], ["لفيفاً", "مختلطين من أحياء وقبائل شتى."]], "m": "قل لأولئك الذين يطالبون بتحويل الصفا ذهباً وما حول مكة بساتين: لو كنتم تملكون خزائن رحمة ربي من الأموال والأرزاق لأمسكتم بخلاً خوفاً من نفادها، وكان الإنسان قبل هدايته وإيمانه كثير التقتير، حتى يعالج هذا الشح بما وضع الله من دواء جاء بيانه في سورة المعارج. ولقد أعطينا موسى تسع آيات: اليد، والعصا، والسنين، وانفلاق البحر، والطمس على أموال آل فرعون، والطوفان، والجراد، والقمّل، والضفادع، فهل آمن آل فرعون؟ لا، فلو أعطيناك ما طلب قومك ما كانوا ليؤمنوا، فلا فائدة من إعطائك إياها. فاسأل علماء بني إسرائيل كعبد الله بن سلام: إذ جاءهم موسى يطالب فرعون بإرسالهم معه، وأراه الآيات، فقال فرعون: إني لأظنك يا موسى مسحوراً مغلوباً على عقلك. فرد موسى: لقد علمت ما أنزل هؤلاء الآيات إلا رب السماوات والأرض بصائر واضحات هاديات لمن طلب الهداية، فعميت عنها وأنت تعلم صدقها، وإني لأظنك يا فرعون هالكاً. فلما أعيته الحجج لجأ إلى القوة، فأراد أن يستخفّهم من أرض مصر بالقتل أو الطرد، فعامله الله بنقيض قصده فأغرقه وجنوده أجمعين، وقلنا لبني إسرائيل من بعده: اسكنوا أرض القدس والشام، فإذا جاء يوم القيامة جئنا بكم مختلطين من أحياء وقبائل شتى، حفاة عراة، لفصل القضاء.", "h": ["الشح من طبع الإنسان إلا أن يعالجه بالإيمان والتقوى.", "الآيات وحدها لا تكفي لهداية الإنسان، بل لا بد من توفيق إلهي.", "مظاهر قدرة الله تعالى وانتصاره لأوليائه وكبت أعدائه.", "بيان كيفية حشر الناس يوم القيامة."], "k": "«وكان الإنسان قتوراً»… الشحّ طبع؛ فبأي صدقة أعالجه اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (196, 17, 105, 111, 'سورة الإسراء ١٠٥ – ١١١', '«وبالحق أنزلناه وبالحق نزل»، وسجود الذين أوتوا العلم، و«قل الحمد لله الذي لم يتخذ ولداً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 196) = $j$[{"lbl": "الآيات ١٠٥ – ١٠٩", "q": "وَبِٱلۡحَقِّ أَنزَلۡنَٰهُ وَبِٱلۡحَقِّ نَزَلَۗ وَمَآ أَرۡسَلۡنَٰكَ إِلَّا مُبَشِّرٗا وَنَذِيرٗا ﴿١٠٥﴾ وَقُرۡءَانٗا فَرَقۡنَٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثٖ وَنَزَّلۡنَٰهُ تَنزِيلٗا ﴿١٠٦﴾ قُلۡ ءَامِنُواْ بِهِۦٓ أَوۡ لَا تُؤۡمِنُوٓاْۚ إِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مِن قَبۡلِهِۦٓ إِذَا يُتۡلَىٰ عَلَيۡهِمۡ يَخِرُّونَۤ لِلۡأَذۡقَانِۤ سُجَّدٗاۤ ﴿١٠٧﴾ وَيَقُولُونَ سُبۡحَٰنَ رَبِّنَآ إِن كَانَ وَعۡدُ رَبِّنَا لَمَفۡعُولٗا ﴿١٠٨﴾ وَيَخِرُّونَ لِلۡأَذۡقَانِ يَبۡكُونَ وَيَزِيدُهُمۡ خُشُوعٗا۩ ﴿١٠٩﴾", "w": [["وبالحق أنزلناه", "القرآن."], ["وبالحق نزل", "نزل ببيان الحق في العبادات والعقائد والأخبار والمواعظ والأحكام."], ["وقرآناً فرقناه", "أنزلناه مفرّقاً في ظرف ثلاث وعشرين سنة لحكمة اقتضت ذلك."], ["على مكث", "على مهل وتؤدة ليفهمه المستمع إليه."], ["ونزّلناه تنزيلاً", "شيئاً فشيئاً حسب مصالح الأمة لتكمل به وتسعد عليه."], ["الذين أوتوا العلم من قبله", "مؤمنو أهل الكتاب من اليهود والنصارى، كعبد الله بن سلام وسلمان الفارسي."], ["للأذقان سجّداً", "سجّداً على وجوههم، ومن سجد على وجهه فقد خرّ على ذقنه."], ["إن كان وعد ربنا لمفعولاً", "منجزاً واقعاً، فقد أرسل النبي الأمي الذي بشّرت به كتبه وأنزل عليه القرآن."]], "m": "وبالحق الثابت أنزلنا هذا الكتاب الذي جحده الجاحدون، فلا شك أنه كتاب الله ووحيه، وبالحق نزل، فكل ما جاء فيه من عقائد وتشريع وأخبار ووعد ووعيد حق ثابت. وما أرسلناك لخلق الهداية في القلوب ولا لإجبار الناس على الإيمان، وإنما مبشّراً من أطاعنا بالجنة، ونذيراً من عصانا بالنار. وقرآناً فرّقناه في ثلاث وعشرين سنة لتقرأه على الناس على مهل، آيات بعد آيات، ليكون أدعى إلى فهم من يسمعه، ونزّلناه شيئاً فشيئاً حسب ما تتطلبه تربيتهم الروحية ليكملوا به عقولاً وأخلاقاً ويسعدوا في الدارين. قل للمنكرين: آمنوا به أو لا تؤمنوا، فإن إيمانكم كعدمه لا يغيّر من واقعه شيئاً، فهؤلاء الذين أوتوا العلم من قبله من علماء أهل الكتاب، كعبد الله بن سلام وسلمان الفارسي والنجاشي، إذا يُتلى عليهم يخرّون ساجدين على وجوههم ويقولون: سبحان ربنا أن يخلف وعده، إن كان وعد ربنا بإرسال النبي الخاتم وإنزال الكتاب عليه لمنجزاً. ويخرّون للأذقان يبكون، ويزيدهم سماع القرآن خشوعاً في قلوبهم واطمئناناً في جوارحهم لأنه الحق سمعوه من ربهم.", "h": ["القرآن حق من الله، وما نزل به كله حق.", "الندب إلى ترتيل القرآن، لا سيما عند قراءته على الناس لدعوتهم إلى الله تعالى.", "تقرير نزول القرآن مفرّقاً في ثلاث وعشرين سنة.", "تقرير النبوة المحمدية بنزول القرآن وإيمان من آمن به من أهل الكتاب.", "بيان حقيقة السجود، وأنه وضع الوجه على الأرض.", "مشروعية السجود للقارئ أو المستمع وسنيّته عند قراءة هذه الآية: «ويخرّون للأذقان يبكون ويزيدهم خشوعاً»، فيخرّ ساجداً مكبّراً في الخفض والرفع، ويسبّح ويدعو في سجوده بما يشاء."], "k": "«ويخرّون للأذقان يبكون ويزيدهم خشوعاً»… متى آخر مرة أبكتني آية؟"}, {"lbl": "الآيتان ١١٠ – ١١١", "q": "قُلِ ٱدۡعُواْ ٱللَّهَ أَوِ ٱدۡعُواْ ٱلرَّحۡمَٰنَۖ أَيّٗا مَّا تَدۡعُواْ فَلَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ وَلَا تَجۡهَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا وَٱبۡتَغِ بَيۡنَ ذَٰلِكَ سَبِيلٗا ﴿١١٠﴾ وَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ يَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ وَلَمۡ يَكُن لَّهُۥ وَلِيّٞ مِّنَ ٱلذُّلِّۖ وَكَبِّرۡهُ تَكۡبِيرَۢا ﴿١١١﴾", "w": [["ادعوا الله أو ادعوا الرحمن", "سمّوه بأيهما ونادوه بكل واحد منهما."], ["أيّاً ما تدعوا", "إن تدعوه بأيهما فهو حسن، لأن له الأسماء الحسنى."], ["ولا تجهر بصلاتك", "بقراءتك في الصلاة، كراهة أن يسمعها المشركون فيسبّوك ويسبّوا القرآن ومن أنزله."], ["ولا تخافت بها", "لا تسرّ بها إسراراً، حتى ينتفع بقراءتك أصحابك الذين يصلّون وراءك."], ["وابتغ بين ذلك سبيلاً", "اطلب بين السر والجهر طريقاً وسطاً."], ["لم يتخذ ولداً", "كما يقول الكافرون."], ["ولم يكن له شريك", "كما يقول المشركون."], ["ولم يكن له وليّ من الذل", "لم يكن له وليّ ينصره من أجل الذل، إذ هو العزيز الجبار."], ["وكبّره تكبيراً", "عظّمه تعظيماً كاملاً عن اتخاذ الولد والشريك والولي من الذل."]], "m": "كان ﷺ يقول في دعائه: يا الله، يا رحمن، يا رحيم، فسمعه المشركون وهم يتصيّدون له الشبهة، فقالوا: انظروا إليه كيف يدعو إلهين وينهانا عن ذلك! فأنزل الله: قل ادعوا الله أو ادعوا الرحمن، أيّاً ما تدعوا فهو الله ذو الأسماء الحسنى والصفات العلى. ولا تجهر بقراءتك في الصلاة فيسمعها المشركون فيسبّوا القرآن ومن أنزله، ولا تسرّ بها حتى لا يُحرم سماعها من يصلّي وراءك، واطلب بين السر والجهر طريقاً وسطاً. وقل الحمد لله الذي لم يتخذ ولداً، كما زعم بعض العرب: الملائكة بنات الله، واليهود: عزير ابن الله، والنصارى: عيسى ابن الله، ولم يكن له شريك في الملك، كما قال المشركون في تلبيتهم: إلا شريكاً هو لك، تملكه وما ملك، ولم يكن له وليّ من الذل، كما قال الصابئون والمجوس: لولا أولياء الله لذلّ الله! وعظّمه تعظيماً من أن يكون له وصف النقص أو الافتقار أو العجز.", "h": ["إن لله الأسماء الحسنى، وهي مائة اسم إلا اسماً، فيُدعى الله تعالى ويُنادى بأيّها، وكلها حسنى.", "بيان ما كان عليه المشركون في مكة من بغض للرسول والقرآن والمؤمنين.", "مشروعية الأخذ بالاحتياط للدين كما هو للدنيا.", "وجوب حمد الله تعالى والثناء عليه وتنزيهه عن كل عجز ونقص.", "هذه الآية «وقل الحمد لله الذي لم يتخذ ولداً ولم يكن له شريك في الملك ولم يكن له وليّ من الذل» تُسمّى آية العز، هكذا سمّاها رسول الله ﷺ."], "k": "«وقل الحمد لله الذي لم يتخذ ولداً… وكبّره تكبيراً»… أختم يومي بها حمداً وتكبيراً من قلب حاضر."}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 196;
insert into public.tdb_cards(topic, i, body) select 196, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٠٥ – ١٠٩", "q": "وَبِٱلۡحَقِّ أَنزَلۡنَٰهُ وَبِٱلۡحَقِّ نَزَلَۗ وَمَآ أَرۡسَلۡنَٰكَ إِلَّا مُبَشِّرٗا وَنَذِيرٗا ﴿١٠٥﴾ وَقُرۡءَانٗا فَرَقۡنَٰهُ لِتَقۡرَأَهُۥ عَلَى ٱلنَّاسِ عَلَىٰ مُكۡثٖ وَنَزَّلۡنَٰهُ تَنزِيلٗا ﴿١٠٦﴾ قُلۡ ءَامِنُواْ بِهِۦٓ أَوۡ لَا تُؤۡمِنُوٓاْۚ إِنَّ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مِن قَبۡلِهِۦٓ إِذَا يُتۡلَىٰ عَلَيۡهِمۡ يَخِرُّونَۤ لِلۡأَذۡقَانِۤ سُجَّدٗاۤ ﴿١٠٧﴾ وَيَقُولُونَ سُبۡحَٰنَ رَبِّنَآ إِن كَانَ وَعۡدُ رَبِّنَا لَمَفۡعُولٗا ﴿١٠٨﴾ وَيَخِرُّونَ لِلۡأَذۡقَانِ يَبۡكُونَ وَيَزِيدُهُمۡ خُشُوعٗا۩ ﴿١٠٩﴾", "w": [["وبالحق أنزلناه", "القرآن."], ["وبالحق نزل", "نزل ببيان الحق في العبادات والعقائد والأخبار والمواعظ والأحكام."], ["وقرآناً فرقناه", "أنزلناه مفرّقاً في ظرف ثلاث وعشرين سنة لحكمة اقتضت ذلك."], ["على مكث", "على مهل وتؤدة ليفهمه المستمع إليه."], ["ونزّلناه تنزيلاً", "شيئاً فشيئاً حسب مصالح الأمة لتكمل به وتسعد عليه."], ["الذين أوتوا العلم من قبله", "مؤمنو أهل الكتاب من اليهود والنصارى، كعبد الله بن سلام وسلمان الفارسي."], ["للأذقان سجّداً", "سجّداً على وجوههم، ومن سجد على وجهه فقد خرّ على ذقنه."], ["إن كان وعد ربنا لمفعولاً", "منجزاً واقعاً، فقد أرسل النبي الأمي الذي بشّرت به كتبه وأنزل عليه القرآن."]], "m": "وبالحق الثابت أنزلنا هذا الكتاب الذي جحده الجاحدون، فلا شك أنه كتاب الله ووحيه، وبالحق نزل، فكل ما جاء فيه من عقائد وتشريع وأخبار ووعد ووعيد حق ثابت. وما أرسلناك لخلق الهداية في القلوب ولا لإجبار الناس على الإيمان، وإنما مبشّراً من أطاعنا بالجنة، ونذيراً من عصانا بالنار. وقرآناً فرّقناه في ثلاث وعشرين سنة لتقرأه على الناس على مهل، آيات بعد آيات، ليكون أدعى إلى فهم من يسمعه، ونزّلناه شيئاً فشيئاً حسب ما تتطلبه تربيتهم الروحية ليكملوا به عقولاً وأخلاقاً ويسعدوا في الدارين. قل للمنكرين: آمنوا به أو لا تؤمنوا، فإن إيمانكم كعدمه لا يغيّر من واقعه شيئاً، فهؤلاء الذين أوتوا العلم من قبله من علماء أهل الكتاب، كعبد الله بن سلام وسلمان الفارسي والنجاشي، إذا يُتلى عليهم يخرّون ساجدين على وجوههم ويقولون: سبحان ربنا أن يخلف وعده، إن كان وعد ربنا بإرسال النبي الخاتم وإنزال الكتاب عليه لمنجزاً. ويخرّون للأذقان يبكون، ويزيدهم سماع القرآن خشوعاً في قلوبهم واطمئناناً في جوارحهم لأنه الحق سمعوه من ربهم.", "h": ["القرآن حق من الله، وما نزل به كله حق.", "الندب إلى ترتيل القرآن، لا سيما عند قراءته على الناس لدعوتهم إلى الله تعالى.", "تقرير نزول القرآن مفرّقاً في ثلاث وعشرين سنة.", "تقرير النبوة المحمدية بنزول القرآن وإيمان من آمن به من أهل الكتاب.", "بيان حقيقة السجود، وأنه وضع الوجه على الأرض.", "مشروعية السجود للقارئ أو المستمع وسنيّته عند قراءة هذه الآية: «ويخرّون للأذقان يبكون ويزيدهم خشوعاً»، فيخرّ ساجداً مكبّراً في الخفض والرفع، ويسبّح ويدعو في سجوده بما يشاء."], "k": "«ويخرّون للأذقان يبكون ويزيدهم خشوعاً»… متى آخر مرة أبكتني آية؟"}, {"lbl": "الآيتان ١١٠ – ١١١", "q": "قُلِ ٱدۡعُواْ ٱللَّهَ أَوِ ٱدۡعُواْ ٱلرَّحۡمَٰنَۖ أَيّٗا مَّا تَدۡعُواْ فَلَهُ ٱلۡأَسۡمَآءُ ٱلۡحُسۡنَىٰۚ وَلَا تَجۡهَرۡ بِصَلَاتِكَ وَلَا تُخَافِتۡ بِهَا وَٱبۡتَغِ بَيۡنَ ذَٰلِكَ سَبِيلٗا ﴿١١٠﴾ وَقُلِ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي لَمۡ يَتَّخِذۡ وَلَدٗا وَلَمۡ يَكُن لَّهُۥ شَرِيكٞ فِي ٱلۡمُلۡكِ وَلَمۡ يَكُن لَّهُۥ وَلِيّٞ مِّنَ ٱلذُّلِّۖ وَكَبِّرۡهُ تَكۡبِيرَۢا ﴿١١١﴾", "w": [["ادعوا الله أو ادعوا الرحمن", "سمّوه بأيهما ونادوه بكل واحد منهما."], ["أيّاً ما تدعوا", "إن تدعوه بأيهما فهو حسن، لأن له الأسماء الحسنى."], ["ولا تجهر بصلاتك", "بقراءتك في الصلاة، كراهة أن يسمعها المشركون فيسبّوك ويسبّوا القرآن ومن أنزله."], ["ولا تخافت بها", "لا تسرّ بها إسراراً، حتى ينتفع بقراءتك أصحابك الذين يصلّون وراءك."], ["وابتغ بين ذلك سبيلاً", "اطلب بين السر والجهر طريقاً وسطاً."], ["لم يتخذ ولداً", "كما يقول الكافرون."], ["ولم يكن له شريك", "كما يقول المشركون."], ["ولم يكن له وليّ من الذل", "لم يكن له وليّ ينصره من أجل الذل، إذ هو العزيز الجبار."], ["وكبّره تكبيراً", "عظّمه تعظيماً كاملاً عن اتخاذ الولد والشريك والولي من الذل."]], "m": "كان ﷺ يقول في دعائه: يا الله، يا رحمن، يا رحيم، فسمعه المشركون وهم يتصيّدون له الشبهة، فقالوا: انظروا إليه كيف يدعو إلهين وينهانا عن ذلك! فأنزل الله: قل ادعوا الله أو ادعوا الرحمن، أيّاً ما تدعوا فهو الله ذو الأسماء الحسنى والصفات العلى. ولا تجهر بقراءتك في الصلاة فيسمعها المشركون فيسبّوا القرآن ومن أنزله، ولا تسرّ بها حتى لا يُحرم سماعها من يصلّي وراءك، واطلب بين السر والجهر طريقاً وسطاً. وقل الحمد لله الذي لم يتخذ ولداً، كما زعم بعض العرب: الملائكة بنات الله، واليهود: عزير ابن الله، والنصارى: عيسى ابن الله، ولم يكن له شريك في الملك، كما قال المشركون في تلبيتهم: إلا شريكاً هو لك، تملكه وما ملك، ولم يكن له وليّ من الذل، كما قال الصابئون والمجوس: لولا أولياء الله لذلّ الله! وعظّمه تعظيماً من أن يكون له وصف النقص أو الافتقار أو العجز.", "h": ["إن لله الأسماء الحسنى، وهي مائة اسم إلا اسماً، فيُدعى الله تعالى ويُنادى بأيّها، وكلها حسنى.", "بيان ما كان عليه المشركون في مكة من بغض للرسول والقرآن والمؤمنين.", "مشروعية الأخذ بالاحتياط للدين كما هو للدنيا.", "وجوب حمد الله تعالى والثناء عليه وتنزيهه عن كل عجز ونقص.", "هذه الآية «وقل الحمد لله الذي لم يتخذ ولداً ولم يكن له شريك في الملك ولم يكن له وليّ من الذل» تُسمّى آية العز، هكذا سمّاها رسول الله ﷺ."], "k": "«وقل الحمد لله الذي لم يتخذ ولداً… وكبّره تكبيراً»… أختم يومي بها حمداً وتكبيراً من قلب حاضر."}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (197, 18, 1, 12, 'سورة الكهف ١ – ١٢', '«الحمد لله الذي أنزل على عبده الكتاب ولم يجعل له عوجاً»، وزينة الأرض للابتلاء، وإيواء الفتية إلى الكهف', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 197) = $j$[{"lbl": "الآيات ١ – ٦", "q": "ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَنزَلَ عَلَىٰ عَبۡدِهِ ٱلۡكِتَٰبَ وَلَمۡ يَجۡعَل لَّهُۥ عِوَجَاۜ ﴿١﴾ قَيِّمٗا لِّيُنذِرَ بَأۡسٗا شَدِيدٗا مِّن لَّدُنۡهُ وَيُبَشِّرَ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّـٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرًا حَسَنٗا ﴿٢﴾ مَّـٰكِثِينَ فِيهِ أَبَدٗا ﴿٣﴾ وَيُنذِرَ ٱلَّذِينَ قَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗا ﴿٤﴾ مَّا لَهُم بِهِۦ مِنۡ عِلۡمٖ وَلَا لِأٓبَآئِهِمۡۚ كَبُرَتۡ كَلِمَةٗ تَخۡرُجُ مِنۡ أَفۡوَٰهِهِمۡۚ إِن يَقُولُونَ إِلَّا كَذِبٗا ﴿٥﴾ فَلَعَلَّكَ بَٰخِعٞ نَّفۡسَكَ عَلَىٰٓ ءَاثَٰرِهِمۡ إِن لَّمۡ يُؤۡمِنُواْ بِهَٰذَا ٱلۡحَدِيثِ أَسَفًا ﴿٦﴾", "w": [["الحمد لله", "الحمد: الوصف بالجميل، والله: علم على ذات الرب تعالى."], ["الكتاب", "القرآن الكريم."], ["ولم يجعل له عوجاً", "ميلاً عن الحق والاعتدال في ألفاظه ومعانيه."], ["قيّماً", "ذا اعتدال لا إفراط فيه ولا تفريط في كل ما حواه ودعا إليه من التوحيد والعبادة والآداب والشرائع والأحكام."], ["بأساً شديداً", "عذاباً ذا شدة وقسوة."], ["من لدنه", "من عنده سبحانه وتعالى."], ["أجراً حسناً", "الجنة، إذ هي أجر المؤمنين العاملين بالصالحات."], ["كبرت كلمة", "عظمت فرية، وهي قولهم: الملائكة بنات الله."], ["إن يقولون إلا كذباً", "ما يقولون إلا كذباً بحتاً لا واقع له في الخارج."], ["باخع نفسك", "قاتل نفسك."], ["بهذا الحديث أسفاً", "بالقرآن، من أجل الأسف الذي هو الحزن الشديد."]], "m": "يخبر تعالى في فاتحة سورة الكهف أنه المستحق للحمد، ويذكر موجبه: إنزاله على عبده ورسوله محمد ﷺ الكتاب العظيم، ولم يجعل له ميلاً عن الحق في ألفاظه ومعانيه، فهو كلام مستقيم محقّق للآخذ به كل سعادة وكمال، قيّماً معتدلاً خالياً من الإفراط والتفريط، مهيمناً على الكتب السابقة. أنزله لينذر أهل الشرك والمعاصي عذاباً شديداً من عند ربهم، ويبشّر المؤمنين الذين يعملون الصالحات أن لهم جنات ماكثين فيها أبداً، وينذر بصورة خاصة الذين قالوا: اتخذ الله ولداً، من اليهود والنصارى وبعض مشركي العرب، وهو قول توارثوه لا علم لأحد منهم به، عظمت كلمة تخرج من أفواههم لا غير، إذ لا واقع لها أبداً، ما يقولون إلا الكذب البحت. فلعلك يا رسولنا قاتل نفسك حزناً على إثر رفض قومك الإيمان بهذا القرآن! يعاتبه ربه ويخفّف عنه: فلا تفعل، واصبر لحكم ربك فإنه منجز وعده لك بالنصر.", "h": ["وجوب حمد الله تعالى على آلائه وعظيم نعمه.", "لا يُحمد إلا من له ما يقتضي حمده، وإلا كان المدح كذباً وزوراً.", "عظم شأن القرآن الكريم وسلامته من الإفراط والتفريط والانحراف في كل ما جاء به.", "بيان مهمة القرآن، وهي البشارة لأهل الإيمان والإنذار لأهل الشرك والكفران.", "التنديد بالكذب على الله ونسبة ما لا يليق بجلاله وكماله إليه كالولد ونحوه.", "تحريم الانتحار وقتل النفس من الحزن أو الخوف ونحوه من الغضب والحرمان."], "k": "«الحمد لله الذي أنزل على عبده الكتاب»… أعظم نعمة بين يديّ هذا الكتاب؛ فهل أحمد الله عليه بتلاوته والعمل به؟"}, {"lbl": "الآيات ٧ – ١٢", "q": "إِنَّا جَعَلۡنَا مَا عَلَى ٱلۡأَرۡضِ زِينَةٗ لَّهَا لِنَبۡلُوَهُمۡ أَيُّهُمۡ أَحۡسَنُ عَمَلٗا ﴿٧﴾ وَإِنَّا لَجَٰعِلُونَ مَا عَلَيۡهَا صَعِيدٗا جُرُزًا ﴿٨﴾ أَمۡ حَسِبۡتَ أَنَّ أَصۡحَٰبَ ٱلۡكَهۡفِ وَٱلرَّقِيمِ كَانُواْ مِنۡ ءَايَٰتِنَا عَجَبًا ﴿٩﴾ إِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا ﴿١٠﴾ فَضَرَبۡنَا عَلَىٰٓ ءَاذَانِهِمۡ فِي ٱلۡكَهۡفِ سِنِينَ عَدَدٗا ﴿١١﴾ ثُمَّ بَعَثۡنَٰهُمۡ لِنَعۡلَمَ أَيُّ ٱلۡحِزۡبَيۡنِ أَحۡصَىٰ لِمَا لَبِثُوٓاْ أَمَدٗا ﴿١٢﴾", "w": [["زينة لها", "من حيوان وأشجار ونبات وأنهار وبحار."], ["لنبلوهم", "لنختبرهم."], ["صعيداً جرزاً", "تراباً لا نبات فيه."], ["الكهف", "النقب الواسع في الجبل، والضيّق منه يقال له غار."], ["والرقيم", "لوح حجري رُقمت فيه أسماء أصحاب الكهف."], ["أوى الفتية إلى الكهف", "اتخذوه مأوى لهم ومنزلاً نزلوا فيه."], ["الفتية", "جمع فتى، وهم شبان مؤمنون."], ["وهيّئ لنا من أمرنا رشداً", "يسّر لنا طريق رشد وهداية."], ["فضربنا على آذانهم", "ضربنا على آذانهم حجاباً يمنعهم من سماع الأصوات."], ["سنين عدداً", "أعواماً عدّة."], ["ثم بعثناهم", "أيقظناهم من نومهم."], ["أحصى لما لبثوا", "أضبط لأوقات لبثهم في الكهف."], ["أمداً", "مدة محدودة معلومة."]], "m": "إنا جعلنا ما على الأرض من حيوان وأشجار وأنهار زينة لها لنختبر الناس أيّهم أترك لها وأعمل فيها بطاعتنا، وإنا لمخرّبوها يوماً بعد عمارتها فنجعلها تراباً لا نبات فيه، فلا تحزن يا رسولنا مما تلقاه من قومك، فإن مآل الحياة التي من أجلها عادوك إلى أن تصبح صعيداً جرزاً. أظننت أن أصحاب الكهف والرقيم، اللوح الذي رُقمت فيه أسماؤهم وقصتهم، كانوا أعجب آياتنا؟ بل من مخلوقات الله ما هو أعجب بكثير. ثم شرع في قصتهم: اذكر للسائلين إذ أوى الفتية، سبعة شبان ومعهم كلب لهم، إلى الغار هروباً من قومهم الكفار أن يفتنوهم في دينهم، فقالوا: ربنا أعطنا من عندك رحمة تصحبنا في هجرتنا هذه، ويسّر لنا من أمرنا سداداً ونجاة من أهل الكفر. قال ابن جرير: كانوا مسلمين على دين عيسى، وكان لهم ملك عابد وثن دعاهم إلى عبادة الأصنام فهربوا بدينهم. فضربنا على آذانهم حجاباً يمنعهم من سماع الأصوات فناموا سنين معدودة، ثلاثمائة وتسع سنين، استجابة لدعائهم، ثم أيقظناهم لنعلم علم مشاهدة، ويعلم عبادي، أي الحزبين اللذين اختلفا في مدة لبثهم كان أضبط لها.", "h": ["بيان العلة في وجود الزينة على هذه الأرض، وهي الابتلاء والاختبار للناس، ليظهر الزاهد فيها العارف بتفاهتها وسرعة زوالها، وليظهر الراغب فيها المتكالب عليها.", "تقرير فناء كل ما على الأرض حتى تبقى صعيداً جرزاً وقاعاً صفصفاً.", "تقرير نبوة الرسول ﷺ بإجابة السائلين عن أصحاب الكهف بالإيجاز والتفصيل.", "تقرير التوحيد ضمن قصة أصحاب الكهف، إذ فرّوا بدينهم خوفاً من الشرك والكفر.", "استجابة الله دعاء عباده المؤمنين الموحّدين، حيث استجاب للفتية فآواهم الغار ورعاهم حتى بعثهم بعد تغيّر الأحوال وتبدّل العباد والبلاد."], "k": "«ربنا آتنا من لدنك رحمة وهيّئ لنا من أمرنا رشداً»… أي أمر في حياتي أحتاج أن أدعو له بهذا الدعاء الليلة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 197;
insert into public.tdb_cards(topic, i, body) select 197, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٦", "q": "ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِيٓ أَنزَلَ عَلَىٰ عَبۡدِهِ ٱلۡكِتَٰبَ وَلَمۡ يَجۡعَل لَّهُۥ عِوَجَاۜ ﴿١﴾ قَيِّمٗا لِّيُنذِرَ بَأۡسٗا شَدِيدٗا مِّن لَّدُنۡهُ وَيُبَشِّرَ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّـٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرًا حَسَنٗا ﴿٢﴾ مَّـٰكِثِينَ فِيهِ أَبَدٗا ﴿٣﴾ وَيُنذِرَ ٱلَّذِينَ قَالُواْ ٱتَّخَذَ ٱللَّهُ وَلَدٗا ﴿٤﴾ مَّا لَهُم بِهِۦ مِنۡ عِلۡمٖ وَلَا لِأٓبَآئِهِمۡۚ كَبُرَتۡ كَلِمَةٗ تَخۡرُجُ مِنۡ أَفۡوَٰهِهِمۡۚ إِن يَقُولُونَ إِلَّا كَذِبٗا ﴿٥﴾ فَلَعَلَّكَ بَٰخِعٞ نَّفۡسَكَ عَلَىٰٓ ءَاثَٰرِهِمۡ إِن لَّمۡ يُؤۡمِنُواْ بِهَٰذَا ٱلۡحَدِيثِ أَسَفًا ﴿٦﴾", "w": [["الحمد لله", "الحمد: الوصف بالجميل، والله: علم على ذات الرب تعالى."], ["الكتاب", "القرآن الكريم."], ["ولم يجعل له عوجاً", "ميلاً عن الحق والاعتدال في ألفاظه ومعانيه."], ["قيّماً", "ذا اعتدال لا إفراط فيه ولا تفريط في كل ما حواه ودعا إليه من التوحيد والعبادة والآداب والشرائع والأحكام."], ["بأساً شديداً", "عذاباً ذا شدة وقسوة."], ["من لدنه", "من عنده سبحانه وتعالى."], ["أجراً حسناً", "الجنة، إذ هي أجر المؤمنين العاملين بالصالحات."], ["كبرت كلمة", "عظمت فرية، وهي قولهم: الملائكة بنات الله."], ["إن يقولون إلا كذباً", "ما يقولون إلا كذباً بحتاً لا واقع له في الخارج."], ["باخع نفسك", "قاتل نفسك."], ["بهذا الحديث أسفاً", "بالقرآن، من أجل الأسف الذي هو الحزن الشديد."]], "m": "يخبر تعالى في فاتحة سورة الكهف أنه المستحق للحمد، ويذكر موجبه: إنزاله على عبده ورسوله محمد ﷺ الكتاب العظيم، ولم يجعل له ميلاً عن الحق في ألفاظه ومعانيه، فهو كلام مستقيم محقّق للآخذ به كل سعادة وكمال، قيّماً معتدلاً خالياً من الإفراط والتفريط، مهيمناً على الكتب السابقة. أنزله لينذر أهل الشرك والمعاصي عذاباً شديداً من عند ربهم، ويبشّر المؤمنين الذين يعملون الصالحات أن لهم جنات ماكثين فيها أبداً، وينذر بصورة خاصة الذين قالوا: اتخذ الله ولداً، من اليهود والنصارى وبعض مشركي العرب، وهو قول توارثوه لا علم لأحد منهم به، عظمت كلمة تخرج من أفواههم لا غير، إذ لا واقع لها أبداً، ما يقولون إلا الكذب البحت. فلعلك يا رسولنا قاتل نفسك حزناً على إثر رفض قومك الإيمان بهذا القرآن! يعاتبه ربه ويخفّف عنه: فلا تفعل، واصبر لحكم ربك فإنه منجز وعده لك بالنصر.", "h": ["وجوب حمد الله تعالى على آلائه وعظيم نعمه.", "لا يُحمد إلا من له ما يقتضي حمده، وإلا كان المدح كذباً وزوراً.", "عظم شأن القرآن الكريم وسلامته من الإفراط والتفريط والانحراف في كل ما جاء به.", "بيان مهمة القرآن، وهي البشارة لأهل الإيمان والإنذار لأهل الشرك والكفران.", "التنديد بالكذب على الله ونسبة ما لا يليق بجلاله وكماله إليه كالولد ونحوه.", "تحريم الانتحار وقتل النفس من الحزن أو الخوف ونحوه من الغضب والحرمان."], "k": "«الحمد لله الذي أنزل على عبده الكتاب»… أعظم نعمة بين يديّ هذا الكتاب؛ فهل أحمد الله عليه بتلاوته والعمل به؟"}, {"lbl": "الآيات ٧ – ١٢", "q": "إِنَّا جَعَلۡنَا مَا عَلَى ٱلۡأَرۡضِ زِينَةٗ لَّهَا لِنَبۡلُوَهُمۡ أَيُّهُمۡ أَحۡسَنُ عَمَلٗا ﴿٧﴾ وَإِنَّا لَجَٰعِلُونَ مَا عَلَيۡهَا صَعِيدٗا جُرُزًا ﴿٨﴾ أَمۡ حَسِبۡتَ أَنَّ أَصۡحَٰبَ ٱلۡكَهۡفِ وَٱلرَّقِيمِ كَانُواْ مِنۡ ءَايَٰتِنَا عَجَبًا ﴿٩﴾ إِذۡ أَوَى ٱلۡفِتۡيَةُ إِلَى ٱلۡكَهۡفِ فَقَالُواْ رَبَّنَآ ءَاتِنَا مِن لَّدُنكَ رَحۡمَةٗ وَهَيِّئۡ لَنَا مِنۡ أَمۡرِنَا رَشَدٗا ﴿١٠﴾ فَضَرَبۡنَا عَلَىٰٓ ءَاذَانِهِمۡ فِي ٱلۡكَهۡفِ سِنِينَ عَدَدٗا ﴿١١﴾ ثُمَّ بَعَثۡنَٰهُمۡ لِنَعۡلَمَ أَيُّ ٱلۡحِزۡبَيۡنِ أَحۡصَىٰ لِمَا لَبِثُوٓاْ أَمَدٗا ﴿١٢﴾", "w": [["زينة لها", "من حيوان وأشجار ونبات وأنهار وبحار."], ["لنبلوهم", "لنختبرهم."], ["صعيداً جرزاً", "تراباً لا نبات فيه."], ["الكهف", "النقب الواسع في الجبل، والضيّق منه يقال له غار."], ["والرقيم", "لوح حجري رُقمت فيه أسماء أصحاب الكهف."], ["أوى الفتية إلى الكهف", "اتخذوه مأوى لهم ومنزلاً نزلوا فيه."], ["الفتية", "جمع فتى، وهم شبان مؤمنون."], ["وهيّئ لنا من أمرنا رشداً", "يسّر لنا طريق رشد وهداية."], ["فضربنا على آذانهم", "ضربنا على آذانهم حجاباً يمنعهم من سماع الأصوات."], ["سنين عدداً", "أعواماً عدّة."], ["ثم بعثناهم", "أيقظناهم من نومهم."], ["أحصى لما لبثوا", "أضبط لأوقات لبثهم في الكهف."], ["أمداً", "مدة محدودة معلومة."]], "m": "إنا جعلنا ما على الأرض من حيوان وأشجار وأنهار زينة لها لنختبر الناس أيّهم أترك لها وأعمل فيها بطاعتنا، وإنا لمخرّبوها يوماً بعد عمارتها فنجعلها تراباً لا نبات فيه، فلا تحزن يا رسولنا مما تلقاه من قومك، فإن مآل الحياة التي من أجلها عادوك إلى أن تصبح صعيداً جرزاً. أظننت أن أصحاب الكهف والرقيم، اللوح الذي رُقمت فيه أسماؤهم وقصتهم، كانوا أعجب آياتنا؟ بل من مخلوقات الله ما هو أعجب بكثير. ثم شرع في قصتهم: اذكر للسائلين إذ أوى الفتية، سبعة شبان ومعهم كلب لهم، إلى الغار هروباً من قومهم الكفار أن يفتنوهم في دينهم، فقالوا: ربنا أعطنا من عندك رحمة تصحبنا في هجرتنا هذه، ويسّر لنا من أمرنا سداداً ونجاة من أهل الكفر. قال ابن جرير: كانوا مسلمين على دين عيسى، وكان لهم ملك عابد وثن دعاهم إلى عبادة الأصنام فهربوا بدينهم. فضربنا على آذانهم حجاباً يمنعهم من سماع الأصوات فناموا سنين معدودة، ثلاثمائة وتسع سنين، استجابة لدعائهم، ثم أيقظناهم لنعلم علم مشاهدة، ويعلم عبادي، أي الحزبين اللذين اختلفا في مدة لبثهم كان أضبط لها.", "h": ["بيان العلة في وجود الزينة على هذه الأرض، وهي الابتلاء والاختبار للناس، ليظهر الزاهد فيها العارف بتفاهتها وسرعة زوالها، وليظهر الراغب فيها المتكالب عليها.", "تقرير فناء كل ما على الأرض حتى تبقى صعيداً جرزاً وقاعاً صفصفاً.", "تقرير نبوة الرسول ﷺ بإجابة السائلين عن أصحاب الكهف بالإيجاز والتفصيل.", "تقرير التوحيد ضمن قصة أصحاب الكهف، إذ فرّوا بدينهم خوفاً من الشرك والكفر.", "استجابة الله دعاء عباده المؤمنين الموحّدين، حيث استجاب للفتية فآواهم الغار ورعاهم حتى بعثهم بعد تغيّر الأحوال وتبدّل العباد والبلاد."], "k": "«ربنا آتنا من لدنك رحمة وهيّئ لنا من أمرنا رشداً»… أي أمر في حياتي أحتاج أن أدعو له بهذا الدعاء الليلة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (198, 18, 13, 18, 'سورة الكهف ١٣ – ١٨', '«إنهم فتية آمنوا بربهم وزدناهم هدى»، وحالهم في الكهف: «وتحسبهم أيقاظاً وهم رقود»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 198) = $j$[{"lbl": "الآيات ١٣ – ١٦", "q": "نَّحۡنُ نَقُصُّ عَلَيۡكَ نَبَأَهُم بِٱلۡحَقِّۚ إِنَّهُمۡ فِتۡيَةٌ ءَامَنُواْ بِرَبِّهِمۡ وَزِدۡنَٰهُمۡ هُدٗى ﴿١٣﴾ وَرَبَطۡنَا عَلَىٰ قُلُوبِهِمۡ إِذۡ قَامُواْ فَقَالُواْ رَبُّنَا رَبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ لَن نَّدۡعُوَاْ مِن دُونِهِۦٓ إِلَٰهٗاۖ لَّقَدۡ قُلۡنَآ إِذٗا شَطَطًا ﴿١٤﴾ هَـٰٓؤُلَآءِ قَوۡمُنَا ٱتَّخَذُواْ مِن دُونِهِۦٓ ءَالِهَةٗۖ لَّوۡلَا يَأۡتُونَ عَلَيۡهِم بِسُلۡطَٰنِۭ بَيِّنٖۖ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا ﴿١٥﴾ وَإِذِ ٱعۡتَزَلۡتُمُوهُمۡ وَمَا يَعۡبُدُونَ إِلَّا ٱللَّهَ فَأۡوُۥٓاْ إِلَى ٱلۡكَهۡفِ يَنشُرۡ لَكُمۡ رَبُّكُم مِّن رَّحۡمَتِهِۦ وَيُهَيِّئۡ لَكُم مِّنۡ أَمۡرِكُم مِّرۡفَقٗا ﴿١٦﴾", "w": [["نبأهم بالحق", "خبرهم العجيب بالصدق واليقين."], ["وزدناهم هدى", "إيماناً وبصيرة في دينهم ومعرفة ربهم حتى صبروا على الهجرة."], ["وربطنا على قلوبهم", "شددنا عليها فقويت عزائمهم حتى قالوا كلمة الحق عند سلطان كافر."], ["لن ندعو من دونه إلهاً", "لن نعبد من دونه إلهاً آخر."], ["لولا يأتون عليهم بسلطان", "هلّا يأتون بحجة قوية تثبت صحة عبادتهم."], ["على الله كذباً", "باتخاذ آلهة من دونه تعالى يدعوها ويعبدها."], ["فأووا إلى الكهف", "انزلوا في الكهف تستترون به عن أعين أعدائكم المشركين."], ["ينشر لكم ربكم من رحمته", "يبسط من رحمته عليكم بنجاتكم مما فررتم منه."], ["ويهيّئ لكم من أمركم", "ييسّر لكم من أمركم الذي أنتم فيه من الغم والكرب."], ["مرفقاً", "ما ترتفقون به وتنتفعون من طعام وشراب وإيواء."]], "m": "بعد الموجز أخذ في التفصيل: نحن نقصّ عليك خبر أصحاب الكهف بالحق الثابت، إنهم فتية صدّقوا بوجود ربهم ووجوب عبادته وتوحيده، وزدناهم هداية إلى معرفة الحق، وقوّينا عزائمهم بما شددنا على قلوبهم، حتى قاموا وقالوا على رؤوس الملأ أمام ملك كافر: ربنا رب السماوات والأرض، لن ندعو من دونه إلهاً، لقد قلنا إذاً قولاً بعيداً عن الحق. هؤلاء قومنا اتخذوا من دونه آلهة، هلّا يأتون على عبادتها بحجة واضحة؟ ومن أين ذلك ولا إله إلا الله؟ فلا أظلم ممن افترى على الله كذباً باتخاذ آلهة معه باسم التوسّل بها والتقرّب إلى الله زلفى. ثم قال بعضهم لبعض: وإذ اعتزلتموهم وما يعبدون من الأصنام إلا الله، فصيروا إلى الغار، يبسط لكم ربكم من رحمته بتيسير المخرج، ويهيّئ لكم ما ترتفقون به من طعام وشراب وأمن في مأواكم الجديد الذي أويتم إليه فراراً بدينكم.", "h": ["تقرير النبوة المحمدية بذكر قصة أصحاب الكهف.", "تقرير زيادة الإيمان ونقصانه.", "فضيلة الجرأة في الحق والتصريح به ولو أدّى إلى القتل أو الضرب أو السجن.", "تقرير التوحيد، وأنه لا إله إلا الله، على لسان أصحاب الكهف.", "بطلان عبادة غير الله لعدم وجود دليل عقلي أو نقلي عليها.", "الشرك ظلم وكذب، والمشرك ظالم مفترٍ كاذب.", "تقرير فرض الهجرة في سبيل الله.", "فضيلة الالتجاء إلى الله تعالى وطلب حمايته، وكفاية الله من لجأ إليه في صدق."], "k": "«إنهم فتية آمنوا بربهم وزدناهم هدى»… شباب ثبتوا أمام ملك؛ فهل أثبت على الحق أمام رفاقي؟"}, {"lbl": "الآيتان ١٧ – ١٨", "q": "۞وَتَرَى ٱلشَّمۡسَ إِذَا طَلَعَت تَّزَٰوَرُ عَن كَهۡفِهِمۡ ذَاتَ ٱلۡيَمِينِ وَإِذَا غَرَبَت تَّقۡرِضُهُمۡ ذَاتَ ٱلشِّمَالِ وَهُمۡ فِي فَجۡوَةٖ مِّنۡهُۚ ذَٰلِكَ مِنۡ ءَايَٰتِ ٱللَّهِۗ مَن يَهۡدِ ٱللَّهُ فَهُوَ ٱلۡمُهۡتَدِۖ وَمَن يُضۡلِلۡ فَلَن تَجِدَ لَهُۥ وَلِيّٗا مُّرۡشِدٗا ﴿١٧﴾ وَتَحۡسَبُهُمۡ أَيۡقَاظٗا وَهُمۡ رُقُودٞۚ وَنُقَلِّبُهُمۡ ذَاتَ ٱلۡيَمِينِ وَذَاتَ ٱلشِّمَالِۖ وَكَلۡبُهُم بَٰسِطٞ ذِرَاعَيۡهِ بِٱلۡوَصِيدِۚ لَوِ ٱطَّلَعۡتَ عَلَيۡهِمۡ لَوَلَّيۡتَ مِنۡهُمۡ فِرَارٗا وَلَمُلِئۡتَ مِنۡهُمۡ رُعۡبٗا ﴿١٨﴾", "w": [["تزاور", "تميل."], ["تقرضهم", "تتركهم وتتجاوز عنهم فلا تصيبهم."], ["في فجوة منه", "متّسع من الكهف ينالهم برد الريح ونسيمها."], ["أيقاظاً", "جمع يقظ، أي منتبهين لأن أعينهم منفتحة."], ["بالوصيد", "فناء الكهف."], ["رعباً", "منعهم الله بسببه من الدخول عليهم."]], "m": "ما زال السياق في أهل الكهف: وترى الشمس إذا طلعت تميل عن كهفهم جهة اليمين، وإذا غربت تتركهم وتتجاوز عنهم ذات الشمال فلا تصيبهم، وهم في متّسع من الكهف ينالهم برد الريح ونسيمها، ذلك من دلائل قدرة الله ورحمته بأوليائه ولطفه بهم. من يهد الله فهو المهتد، ومن يضلل فلن تجد له ولياً مرشداً، فليطلب العبد من ربه الهداية، وليستعذ به من الضلال. وتحسبهم إذا نظرت إليهم منتبهين لأن أعينهم مفتّحة، وهم رقود لا يحسّون بأحد، ونقلّبهم جهة اليمين وجهة الشمال حتى لا تعدو التربة على أجسادهم فتبليها، وكلبهم الذي خرج معهم باسط ذراعيه بفناء الكهف. لو شاهدتهم لولّيت منهم فاراً، ولمُلئت منهم خوفاً وفزعاً، إذ ألقى الله عليهم من الهيبة ما لا يدنو منهم أحد بسوء إلى أن يوقظهم عند نهاية الأجل، ليكون أمرهم آية على قدرته وعجيب تدبيره.", "h": ["بيان لطف الله تعالى بأوليائه بإكرامهم في هجرتهم إليه.", "تقرير أن الهداية بيد الله، فالمهتدي من هداه الله، والضال من أضلّه الله، ولازم ذلك طلب الهداية من الله والتعوّذ به من الضلال لأنه مالك ذلك."], "k": "«ونقلّبهم ذات اليمين وذات الشمال»… رعاهم وهم نيام؛ فكيف لا أطمئن إلى رعايته وأنا يقظ؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 198;
