insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (199, 18, 19, 26, 'سورة الكهف ١٩ – ٢٦', 'بعث الفتية وإعثار قومهم عليهم، و«ولا تقولنّ لشيء إني فاعل ذلك غداً إلا أن يشاء الله»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 199) = $j$[{"lbl": "الآيات ١٩ – ٢١", "q": "وَكَذَٰلِكَ بَعَثۡنَٰهُمۡ لِيَتَسَآءَلُواْ بَيۡنَهُمۡۚ قَالَ قَآئِلٞ مِّنۡهُمۡ كَمۡ لَبِثۡتُمۡۖ قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۚ قَالُواْ رَبُّكُمۡ أَعۡلَمُ بِمَا لَبِثۡتُمۡ فَٱبۡعَثُوٓاْ أَحَدَكُم بِوَرِقِكُمۡ هَٰذِهِۦٓ إِلَى ٱلۡمَدِينَةِ فَلۡيَنظُرۡ أَيُّهَآ أَزۡكَىٰ طَعَامٗا فَلۡيَأۡتِكُم بِرِزۡقٖ مِّنۡهُ وَلۡيَتَلَطَّفۡ وَلَا يُشۡعِرَنَّ بِكُمۡ أَحَدًا ﴿١٩﴾ إِنَّهُمۡ إِن يَظۡهَرُواْ عَلَيۡكُمۡ يَرۡجُمُوكُمۡ أَوۡ يُعِيدُوكُمۡ فِي مِلَّتِهِمۡ وَلَن تُفۡلِحُوٓاْ إِذًا أَبَدٗا ﴿٢٠﴾ وَكَذَٰلِكَ أَعۡثَرۡنَا عَلَيۡهِمۡ لِيَعۡلَمُوٓاْ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَأَنَّ ٱلسَّاعَةَ لَا رَيۡبَ فِيهَآ إِذۡ يَتَنَٰزَعُونَ بَيۡنَهُمۡ أَمۡرَهُمۡۖ فَقَالُواْ ٱبۡنُواْ عَلَيۡهِم بُنۡيَٰنٗاۖ رَّبُّهُمۡ أَعۡلَمُ بِهِمۡۚ قَالَ ٱلَّذِينَ غَلَبُواْ عَلَىٰٓ أَمۡرِهِمۡ لَنَتَّخِذَنَّ عَلَيۡهِم مَّسۡجِدٗا ﴿٢١﴾", "w": [["وكذلك بعثناهم", "كما أنمناهم تلك النومة الطويلة الخارقة للعادة بعثناهم من رقادهم بعثاً خارقاً للعادة أيضاً."], ["كم لبثتم", "في الكهف نائمين."], ["يوماً أو بعض يوم", "لأنهم دخلوا الكهف صباحاً واستيقظوا عشية."], ["بورقكم", "بدراهم الفضة التي عندكم."], ["إلى المدينة", "المدينة التي خرجوا منها هاربين بدينهم."], ["أزكى طعاماً", "أي أطعمة المدينة أحلّ."], ["وليتلطّف", "يذهب يشتري الطعام ويعود في لطف وخفاء."], ["يرجموكم", "يقتلوكم رمياً بالحجارة."], ["أعثرنا عليهم", "أطلعنا عليهم أهل بلدهم."], ["ليعلموا", "ليعلم قومهم أن البعث حق للأجساد والأرواح معاً."], ["وقال الذين غلبوا على أمرهم", "لنتخذنّ حولهم مسجداً يُصلّى فيه."]], "m": "كما أنمناهم ثلاثمائة سنة وتسعاً وحفظنا أجسادهم وثيابهم من البلى، بعثناهم ليتساءلوا بينهم، فقال قائل منهم: كم لبثتم يا إخواننا؟ فأجاب بعضهم: لبثنا يوماً أو بعض يوم، لأنهم أووا إلى الكهف في الصباح وبُعثوا في المساء، وأجاب آخرون: ربكم أعلم بما لبثتم، فسلّموا الأمر إليه. وكانوا جياعاً، فقالوا: ابعثوا أحدكم بهذه الدراهم الفضية إلى المدينة، فلينظر أي أنواع الطعام أطهر من الحرام والاستقذار فليأتكم برزق منه، وليتلطّف في شرائه وذهابه وإيابه حتى لا يُشعر بكم أحداً، إنهم إن يطّلعوا عليكم يقتلوكم رجماً بالحجارة، أو يعيدوكم في ملّتهم بالقسر، ولن تفلحوا إذاً أبداً إن عدتم للكفر. وكذلك أطلعنا عليهم أهل مدينتهم، وكانوا فريقين: فريق يعتقد أن البعث بالأجسام والأرواح، وفريق يقول هو للأرواح دون الأجسام، فاتضح لهم أن الله قادر على بعث الناس أجساماً وأرواحاً كما بعث أصحاب الكهف، ليعلموا أن وعد الله حق وأن الساعة لا ريب فيها. فلما ماتوا بعد أن عُثر عليهم قال بعضهم: ابنوا عليهم بنياناً وسدّوا عليهم باب الكهف، ربهم أعلم بهم، وقال الذين غلبوا على أمرهم: لنتخذنّ عليهم مسجداً، فبنوه على مقربة من فم الغار.", "h": ["مظاهر قدرة الله تعالى وعلمه وحكمته.", "وجوب طلب الحلال في الطعام والشراب وغيرهما.", "الموت على الشرك والكفر مانع من الفلاح يوم القيامة أبداً.", "تقرير معتقد البعث والجزاء الذي ينكره أهل مكة.", "مصداق قول الرسول ﷺ: «لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد»، وقوله: «إن أولئك إذا كان فيهم الرجل الصالح فمات بنوا على قبره مسجداً وصوّروا فيه تلك الصور، أولئك شرار الخلق يوم القيامة» (في الصحيحين).", "مصداق قول الرسول ﷺ: «لتتبعنّ سنن من قبلكم شبراً بشبر وذراعاً بذراع»، إذ قد بنى المسلمون على قبور الأولياء والصالحين المساجد بعد القرون المفضّلة، حتى أصبح يندر وجود مسجد عتيق خالٍ من قبر أو قبور."], "k": "«فلينظر أيها أزكى طعاماً»… في أشد جوعهم تحرّوا الحلال؛ فهل أسأل عن طيب ما آكل؟"}, {"lbl": "الآيات ٢٢ – ٢٦", "q": "سَيَقُولُونَ ثَلَٰثَةٞ رَّابِعُهُمۡ كَلۡبُهُمۡ وَيَقُولُونَ خَمۡسَةٞ سَادِسُهُمۡ كَلۡبُهُمۡ رَجۡمَۢا بِٱلۡغَيۡبِۖ وَيَقُولُونَ سَبۡعَةٞ وَثَامِنُهُمۡ كَلۡبُهُمۡۚ قُل رَّبِّيٓ أَعۡلَمُ بِعِدَّتِهِم مَّا يَعۡلَمُهُمۡ إِلَّا قَلِيلٞۗ فَلَا تُمَارِ فِيهِمۡ إِلَّا مِرَآءٗ ظَٰهِرٗا وَلَا تَسۡتَفۡتِ فِيهِم مِّنۡهُمۡ أَحَدٗا ﴿٢٢﴾ وَلَا تَقُولَنَّ لِشَاْيۡءٍ إِنِّي فَاعِلٞ ذَٰلِكَ غَدًا ﴿٢٣﴾ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ وَٱذۡكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلۡ عَسَىٰٓ أَن يَهۡدِيَنِ رَبِّي لِأَقۡرَبَ مِنۡ هَٰذَا رَشَدٗا ﴿٢٤﴾ وَلَبِثُواْ فِي كَهۡفِهِمۡ ثَلَٰثَ مِاْئَةٖ سِنِينَ وَٱزۡدَادُواْ تِسۡعٗا ﴿٢٥﴾ قُلِ ٱللَّهُ أَعۡلَمُ بِمَا لَبِثُواْۖ لَهُۥ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَبۡصِرۡ بِهِۦ وَأَسۡمِعۡۚ مَا لَهُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا يُشۡرِكُ فِي حُكۡمِهِۦٓ أَحَدٗا ﴿٢٦﴾", "w": [["رجماً بالغيب", "قذفاً بالظن من غير يقين علم."], ["ما يعلمهم إلا قليل", "من الناس."], ["فلا تمار فيهم", "لا تجادل في عدّتهم."], ["ولا تستفت فيهم منهم أحداً", "من أهل الكتاب، والاستفتاء: الاستفهام والسؤال."], ["إلا أن يشاء الله", "إلا أن تقول: إن شاء الله."], ["لأقرب من هذا رشداً", "هداية وأظهر دلالة على نبوتي من قصة أصحاب الكهف."], ["له غيب السماوات والأرض", "علم ما غاب فيهما."], ["أبصر به وأسمع", "صيغة تعجّب، والأصل: ما أبصره وما أسمعه."], ["ما لهم من دونه من ولي", "ليس لأهل السماوات والأرض من دون الله من ناصر."], ["ولا يشرك في حكمه أحداً", "لأنه غني عما سواه ولا شريك له."]], "m": "يخبر تعالى أن الخائضين في شأن أصحاب الكهف سيقول بعضهم: ثلاثة رابعهم كلبهم، ويقول آخرون: خمسة سادسهم كلبهم، قذفاً بالغيب من غير علم، ويقول بعضهم: سبعة وثامنهم كلبهم. قل: ربي أعلم بعدّتهم، ما يعلمهم إلا قليل من الناس، قال ابن عباس: أنا من ذلك القليل، فعدّتهم سبعة وثامنهم كلبهم، ولعله فهمه من سياق الآية، إذ وصف القولين الأولين بالرجم بالغيب وسكت عن الثالث. فلا تجادل أهل الكتاب فيهم إلا جدالاً ظاهراً بذكر ما قصصنا عليك، ولا تسأل عنهم منهم أحداً، فإنهم يقولون بالخرص والتخمين. ولا تقولنّ في شيء تريد فعله: سأفعله غداً، إلا أن تقول: إن شاء الله؛ وذلك أنه ﷺ لما سأله وفد قريش، بإيعاز من اليهود، عن الروح وأصحاب الكهف وذي القرنين، قال: أجيبكم غداً، ولم يقل: إن شاء الله، فأدّبه ربه بانقطاع الوحي عنه نصف شهر. واذكر ربك إذا نسيت الاستثناء فاذكره ولو بعد حين، وقل: عسى أن يهديني ربي لأقرب من هذا رشداً، مما هو أظهر دلالة على نبوتي. ولبثوا في كهفهم ثلاثمائة سنين بالحساب الشمسي، وازدادوا تسعاً بالحساب القمري، قل الله أعلم بما لبثوا، له غيب السماوات والأرض، ما أبصره بخلقه وما أسمعه لأقوالهم، ليس لأهل السماوات والأرض من دونه من ناصر، ولا يشرك في حكمه أحداً لغناه عما سواه.", "h": ["بيان اختلاف أهل الكتاب وعدم ضبطهم للأحداث التاريخية.", "بيان عدد فتية أصحاب الكهف، وأنهم سبعة وثامنهم كلبهم.", "من الأدب مع الله تعالى أن لا يقول العبد: سأفعل كذا مستقبلاً، إلا قال بعدها: إن شاء الله.", "من الأدب أن من نسي الاستثناء يستثني ولو بعد حين، فإن حلف لا ينفعه الاستثناء إلا إذا كان متصلاً بكلامه.", "تقرير المدة التي لبثها الفتية في كهفهم، وهي ثلاثمائة وتسع سنين بالحساب القمري."], "k": "«ولا تقولنّ لشيء إني فاعل ذلك غداً إلا أن يشاء الله»… خططي للغد، هل أعلّقها بمشيئته؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 199;
insert into public.tdb_cards(topic, i, body) select 199, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٩ – ٢١", "q": "وَكَذَٰلِكَ بَعَثۡنَٰهُمۡ لِيَتَسَآءَلُواْ بَيۡنَهُمۡۚ قَالَ قَآئِلٞ مِّنۡهُمۡ كَمۡ لَبِثۡتُمۡۖ قَالُواْ لَبِثۡنَا يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۚ قَالُواْ رَبُّكُمۡ أَعۡلَمُ بِمَا لَبِثۡتُمۡ فَٱبۡعَثُوٓاْ أَحَدَكُم بِوَرِقِكُمۡ هَٰذِهِۦٓ إِلَى ٱلۡمَدِينَةِ فَلۡيَنظُرۡ أَيُّهَآ أَزۡكَىٰ طَعَامٗا فَلۡيَأۡتِكُم بِرِزۡقٖ مِّنۡهُ وَلۡيَتَلَطَّفۡ وَلَا يُشۡعِرَنَّ بِكُمۡ أَحَدًا ﴿١٩﴾ إِنَّهُمۡ إِن يَظۡهَرُواْ عَلَيۡكُمۡ يَرۡجُمُوكُمۡ أَوۡ يُعِيدُوكُمۡ فِي مِلَّتِهِمۡ وَلَن تُفۡلِحُوٓاْ إِذًا أَبَدٗا ﴿٢٠﴾ وَكَذَٰلِكَ أَعۡثَرۡنَا عَلَيۡهِمۡ لِيَعۡلَمُوٓاْ أَنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَأَنَّ ٱلسَّاعَةَ لَا رَيۡبَ فِيهَآ إِذۡ يَتَنَٰزَعُونَ بَيۡنَهُمۡ أَمۡرَهُمۡۖ فَقَالُواْ ٱبۡنُواْ عَلَيۡهِم بُنۡيَٰنٗاۖ رَّبُّهُمۡ أَعۡلَمُ بِهِمۡۚ قَالَ ٱلَّذِينَ غَلَبُواْ عَلَىٰٓ أَمۡرِهِمۡ لَنَتَّخِذَنَّ عَلَيۡهِم مَّسۡجِدٗا ﴿٢١﴾", "w": [["وكذلك بعثناهم", "كما أنمناهم تلك النومة الطويلة الخارقة للعادة بعثناهم من رقادهم بعثاً خارقاً للعادة أيضاً."], ["كم لبثتم", "في الكهف نائمين."], ["يوماً أو بعض يوم", "لأنهم دخلوا الكهف صباحاً واستيقظوا عشية."], ["بورقكم", "بدراهم الفضة التي عندكم."], ["إلى المدينة", "المدينة التي خرجوا منها هاربين بدينهم."], ["أزكى طعاماً", "أي أطعمة المدينة أحلّ."], ["وليتلطّف", "يذهب يشتري الطعام ويعود في لطف وخفاء."], ["يرجموكم", "يقتلوكم رمياً بالحجارة."], ["أعثرنا عليهم", "أطلعنا عليهم أهل بلدهم."], ["ليعلموا", "ليعلم قومهم أن البعث حق للأجساد والأرواح معاً."], ["وقال الذين غلبوا على أمرهم", "لنتخذنّ حولهم مسجداً يُصلّى فيه."]], "m": "كما أنمناهم ثلاثمائة سنة وتسعاً وحفظنا أجسادهم وثيابهم من البلى، بعثناهم ليتساءلوا بينهم، فقال قائل منهم: كم لبثتم يا إخواننا؟ فأجاب بعضهم: لبثنا يوماً أو بعض يوم، لأنهم أووا إلى الكهف في الصباح وبُعثوا في المساء، وأجاب آخرون: ربكم أعلم بما لبثتم، فسلّموا الأمر إليه. وكانوا جياعاً، فقالوا: ابعثوا أحدكم بهذه الدراهم الفضية إلى المدينة، فلينظر أي أنواع الطعام أطهر من الحرام والاستقذار فليأتكم برزق منه، وليتلطّف في شرائه وذهابه وإيابه حتى لا يُشعر بكم أحداً، إنهم إن يطّلعوا عليكم يقتلوكم رجماً بالحجارة، أو يعيدوكم في ملّتهم بالقسر، ولن تفلحوا إذاً أبداً إن عدتم للكفر. وكذلك أطلعنا عليهم أهل مدينتهم، وكانوا فريقين: فريق يعتقد أن البعث بالأجسام والأرواح، وفريق يقول هو للأرواح دون الأجسام، فاتضح لهم أن الله قادر على بعث الناس أجساماً وأرواحاً كما بعث أصحاب الكهف، ليعلموا أن وعد الله حق وأن الساعة لا ريب فيها. فلما ماتوا بعد أن عُثر عليهم قال بعضهم: ابنوا عليهم بنياناً وسدّوا عليهم باب الكهف، ربهم أعلم بهم، وقال الذين غلبوا على أمرهم: لنتخذنّ عليهم مسجداً، فبنوه على مقربة من فم الغار.", "h": ["مظاهر قدرة الله تعالى وعلمه وحكمته.", "وجوب طلب الحلال في الطعام والشراب وغيرهما.", "الموت على الشرك والكفر مانع من الفلاح يوم القيامة أبداً.", "تقرير معتقد البعث والجزاء الذي ينكره أهل مكة.", "مصداق قول الرسول ﷺ: «لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد»، وقوله: «إن أولئك إذا كان فيهم الرجل الصالح فمات بنوا على قبره مسجداً وصوّروا فيه تلك الصور، أولئك شرار الخلق يوم القيامة» (في الصحيحين).", "مصداق قول الرسول ﷺ: «لتتبعنّ سنن من قبلكم شبراً بشبر وذراعاً بذراع»، إذ قد بنى المسلمون على قبور الأولياء والصالحين المساجد بعد القرون المفضّلة، حتى أصبح يندر وجود مسجد عتيق خالٍ من قبر أو قبور."], "k": "«فلينظر أيها أزكى طعاماً»… في أشد جوعهم تحرّوا الحلال؛ فهل أسأل عن طيب ما آكل؟"}, {"lbl": "الآيات ٢٢ – ٢٦", "q": "سَيَقُولُونَ ثَلَٰثَةٞ رَّابِعُهُمۡ كَلۡبُهُمۡ وَيَقُولُونَ خَمۡسَةٞ سَادِسُهُمۡ كَلۡبُهُمۡ رَجۡمَۢا بِٱلۡغَيۡبِۖ وَيَقُولُونَ سَبۡعَةٞ وَثَامِنُهُمۡ كَلۡبُهُمۡۚ قُل رَّبِّيٓ أَعۡلَمُ بِعِدَّتِهِم مَّا يَعۡلَمُهُمۡ إِلَّا قَلِيلٞۗ فَلَا تُمَارِ فِيهِمۡ إِلَّا مِرَآءٗ ظَٰهِرٗا وَلَا تَسۡتَفۡتِ فِيهِم مِّنۡهُمۡ أَحَدٗا ﴿٢٢﴾ وَلَا تَقُولَنَّ لِشَاْيۡءٍ إِنِّي فَاعِلٞ ذَٰلِكَ غَدًا ﴿٢٣﴾ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ وَٱذۡكُر رَّبَّكَ إِذَا نَسِيتَ وَقُلۡ عَسَىٰٓ أَن يَهۡدِيَنِ رَبِّي لِأَقۡرَبَ مِنۡ هَٰذَا رَشَدٗا ﴿٢٤﴾ وَلَبِثُواْ فِي كَهۡفِهِمۡ ثَلَٰثَ مِاْئَةٖ سِنِينَ وَٱزۡدَادُواْ تِسۡعٗا ﴿٢٥﴾ قُلِ ٱللَّهُ أَعۡلَمُ بِمَا لَبِثُواْۖ لَهُۥ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ أَبۡصِرۡ بِهِۦ وَأَسۡمِعۡۚ مَا لَهُم مِّن دُونِهِۦ مِن وَلِيّٖ وَلَا يُشۡرِكُ فِي حُكۡمِهِۦٓ أَحَدٗا ﴿٢٦﴾", "w": [["رجماً بالغيب", "قذفاً بالظن من غير يقين علم."], ["ما يعلمهم إلا قليل", "من الناس."], ["فلا تمار فيهم", "لا تجادل في عدّتهم."], ["ولا تستفت فيهم منهم أحداً", "من أهل الكتاب، والاستفتاء: الاستفهام والسؤال."], ["إلا أن يشاء الله", "إلا أن تقول: إن شاء الله."], ["لأقرب من هذا رشداً", "هداية وأظهر دلالة على نبوتي من قصة أصحاب الكهف."], ["له غيب السماوات والأرض", "علم ما غاب فيهما."], ["أبصر به وأسمع", "صيغة تعجّب، والأصل: ما أبصره وما أسمعه."], ["ما لهم من دونه من ولي", "ليس لأهل السماوات والأرض من دون الله من ناصر."], ["ولا يشرك في حكمه أحداً", "لأنه غني عما سواه ولا شريك له."]], "m": "يخبر تعالى أن الخائضين في شأن أصحاب الكهف سيقول بعضهم: ثلاثة رابعهم كلبهم، ويقول آخرون: خمسة سادسهم كلبهم، قذفاً بالغيب من غير علم، ويقول بعضهم: سبعة وثامنهم كلبهم. قل: ربي أعلم بعدّتهم، ما يعلمهم إلا قليل من الناس، قال ابن عباس: أنا من ذلك القليل، فعدّتهم سبعة وثامنهم كلبهم، ولعله فهمه من سياق الآية، إذ وصف القولين الأولين بالرجم بالغيب وسكت عن الثالث. فلا تجادل أهل الكتاب فيهم إلا جدالاً ظاهراً بذكر ما قصصنا عليك، ولا تسأل عنهم منهم أحداً، فإنهم يقولون بالخرص والتخمين. ولا تقولنّ في شيء تريد فعله: سأفعله غداً، إلا أن تقول: إن شاء الله؛ وذلك أنه ﷺ لما سأله وفد قريش، بإيعاز من اليهود، عن الروح وأصحاب الكهف وذي القرنين، قال: أجيبكم غداً، ولم يقل: إن شاء الله، فأدّبه ربه بانقطاع الوحي عنه نصف شهر. واذكر ربك إذا نسيت الاستثناء فاذكره ولو بعد حين، وقل: عسى أن يهديني ربي لأقرب من هذا رشداً، مما هو أظهر دلالة على نبوتي. ولبثوا في كهفهم ثلاثمائة سنين بالحساب الشمسي، وازدادوا تسعاً بالحساب القمري، قل الله أعلم بما لبثوا، له غيب السماوات والأرض، ما أبصره بخلقه وما أسمعه لأقوالهم، ليس لأهل السماوات والأرض من دونه من ناصر، ولا يشرك في حكمه أحداً لغناه عما سواه.", "h": ["بيان اختلاف أهل الكتاب وعدم ضبطهم للأحداث التاريخية.", "بيان عدد فتية أصحاب الكهف، وأنهم سبعة وثامنهم كلبهم.", "من الأدب مع الله تعالى أن لا يقول العبد: سأفعل كذا مستقبلاً، إلا قال بعدها: إن شاء الله.", "من الأدب أن من نسي الاستثناء يستثني ولو بعد حين، فإن حلف لا ينفعه الاستثناء إلا إذا كان متصلاً بكلامه.", "تقرير المدة التي لبثها الفتية في كهفهم، وهي ثلاثمائة وتسع سنين بالحساب القمري."], "k": "«ولا تقولنّ لشيء إني فاعل ذلك غداً إلا أن يشاء الله»… خططي للغد، هل أعلّقها بمشيئته؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (200, 18, 27, 38, 'سورة الكهف ٢٧ – ٣٨', '«واصبر نفسك مع الذين يدعون ربهم بالغداة والعشي»، ومثل صاحب الجنتين: «أكفرت بالذي خلقك من تراب»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 200) = $j$[{"lbl": "الآيات ٢٧ – ٣١", "q": "وَٱتۡلُ مَآ أُوحِيَ إِلَيۡكَ مِن كِتَابِ رَبِّكَۖ لَا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَلَن تَجِدَ مِن دُونِهِۦ مُلۡتَحَدٗا ﴿٢٧﴾ وَٱصۡبِرۡ نَفۡسَكَ مَعَ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ وَلَا تَعۡدُ عَيۡنَاكَ عَنۡهُمۡ تُرِيدُ زِينَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُۥ عَن ذِكۡرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمۡرُهُۥ فُرُطٗا ﴿٢٨﴾ وَقُلِ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَن شَآءَ فَلۡيُؤۡمِن وَمَن شَآءَ فَلۡيَكۡفُرۡۚ إِنَّآ أَعۡتَدۡنَا لِلظَّـٰلِمِينَ نَارًا أَحَاطَ بِهِمۡ سُرَادِقُهَاۚ وَإِن يَسۡتَغِيثُواْ يُغَاثُواْ بِمَآءٖ كَٱلۡمُهۡلِ يَشۡوِي ٱلۡوُجُوهَۚ بِئۡسَ ٱلشَّرَابُ وَسَآءَتۡ مُرۡتَفَقًا ﴿٢٩﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجۡرَ مَنۡ أَحۡسَنَ عَمَلًا ﴿٣٠﴾ أُوْلَـٰٓئِكَ لَهُمۡ جَنَّـٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَيَلۡبَسُونَ ثِيَابًا خُضۡرٗا مِّن سُندُسٖ وَإِسۡتَبۡرَقٖ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلۡأَرَآئِكِۚ نِعۡمَ ٱلثَّوَابُ وَحَسُنَتۡ مُرۡتَفَقٗا ﴿٣١﴾", "w": [["واتل ما أوحي إليك من كتاب ربك", "اقرأ القرآن تعبّداً ودعوةً وتعليماً."], ["لا مبدّل لكلماته", "لا مغيّر لكلمات الله في ألفاظها ولا معانيها وأحكامها."], ["ملتحداً", "ملجأً تميل إليه احتماءً به."], ["واصبر نفسك", "احبسها."], ["يريدون وجهه", "طاعته ورضاه، لا عرضاً من عرض الدنيا."], ["ولا تعدُ عيناك عنهم", "لا تتجاوزهم بنظرك إلى غيرهم من أبناء الدنيا."], ["تريد زينة الحياة الدنيا", "بمجالستك الأغنياء تريد الشرف والفخر."], ["من أغفلنا قلبه", "جعلناه غافلاً عما يجب عليه من ذكرنا وعبادتنا."], ["وكان أمره فرطاً", "ضياعاً وهلاكاً."], ["أحاط بهم سرادقها", "حائط من نار أُحيط بهؤلاء المعذّبين."], ["بماء كالمهل", "كعكر الزيت، وهو ما يبقى في أسفل الإناء."], ["من سندس وإستبرق", "رقيق الديباج وما غلظ منه."]], "m": "بعد نهاية الحديث عن أصحاب الكهف أمر رسوله: واقرأ ما أوحي إليك من كتاب ربك تعبّداً ودعوةً وتعليماً، ولا تتركنّ تلاوته والعمل به، فإن ربك لا مبدّل لكلماته المشتملة على وعده لأوليائه ووعيده لأعدائه، ولن تجد من دونه ملجأً تحتمي به؛ وإذا وُجّه هذا الوعيد إلى رسول الله ﷺ وهو المعصوم، فغيره ممن ترك تلاوة القرآن والعمل به أولى به إن لم يتب. واصبر نفسك: نزل لما عرض عليه المشركون إبعاد أصحابه الفقراء كبلال وصهيب ليجلسوا إليه، فأمره أن يحبس نفسه مع الذين يدعون ربهم في الصباح والمساء لا يريدون عرضاً من الدنيا، وإنما رضا الله، ولا تتجاوزهم بنظرك إلى الأغنياء تريد مجالستهم للشرف والفخر، ولا تطع من أغفلنا قلبه عن ذكرنا لعناده وكبريائه، وكان أمره ضياعاً وهلاكاً. وقل: هذا الحق من ربكم، فمن شاء فليؤمن ومن شاء فليكفر. إنا أعددنا للظالمين ناراً أحاط بهم سورها، وإن يستغيثوا من شدة العطش يغاثوا بماء كعكر الزيت يشوي الوجوه إذا أدناه الشارب، بئس الشراب وساءت مرتفقاً. أما الذين آمنوا وعملوا الصالحات فإنا لا نضيع أجر من أحسن عملاً، أولئك لهم جنات إقامة دائمة تجري من تحتهم الأنهار، يُحلّون فيها أساور من ذهب، ويلبسون ثياباً خضراً من سندس وإستبرق، متكئين فيها على الأسرّة بالحجال، نعم الثواب وحسنت مرتفقاً.", "h": ["بيان خيبة وخسران المعرضين عن كتاب الله، فلم يتلوه ولم يعملوا بما جاء فيه.", "الترغيب في مجالسة أبناء الآخرة، وهم الفقراء الصابرون، وترك أبناء الدنيا.", "على الداعي إلى الله تعالى أن يبيّن الحق، والناس بعدُ بحسب ما كُتب لهم أو عليهم.", "الترغيب والترهيب بذكر جزاء الفريقين المؤمنين والكافرين.", "عذاب النار شر عذاب، ونعيم الجنة نعم النعيم، ولا يهلك على الله إلا هالك."], "k": "«واصبر نفسك مع الذين يدعون ربهم بالغداة والعشي»… من أجالس؟ وهل يذكّرني مجلسي بالله؟"}, {"lbl": "الآيات ٣٢ – ٣٨", "q": "۞وَٱضۡرِبۡ لَهُم مَّثَلٗا رَّجُلَيۡنِ جَعَلۡنَا لِأَحَدِهِمَا جَنَّتَيۡنِ مِنۡ أَعۡنَٰبٖ وَحَفَفۡنَٰهُمَا بِنَخۡلٖ وَجَعَلۡنَا بَيۡنَهُمَا زَرۡعٗا ﴿٣٢﴾ كِلۡتَا ٱلۡجَنَّتَيۡنِ ءَاتَتۡ أُكُلَهَا وَلَمۡ تَظۡلِم مِّنۡهُ شَيۡـٔٗاۚ وَفَجَّرۡنَا خِلَٰلَهُمَا نَهَرٗا ﴿٣٣﴾ وَكَانَ لَهُۥ ثَمَرٞ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكۡثَرُ مِنكَ مَالٗا وَأَعَزُّ نَفَرٗا ﴿٣٤﴾ وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمٞ لِّنَفۡسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ أَبَدٗا ﴿٣٥﴾ وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةٗ وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّي لَأَجِدَنَّ خَيۡرٗا مِّنۡهَا مُنقَلَبٗا ﴿٣٦﴾ قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ يُحَاوِرُهُۥٓ أَكَفَرۡتَ بِٱلَّذِي خَلَقَكَ مِن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ سَوَّىٰكَ رَجُلٗا ﴿٣٧﴾ لَّـٰكِنَّا۠ هُوَ ٱللَّهُ رَبِّي وَلَآ أُشۡرِكُ بِرَبِّيٓ أَحَدٗا ﴿٣٨﴾", "w": [["واضرب لهم مثلاً", "اجعل لهم مثلاً هو رجلين."], ["جنّتين", "بستانين."], ["وحففناهما بنخل", "أحطناهما بنخل."], ["آتت أكلها", "أعطت ثمارها، وهو ما يؤكل."], ["ولم تظلم منه شيئاً", "لم تنقص منه شيئاً، بل أتت به كاملاً وافياً."], ["خلالهما نهراً", "خلال الأشجار والنخيل نهراً جارياً."], ["خيراً منها منقلباً", "مرجعاً في الآخرة."], ["أكفرت بالذي خلقك من تراب", "الاستفهام للتوبيخ، والخلق من تراب باعتبار الأصل، وهو آدم."], ["ثم سوّاك", "عدلك وصيّرك رجلاً."], ["لكنّا", "لكن أنا، حُذفت الألف وأُدغمت النون في النون."], ["هو الله ربي", "أنا أقول: الله ربي."]], "m": "اضرب لأولئك المشركين المتكبّرين الذين اقترحوا عليك طرد الفقراء المؤمنين مثلاً: رجلين، مؤمناً وكافراً، جعلنا للكافر بستانين من أعناب وأحطناهما بنخل وجعلنا بينهما زرعاً، كلتا الجنتين أعطت ثمرها كاملاً، وفجّرنا خلالهما نهراً يسقيهما، وكان له ثمر ومال، فقال لصاحبه وهو يحاوره فخراً وتعاظماً: أنا أكثر منك مالاً وأعزّ عشيرة. ودخل جنته وهو ظالم لنفسه بالكفر والكبر، قال: ما أظن أن تفنى هذه أبداً، وما أظن الساعة قائمة، ولئن رُددت إلى ربي كما تقول لأجدنّ خيراً من جنتي مرجعاً، وهذا هو الغرور النفسي الذي يصاب به أهل الشرك والكبر. قال له صاحبه المسلم موبّخاً: أكفرت بالذي خلق أباك آدم من تراب، ثم خلقك من نطفة، ثم عدّلك رجلاً؟ لكن أنا أقول: هو الله ربي، ولا أشرك بربي أحداً من خلقه في عبادته.", "h": ["استحسان ضرب الأمثال للوصول بالمعاني الخفية إلى الأذهان.", "بيان صورة مثالية لغرس بساتين النخل والكروم.", "تقرير عقيدة التوحيد والبعث والجزاء.", "التنديد بالكبر والغرور، حيث يفضيان بصاحبهما إلى الشرك والكفر."], "k": "«ما أظن أن تبيد هذه أبداً»… ما الذي أطمئن إليه كأنه لا يزول؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 200;
insert into public.tdb_cards(topic, i, body) select 200, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٧ – ٣١", "q": "وَٱتۡلُ مَآ أُوحِيَ إِلَيۡكَ مِن كِتَابِ رَبِّكَۖ لَا مُبَدِّلَ لِكَلِمَٰتِهِۦ وَلَن تَجِدَ مِن دُونِهِۦ مُلۡتَحَدٗا ﴿٢٧﴾ وَٱصۡبِرۡ نَفۡسَكَ مَعَ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ وَلَا تَعۡدُ عَيۡنَاكَ عَنۡهُمۡ تُرِيدُ زِينَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُۥ عَن ذِكۡرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمۡرُهُۥ فُرُطٗا ﴿٢٨﴾ وَقُلِ ٱلۡحَقُّ مِن رَّبِّكُمۡۖ فَمَن شَآءَ فَلۡيُؤۡمِن وَمَن شَآءَ فَلۡيَكۡفُرۡۚ إِنَّآ أَعۡتَدۡنَا لِلظَّـٰلِمِينَ نَارًا أَحَاطَ بِهِمۡ سُرَادِقُهَاۚ وَإِن يَسۡتَغِيثُواْ يُغَاثُواْ بِمَآءٖ كَٱلۡمُهۡلِ يَشۡوِي ٱلۡوُجُوهَۚ بِئۡسَ ٱلشَّرَابُ وَسَآءَتۡ مُرۡتَفَقًا ﴿٢٩﴾ إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ إِنَّا لَا نُضِيعُ أَجۡرَ مَنۡ أَحۡسَنَ عَمَلًا ﴿٣٠﴾ أُوْلَـٰٓئِكَ لَهُمۡ جَنَّـٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُ يُحَلَّوۡنَ فِيهَا مِنۡ أَسَاوِرَ مِن ذَهَبٖ وَيَلۡبَسُونَ ثِيَابًا خُضۡرٗا مِّن سُندُسٖ وَإِسۡتَبۡرَقٖ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلۡأَرَآئِكِۚ نِعۡمَ ٱلثَّوَابُ وَحَسُنَتۡ مُرۡتَفَقٗا ﴿٣١﴾", "w": [["واتل ما أوحي إليك من كتاب ربك", "اقرأ القرآن تعبّداً ودعوةً وتعليماً."], ["لا مبدّل لكلماته", "لا مغيّر لكلمات الله في ألفاظها ولا معانيها وأحكامها."], ["ملتحداً", "ملجأً تميل إليه احتماءً به."], ["واصبر نفسك", "احبسها."], ["يريدون وجهه", "طاعته ورضاه، لا عرضاً من عرض الدنيا."], ["ولا تعدُ عيناك عنهم", "لا تتجاوزهم بنظرك إلى غيرهم من أبناء الدنيا."], ["تريد زينة الحياة الدنيا", "بمجالستك الأغنياء تريد الشرف والفخر."], ["من أغفلنا قلبه", "جعلناه غافلاً عما يجب عليه من ذكرنا وعبادتنا."], ["وكان أمره فرطاً", "ضياعاً وهلاكاً."], ["أحاط بهم سرادقها", "حائط من نار أُحيط بهؤلاء المعذّبين."], ["بماء كالمهل", "كعكر الزيت، وهو ما يبقى في أسفل الإناء."], ["من سندس وإستبرق", "رقيق الديباج وما غلظ منه."]], "m": "بعد نهاية الحديث عن أصحاب الكهف أمر رسوله: واقرأ ما أوحي إليك من كتاب ربك تعبّداً ودعوةً وتعليماً، ولا تتركنّ تلاوته والعمل به، فإن ربك لا مبدّل لكلماته المشتملة على وعده لأوليائه ووعيده لأعدائه، ولن تجد من دونه ملجأً تحتمي به؛ وإذا وُجّه هذا الوعيد إلى رسول الله ﷺ وهو المعصوم، فغيره ممن ترك تلاوة القرآن والعمل به أولى به إن لم يتب. واصبر نفسك: نزل لما عرض عليه المشركون إبعاد أصحابه الفقراء كبلال وصهيب ليجلسوا إليه، فأمره أن يحبس نفسه مع الذين يدعون ربهم في الصباح والمساء لا يريدون عرضاً من الدنيا، وإنما رضا الله، ولا تتجاوزهم بنظرك إلى الأغنياء تريد مجالستهم للشرف والفخر، ولا تطع من أغفلنا قلبه عن ذكرنا لعناده وكبريائه، وكان أمره ضياعاً وهلاكاً. وقل: هذا الحق من ربكم، فمن شاء فليؤمن ومن شاء فليكفر. إنا أعددنا للظالمين ناراً أحاط بهم سورها، وإن يستغيثوا من شدة العطش يغاثوا بماء كعكر الزيت يشوي الوجوه إذا أدناه الشارب، بئس الشراب وساءت مرتفقاً. أما الذين آمنوا وعملوا الصالحات فإنا لا نضيع أجر من أحسن عملاً، أولئك لهم جنات إقامة دائمة تجري من تحتهم الأنهار، يُحلّون فيها أساور من ذهب، ويلبسون ثياباً خضراً من سندس وإستبرق، متكئين فيها على الأسرّة بالحجال، نعم الثواب وحسنت مرتفقاً.", "h": ["بيان خيبة وخسران المعرضين عن كتاب الله، فلم يتلوه ولم يعملوا بما جاء فيه.", "الترغيب في مجالسة أبناء الآخرة، وهم الفقراء الصابرون، وترك أبناء الدنيا.", "على الداعي إلى الله تعالى أن يبيّن الحق، والناس بعدُ بحسب ما كُتب لهم أو عليهم.", "الترغيب والترهيب بذكر جزاء الفريقين المؤمنين والكافرين.", "عذاب النار شر عذاب، ونعيم الجنة نعم النعيم، ولا يهلك على الله إلا هالك."], "k": "«واصبر نفسك مع الذين يدعون ربهم بالغداة والعشي»… من أجالس؟ وهل يذكّرني مجلسي بالله؟"}, {"lbl": "الآيات ٣٢ – ٣٨", "q": "۞وَٱضۡرِبۡ لَهُم مَّثَلٗا رَّجُلَيۡنِ جَعَلۡنَا لِأَحَدِهِمَا جَنَّتَيۡنِ مِنۡ أَعۡنَٰبٖ وَحَفَفۡنَٰهُمَا بِنَخۡلٖ وَجَعَلۡنَا بَيۡنَهُمَا زَرۡعٗا ﴿٣٢﴾ كِلۡتَا ٱلۡجَنَّتَيۡنِ ءَاتَتۡ أُكُلَهَا وَلَمۡ تَظۡلِم مِّنۡهُ شَيۡـٔٗاۚ وَفَجَّرۡنَا خِلَٰلَهُمَا نَهَرٗا ﴿٣٣﴾ وَكَانَ لَهُۥ ثَمَرٞ فَقَالَ لِصَٰحِبِهِۦ وَهُوَ يُحَاوِرُهُۥٓ أَنَا۠ أَكۡثَرُ مِنكَ مَالٗا وَأَعَزُّ نَفَرٗا ﴿٣٤﴾ وَدَخَلَ جَنَّتَهُۥ وَهُوَ ظَالِمٞ لِّنَفۡسِهِۦ قَالَ مَآ أَظُنُّ أَن تَبِيدَ هَٰذِهِۦٓ أَبَدٗا ﴿٣٥﴾ وَمَآ أَظُنُّ ٱلسَّاعَةَ قَآئِمَةٗ وَلَئِن رُّدِدتُّ إِلَىٰ رَبِّي لَأَجِدَنَّ خَيۡرٗا مِّنۡهَا مُنقَلَبٗا ﴿٣٦﴾ قَالَ لَهُۥ صَاحِبُهُۥ وَهُوَ يُحَاوِرُهُۥٓ أَكَفَرۡتَ بِٱلَّذِي خَلَقَكَ مِن تُرَابٖ ثُمَّ مِن نُّطۡفَةٖ ثُمَّ سَوَّىٰكَ رَجُلٗا ﴿٣٧﴾ لَّـٰكِنَّا۠ هُوَ ٱللَّهُ رَبِّي وَلَآ أُشۡرِكُ بِرَبِّيٓ أَحَدٗا ﴿٣٨﴾", "w": [["واضرب لهم مثلاً", "اجعل لهم مثلاً هو رجلين."], ["جنّتين", "بستانين."], ["وحففناهما بنخل", "أحطناهما بنخل."], ["آتت أكلها", "أعطت ثمارها، وهو ما يؤكل."], ["ولم تظلم منه شيئاً", "لم تنقص منه شيئاً، بل أتت به كاملاً وافياً."], ["خلالهما نهراً", "خلال الأشجار والنخيل نهراً جارياً."], ["خيراً منها منقلباً", "مرجعاً في الآخرة."], ["أكفرت بالذي خلقك من تراب", "الاستفهام للتوبيخ، والخلق من تراب باعتبار الأصل، وهو آدم."], ["ثم سوّاك", "عدلك وصيّرك رجلاً."], ["لكنّا", "لكن أنا، حُذفت الألف وأُدغمت النون في النون."], ["هو الله ربي", "أنا أقول: الله ربي."]], "m": "اضرب لأولئك المشركين المتكبّرين الذين اقترحوا عليك طرد الفقراء المؤمنين مثلاً: رجلين، مؤمناً وكافراً، جعلنا للكافر بستانين من أعناب وأحطناهما بنخل وجعلنا بينهما زرعاً، كلتا الجنتين أعطت ثمرها كاملاً، وفجّرنا خلالهما نهراً يسقيهما، وكان له ثمر ومال، فقال لصاحبه وهو يحاوره فخراً وتعاظماً: أنا أكثر منك مالاً وأعزّ عشيرة. ودخل جنته وهو ظالم لنفسه بالكفر والكبر، قال: ما أظن أن تفنى هذه أبداً، وما أظن الساعة قائمة، ولئن رُددت إلى ربي كما تقول لأجدنّ خيراً من جنتي مرجعاً، وهذا هو الغرور النفسي الذي يصاب به أهل الشرك والكبر. قال له صاحبه المسلم موبّخاً: أكفرت بالذي خلق أباك آدم من تراب، ثم خلقك من نطفة، ثم عدّلك رجلاً؟ لكن أنا أقول: هو الله ربي، ولا أشرك بربي أحداً من خلقه في عبادته.", "h": ["استحسان ضرب الأمثال للوصول بالمعاني الخفية إلى الأذهان.", "بيان صورة مثالية لغرس بساتين النخل والكروم.", "تقرير عقيدة التوحيد والبعث والجزاء.", "التنديد بالكبر والغرور، حيث يفضيان بصاحبهما إلى الشرك والكفر."], "k": "«ما أظن أن تبيد هذه أبداً»… ما الذي أطمئن إليه كأنه لا يزول؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (201, 18, 39, 46, 'سورة الكهف ٣٩ – ٤٦', '«ولولا إذ دخلت جنتك قلت ما شاء الله لا قوة إلا بالله»، ومثل الحياة الدنيا، و«والباقيات الصالحات خير»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 201) = $j$[{"lbl": "الآيات ٣٩ – ٤٤", "q": "وَلَوۡلَآ إِذۡ دَخَلۡتَ جَنَّتَكَ قُلۡتَ مَا شَآءَ ٱللَّهُ لَا قُوَّةَ إِلَّا بِٱللَّهِۚ إِن تَرَنِ أَنَا۠ أَقَلَّ مِنكَ مَالٗا وَوَلَدٗا ﴿٣٩﴾ فَعَسَىٰ رَبِّيٓ أَن يُؤۡتِيَنِ خَيۡرٗا مِّن جَنَّتِكَ وَيُرۡسِلَ عَلَيۡهَا حُسۡبَانٗا مِّنَ ٱلسَّمَآءِ فَتُصۡبِحَ صَعِيدٗا زَلَقًا ﴿٤٠﴾ أَوۡ يُصۡبِحَ مَآؤُهَا غَوۡرٗا فَلَن تَسۡتَطِيعَ لَهُۥ طَلَبٗا ﴿٤١﴾ وَأُحِيطَ بِثَمَرِهِۦ فَأَصۡبَحَ يُقَلِّبُ كَفَّيۡهِ عَلَىٰ مَآ أَنفَقَ فِيهَا وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا وَيَقُولُ يَٰلَيۡتَنِي لَمۡ أُشۡرِكۡ بِرَبِّيٓ أَحَدٗا ﴿٤٢﴾ وَلَمۡ تَكُن لَّهُۥ فِئَةٞ يَنصُرُونَهُۥ مِن دُونِ ٱللَّهِ وَمَا كَانَ مُنتَصِرًا ﴿٤٣﴾ هُنَالِكَ ٱلۡوَلَٰيَةُ لِلَّهِ ٱلۡحَقِّۚ هُوَ خَيۡرٞ ثَوَابٗا وَخَيۡرٌ عُقۡبٗا ﴿٤٤﴾", "w": [["ما شاء الله", "ما شاء الله كان، وما لم يشأ لم يكن."], ["حسباناً من السماء", "عذاباً تُرمى به."], ["صعيداً زلقاً", "أرضاً ملساء لا يثبت عليها قدم."], ["أو يصبح ماؤها غوراً", "غائراً في أعماق الأرض فلا يقدر على استنباطه."], ["وأحيط بثمره", "هلكت ثماره فلم يبق منها شيء."], ["يقلّب كفّيه", "ندماً وحسرة على ما أنفق فيها من جهد كبير ومال طائل."], ["وهي خاوية على عروشها", "ساقطة على أعمدتها التي كان يُعرّش بها للكرم."], ["فئة", "جماعة من الناس قوية كعشيرته من قومه."], ["هنالك", "حين حلّ العذاب بصاحب الجنتين، أي يوم القيامة."], ["الولاية", "الملك والسلطان الحق لله تعالى."], ["خير ثواباً وخير عقباً", "الله خير من يثيب، وخير من يُعقب أي يجزي بخير."]], "m": "ما زال السياق في المثل المضروب للمؤمن الفقير والكافر الغني: قال المؤمن للكافر نصحاً وتوبيخاً: هلّا إذ دخلت بستانك قلت عند تعجّبك من حسنه: ما شاء الله، لا قوة إلا بالله، أي لا قوة لأحد على فعل شيء أو تركه إلا بإقدار الله وإعانته. إن ترني أنا أقل منك مالاً وولداً، فرجائي في الله أن يؤتيني خيراً من جنتك، ويرسل عليها عذاباً من السماء فتصبح تراباً أملس لا ينبت زرعاً، أو يغور ماؤها الذي تُسقى به في أعماق الأرض فلن تقدر على استخراجه. وتحقّق رجاء المؤمن: فأُحيط ببستان الكافر فهلك بكل ما فيه، فأصبح يقلّب كفيه ندماً وتحسّراً على ما أنفق فيها، وهي ساقطة على أعمدة الكرم، وهو يقول: يا ليتني لم أشرك بربي أحداً، ولم تكن له جماعة قوية تنصره من دون الله، وما كان منتصراً، لأن من خذله الله لا ناصر له. هنالك، يوم القيامة، القوة والملك والسلطان لله الحق، لا لغيره من الأصنام، هو خير من يثيب على الإيمان والعمل الصالح، وخير من يجزي بحسن العواقب.", "h": ["بيان مآل المؤمنين كصهيب وسلمان وبلال، وهو الجنة، ومآل الكافرين كأبي جهل وعقبة بن أبي معيط، وهو النار.", "استحباب قول من أعجبه شيء: «ما شاء الله لا قوة إلا بالله»، فإنه لا يرى فيه مكروهاً.", "استجابة الله تعالى لعباده المؤمنين، وتحقيق رجائهم فيه سبحانه وتعالى.", "المخذول من خذله الله تعالى، فإنه لا ينصر أبداً.", "الولاية بمعنى الموالاة النافعة للعبد هي موالاة الله تعالى، لا موالاة غيره.", "الولاية بمعنى الملك والسلطان لله يوم القيامة ليست لغيره، إذ الملك والأمر كلاهما لله."], "k": "«ما شاء الله لا قوة إلا بالله»… كلما أعجبني ما عندي، هل أنسبه إلى الله بلساني وقلبي؟"}, {"lbl": "الآيتان ٤٥ – ٤٦", "q": "وَٱضۡرِبۡ لَهُم مَّثَلَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ فَٱخۡتَلَطَ بِهِۦ نَبَاتُ ٱلۡأَرۡضِ فَأَصۡبَحَ هَشِيمٗا تَذۡرُوهُ ٱلرِّيَٰحُۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ مُّقۡتَدِرًا ﴿٤٥﴾ ٱلۡمَالُ وَٱلۡبَنُونَ زِينَةُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَٱلۡبَٰقِيَٰتُ ٱلصَّـٰلِحَٰتُ خَيۡرٌ عِندَ رَبِّكَ ثَوَابٗا وَخَيۡرٌ أَمَلٗا ﴿٤٦﴾", "w": [["كماء أنزلناه", "كماء المطر أنزلناه من السماء."], ["هشيماً", "يابساً متكسّراً."], ["تذروه الرياح", "تنثره الرياح وتفرّقه لخفّته ويبوسته."], ["مقتدراً", "كامل القدرة لا يعجزه شيء."], ["زينة الحياة الدنيا", "يُتجمّل بها فيها."], ["والباقيات الصالحات", "الأعمال الصالحة من سائر العبادات والقربات."], ["وخير أملاً", "ما يأمله الإنسان وينتظره من الخير."]], "m": "هذا مثل آخر للحياة الدنيا التي اغترّ بها الناس فصرفتهم عن ربهم فلم يذكروه ولم يشكروه: اضرب لأولئك المغرورين بالمال والسلطان صفة الحياة الدنيا الحقيقية: كماء أنزلناه من السماء فاختلط به نبات الأرض، فنما وازدهر واخضرّ، فأعجب أهله وأفرحهم، وفجأة أتاه أمر الله برياح جافّة محرقة، فأصبح يابساً متكسّراً تنثره الرياح هنا وهناك، وكان الله على كل شيء مقتدراً، فأصبح أهل الدنيا آيسين من كل خير. ثم علّم عباده حقيقة أخرى: المال والبنون زينة الحياة الدنيا لا غير، يُتجمّل بهما ساعة ثم يذهبان، فلا يجوز الاغترار بهما بحيث يصبحان همّ الإنسان فيصرفانه عن طلب الآخرة. والباقيات الصالحات، أفعال البر وضروب العبادات، ومنها: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، خير جزاءً مما يجنيه العبد من الكدح في طلب الدنيا مع الإعراض عن الآخرة، وخير ما يأمله الإنسان ويرجوه.", "h": ["بيان حقارة الدنيا وسوء عاقبتها.", "تقرير أن المال والبنين لا يعدوان كونهما زينة، والزينة سريعة الزوال، فلا يجوز الاغترار بهما، وعلى العبد أن يطلب ما يبقى على ما يفنى، وهو الباقيات الصالحات من أنواع البر والعبادات، من صلاة وذكر وتسبيح وجهاد ورباط وصيام وزكاة."], "k": "«والباقيات الصالحات خير عند ربك ثواباً»… سبحان الله والحمد لله ولا إله إلا الله والله أكبر؛ كم منها أدّخر اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 201;
