insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (202, 18, 47, 59, 'سورة الكهف ٤٧ – ٥٩', '«ووُضع الكتاب… ووجدوا ما عملوا حاضراً»، و«أفتتخذونه وذريته أولياء من دوني وهم لكم عدو»، و«وكان الإنسان أكثر شيء جدلاً»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 202) = $j$[{"lbl": "الآيات ٤٧ – ٤٩", "q": "وَيَوۡمَ نُسَيِّرُ ٱلۡجِبَالَ وَتَرَى ٱلۡأَرۡضَ بَارِزَةٗ وَحَشَرۡنَٰهُمۡ فَلَمۡ نُغَادِرۡ مِنۡهُمۡ أَحَدٗا ﴿٤٧﴾ وَعُرِضُواْ عَلَىٰ رَبِّكَ صَفّٗا لَّقَدۡ جِئۡتُمُونَا كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةِۭۚ بَلۡ زَعَمۡتُمۡ أَلَّن نَّجۡعَلَ لَكُم مَّوۡعِدٗا ﴿٤٨﴾ وَوُضِعَ ٱلۡكِتَٰبُ فَتَرَى ٱلۡمُجۡرِمِينَ مُشۡفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَٰوَيۡلَتَنَا مَالِ هَٰذَا ٱلۡكِتَٰبِ لَا يُغَادِرُ صَغِيرَةٗ وَلَا كَبِيرَةً إِلَّآ أَحۡصَىٰهَاۚ وَوَجَدُواْ مَا عَمِلُواْ حَاضِرٗاۗ وَلَا يَظۡلِمُ رَبُّكَ أَحَدٗا ﴿٤٩﴾", "w": [["نسيّر الجبال", "تُقتلع من أصولها وتصير هباءً منبثاً."], ["بارزة", "ظاهرة، إذ فني كل ما كان عليها من عمران."], ["فلم نغادر", "لم نترك منهم أحداً."], ["موعداً", "ميعاداً لبعثكم أحياء للحساب والجزاء."], ["مشفقين", "خائفين."], ["يا ويلتنا", "يا هلكتنا احضري، هذا أوان حضورك."], ["لا يغادر صغيرة", "لا يترك صغيرة من ذنوبنا ولا كبيرة إلا جمعها عدّاً."], ["ما عملوا حاضراً", "مثبتاً في كتابهم مسجّلاً فيه."]], "m": "لما ذكر مآل الدنيا إلى الفناء ورغّب في الصالحات، ناسب ذكر نبذة عن يوم القيامة: اذكر يوم تُقتلع الجبال من أصولها وتصير هباءً، وترى الأرض ظاهرة ليس عليها شيء، وجمعناهم من قبورهم للموقف فلم نترك منهم أحداً، وعُرضوا على ربك صفاً وقوفاً أذلّاء، وقيل لهم توبيخاً: لقد جئتمونا كما خلقناكم أول مرة، لا مال معكم ولا سلطان، حفاة عراة غرلاً، بل ادّعيتم كذباً أنا لن نجعل لكم موعداً، فها أنتم مجموعون تنتظرون الحساب. ووُضع كتاب الحسنات والسيئات، فأخذ المؤمن كتابه بيمينه والكافر بشماله، فترى المجرمين خائفين مما فيه من السيئات، ويقولون ندماً وتحسّراً: يا ويلتنا، ما لهذا الكتاب لا يترك صغيرة ولا كبيرة من ذنوبنا إلا أحصاها! ووجدوا ما عملوا من خير وشر مثبتاً في كتابهم، وحوسبوا به، ولا يظلم ربك أحداً بزيادة سيئة أو نقص حسنة.", "h": ["تقرير عقيدة البعث والجزاء بعرضها على مسامع المنكرين لها.", "يُبعث الإنسان كما خلقه الله، ليس معه شيء، حافياً عارياً لم تُقطع منه غلفة الذكر.", "تقرير عقيدة كتب الأعمال في الدنيا وإعطائها أصحابها في الآخرة تحقيقاً للعدالة الإلهية.", "نفي الظلم عن الله تعالى، وهو غير جائز عليه لغناه المطلق وعدم حاجته إلى شيء."], "k": "«ووجدوا ما عملوا حاضراً»… ما الذي أحب أن أجده حاضراً في كتابي؟ فلأعمله اليوم."}, {"lbl": "الآيات ٥٠ – ٥٣", "q": "وَإِذۡ قُلۡنَا لِلۡمَلَـٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ كَانَ مِنَ ٱلۡجِنِّ فَفَسَقَ عَنۡ أَمۡرِ رَبِّهِۦٓۗ أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوۡلِيَآءَ مِن دُونِي وَهُمۡ لَكُمۡ عَدُوُّۢۚ بِئۡسَ لِلظَّـٰلِمِينَ بَدَلٗا ﴿٥٠﴾ ۞مَّآ أَشۡهَدتُّهُمۡ خَلۡقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَا خَلۡقَ أَنفُسِهِمۡ وَمَا كُنتُ مُتَّخِذَ ٱلۡمُضِلِّينَ عَضُدٗا ﴿٥١﴾ وَيَوۡمَ يَقُولُ نَادُواْ شُرَكَآءِيَ ٱلَّذِينَ زَعَمۡتُمۡ فَدَعَوۡهُمۡ فَلَمۡ يَسۡتَجِيبُواْ لَهُمۡ وَجَعَلۡنَا بَيۡنَهُم مَّوۡبِقٗا ﴿٥٢﴾ وَرَءَا ٱلۡمُجۡرِمُونَ ٱلنَّارَ فَظَنُّوٓاْ أَنَّهُم مُّوَاقِعُوهَا وَلَمۡ يَجِدُواْ عَنۡهَا مَصۡرِفٗا ﴿٥٣﴾", "w": [["اسجدوا لآدم", "حيّوه بالسجود له كما أمرتكم، طاعة لي."], ["إلا إبليس", "الشيطان أبى السجود ورفضه."], ["ففسق عن أمر ربه", "خرج عن طاعته، ولم يكن من الملائكة بل كان من الجن."], ["أفتتخذونه وذريته أولياء", "الاستفهام للاستنكار، ينكر تعالى على بني آدم اتخاذ الشيطان وأولاده أولياء يُطاعون ويوالون، وهم لهم عدو."], ["بئس للظالمين بدلاً", "قبح بدلاً طاعة إبليس وذريته عن طاعة الله ورسوله."], ["المضلّين عضداً", "ما كنت متخذ الشياطين من الإنس والجن أعواناً في الخلق والتدبير."], ["موبقاً", "حاجزاً بين المشركين وما كانوا يعبدون، أو وادياً من أودية جهنم يهلكون فيه."], ["مواقعوها", "واقعون فيها لا يخرجون منها أبداً."], ["ولم يجدوا عنها مصرفاً", "مكاناً غيرها ينصرفون إليه لينجوا من عذابها."]], "m": "ما زال السياق في إرشاد بني آدم إلى ما ينجيهم: اذكر لهم إذ قلنا للملائكة اسجدوا لآدم فسجدوا، إلا إبليس، الذي يطيعه الناس اليوم، كان من الجن لا من الملائكة، فخرج عن طاعة ربه. أفيصح منكم يا بني آدم أن تتخذوا عدوّ أبيكم وعدوّ ربكم وعدوّكم وذريته أولياء تطيعونهم فيما يطلبون من الكفر والفسق؟ بئس للظالمين بدلاً طاعة الشيطان عن طاعة الله ورسوله. ما أشهدتهم خلق السماوات والأرض ولا خلق أنفسهم، فأنا المنفرد بالخلق والتدبير، وما كنت متخذ المضلّين أعواناً، فكيف يُعبد الشيطان وأنا خالقه وخالق عابديه؟ واذكر يوم يقال لهم في عرصات القيامة: نادوا شركائي الذين زعمتم أنهم يشفعون لكم، فدعوهم: يا فلان، يا فلان، فلم يستجيبوا لهم، إذ لا يجرؤ أحد ممن عُبد من دون الله أن يقول: رب هؤلاء كانوا يعبدونني، وجعلنا بينهم حاجزاً. ورأى المجرمون النار يؤتى بها تُجرّ بالسلاسل فأيقنوا أنهم داخلون فيها، ولم يجدوا عنها مكاناً ينصرفون إليه لأنهم محاطون بالزبانية.", "h": ["تقرير عداوة إبليس وذريته لبني آدم.", "العجب من بني آدم كيف يطيعون عدوهم ويعصون ربهم!", "لا يستحق العبادة أحد سوى الله عز وجل، لأنه الخالق لكل معبود.", "بيان خزي المشركين يوم القيامة، حيث يُطلب إليهم أن يدعوا شركاءهم لإغاثتهم فيدعونهم فلا يستجيبون لهم.", "جمع الله تعالى المشركين وما كانوا يعبدون من الشياطين في موبق واحد في جهنم، وهو وادٍ من شر أودية جهنم وأسوئها."], "k": "«أفتتخذونه وذريته أولياء من دوني وهم لكم عدو»… في أي أمر أطيع عدوي وأنا أعرف عداوته؟"}, {"lbl": "الآيات ٥٤ – ٥٩", "q": "وَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِلنَّاسِ مِن كُلِّ مَثَلٖۚ وَكَانَ ٱلۡإِنسَٰنُ أَكۡثَرَ شَيۡءٖ جَدَلٗا ﴿٥٤﴾ وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤۡمِنُوٓاْ إِذۡ جَآءَهُمُ ٱلۡهُدَىٰ وَيَسۡتَغۡفِرُواْ رَبَّهُمۡ إِلَّآ أَن تَأۡتِيَهُمۡ سُنَّةُ ٱلۡأَوَّلِينَ أَوۡ يَأۡتِيَهُمُ ٱلۡعَذَابُ قُبُلٗا ﴿٥٥﴾ وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۚ وَيُجَٰدِلُ ٱلَّذِينَ كَفَرُواْ بِٱلۡبَٰطِلِ لِيُدۡحِضُواْ بِهِ ٱلۡحَقَّۖ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَمَآ أُنذِرُواْ هُزُوٗا ﴿٥٦﴾ وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعۡرَضَ عَنۡهَا وَنَسِيَ مَا قَدَّمَتۡ يَدَاهُۚ إِنَّا جَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۖ وَإِن تَدۡعُهُمۡ إِلَى ٱلۡهُدَىٰ فَلَن يَهۡتَدُوٓاْ إِذًا أَبَدٗا ﴿٥٧﴾ وَرَبُّكَ ٱلۡغَفُورُ ذُو ٱلرَّحۡمَةِۖ لَوۡ يُؤَاخِذُهُم بِمَا كَسَبُواْ لَعَجَّلَ لَهُمُ ٱلۡعَذَابَۚ بَل لَّهُم مَّوۡعِدٞ لَّن يَجِدُواْ مِن دُونِهِۦ مَوۡئِلٗا ﴿٥٨﴾ وَتِلۡكَ ٱلۡقُرَىٰٓ أَهۡلَكۡنَٰهُمۡ لَمَّا ظَلَمُواْ وَجَعَلۡنَا لِمَهۡلِكِهِم مَّوۡعِدٗا ﴿٥٩﴾", "w": [["صرّفنا", "بيّنا وكرّرنا البيان."], ["من كل مثل", "المثل: الصفة المستغربة العجيبة."], ["سنّة الأولين", "العذاب بالإبادة الشاملة والاستئصال التام."], ["قُبُلاً", "مقابلة ومعاينة."], ["ليدحضوا به الحق", "ليبطلوا به الحق."], ["هزواً", "مهزوءاً به."], ["وفي آذانهم وقراً", "ثقلاً فهم لا يسمعون."], ["موئلاً", "مكاناً يلجئون إليه."], ["لمهلكهم موعداً", "وقتاً معيّناً لإهلاكهم."]], "m": "ما زال السياق في بيان حجج الله على عباده ليؤمنوا: ولقد ضربنا في هذا القرآن الأمثال الكثيرة، وبيّنا فيه الحجج، وصرّفنا فيه الوعد والوعيد، فقابلوه بالجحود، وكان الإنسان أكثر شيء جدلاً، يصرف أكثر همّه في الجدل والخصومة حتى لا يذعن للحق. وما منع الناس أن يؤمنوا إذ جاءهم الهدى، ويستغفروا ربهم، إلا أن تأتيهم سنّة الأولين بعذاب الاستئصال، أو يأتيهم عذاب يوم القيامة معاينة، وحينئذ لا ينفع الإيمان. وما نرسل المرسلين إلا مبشّرين بالجنة لمن آمن وعمل صالحاً، ومنذرين بالنار لمن كفر، فلم نرسلهم جبّارين، ويجادل الذين كفروا بالباطل ليبطلوا به الحق، واتخذوا آياتي وما أُنذروا به سخرية. ومن أظلم ممن ذُكّر بآيات ربه فأعرض عنها ونسي ما قدّمت يداه من الإجرام والشرك؟ ومن سنّته فيمن توغّل في الشر أن يجعل على قلبه غطاءً فلا يفقه، وفي أذنيه ثقلاً فلا يسمع الهدى، فإن تدعهم إلى الهدى فلن يهتدوا إذاً أبداً. وربك الغفور ذو الرحمة لو يؤاخذهم بما كسبوا لعجّل لهم العذاب، ولكن لهم موعد لن يجدوا من دونه ملجأً، ويرجح أنه يوم بدر، لأن السياق في الظلمة المعاندين كأبي جهل وعقبة بن أبي معيط. وتلك القرى من قوم هود وصالح ولوط أهلكناهم لما ظلموا، وجعلنا لهلاكهم موعداً محدّداً، فكذلك مجرمو قريش، وقد أهلكهم ببدر.", "h": ["لقد أعذر الله تعالى إلى الناس بما بيّن في كتابه من الحجج وما ضرب فيه من الأمثال.", "بيان غريزة الجدل في الإنسان والمخاصمة.", "بيان مهمة الرسل، وهي البشارة والنذارة، وليست إكراه الناس على الإيمان.", "بيان عظم ظلم من يُذكَّر بالقرآن فيعرض ويواصل جرائمه ناسياً ما قدّمت يداه.", "بيان سنة الله في أن العبد إذا واصل الشر والفساد يُحجب عن الإيمان والخير ويُحرم الهداية أبداً، حتى يهلك كافراً ظالماً فيخلد في العذاب المهين."], "k": "«ومن أظلم ممن ذُكّر بآيات ربه فأعرض عنها ونسي ما قدّمت يداه»… آية ذُكّرت بها اليوم، هل وقفت عندها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 202;
insert into public.tdb_cards(topic, i, body) select 202, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٤٧ – ٤٩", "q": "وَيَوۡمَ نُسَيِّرُ ٱلۡجِبَالَ وَتَرَى ٱلۡأَرۡضَ بَارِزَةٗ وَحَشَرۡنَٰهُمۡ فَلَمۡ نُغَادِرۡ مِنۡهُمۡ أَحَدٗا ﴿٤٧﴾ وَعُرِضُواْ عَلَىٰ رَبِّكَ صَفّٗا لَّقَدۡ جِئۡتُمُونَا كَمَا خَلَقۡنَٰكُمۡ أَوَّلَ مَرَّةِۭۚ بَلۡ زَعَمۡتُمۡ أَلَّن نَّجۡعَلَ لَكُم مَّوۡعِدٗا ﴿٤٨﴾ وَوُضِعَ ٱلۡكِتَٰبُ فَتَرَى ٱلۡمُجۡرِمِينَ مُشۡفِقِينَ مِمَّا فِيهِ وَيَقُولُونَ يَٰوَيۡلَتَنَا مَالِ هَٰذَا ٱلۡكِتَٰبِ لَا يُغَادِرُ صَغِيرَةٗ وَلَا كَبِيرَةً إِلَّآ أَحۡصَىٰهَاۚ وَوَجَدُواْ مَا عَمِلُواْ حَاضِرٗاۗ وَلَا يَظۡلِمُ رَبُّكَ أَحَدٗا ﴿٤٩﴾", "w": [["نسيّر الجبال", "تُقتلع من أصولها وتصير هباءً منبثاً."], ["بارزة", "ظاهرة، إذ فني كل ما كان عليها من عمران."], ["فلم نغادر", "لم نترك منهم أحداً."], ["موعداً", "ميعاداً لبعثكم أحياء للحساب والجزاء."], ["مشفقين", "خائفين."], ["يا ويلتنا", "يا هلكتنا احضري، هذا أوان حضورك."], ["لا يغادر صغيرة", "لا يترك صغيرة من ذنوبنا ولا كبيرة إلا جمعها عدّاً."], ["ما عملوا حاضراً", "مثبتاً في كتابهم مسجّلاً فيه."]], "m": "لما ذكر مآل الدنيا إلى الفناء ورغّب في الصالحات، ناسب ذكر نبذة عن يوم القيامة: اذكر يوم تُقتلع الجبال من أصولها وتصير هباءً، وترى الأرض ظاهرة ليس عليها شيء، وجمعناهم من قبورهم للموقف فلم نترك منهم أحداً، وعُرضوا على ربك صفاً وقوفاً أذلّاء، وقيل لهم توبيخاً: لقد جئتمونا كما خلقناكم أول مرة، لا مال معكم ولا سلطان، حفاة عراة غرلاً، بل ادّعيتم كذباً أنا لن نجعل لكم موعداً، فها أنتم مجموعون تنتظرون الحساب. ووُضع كتاب الحسنات والسيئات، فأخذ المؤمن كتابه بيمينه والكافر بشماله، فترى المجرمين خائفين مما فيه من السيئات، ويقولون ندماً وتحسّراً: يا ويلتنا، ما لهذا الكتاب لا يترك صغيرة ولا كبيرة من ذنوبنا إلا أحصاها! ووجدوا ما عملوا من خير وشر مثبتاً في كتابهم، وحوسبوا به، ولا يظلم ربك أحداً بزيادة سيئة أو نقص حسنة.", "h": ["تقرير عقيدة البعث والجزاء بعرضها على مسامع المنكرين لها.", "يُبعث الإنسان كما خلقه الله، ليس معه شيء، حافياً عارياً لم تُقطع منه غلفة الذكر.", "تقرير عقيدة كتب الأعمال في الدنيا وإعطائها أصحابها في الآخرة تحقيقاً للعدالة الإلهية.", "نفي الظلم عن الله تعالى، وهو غير جائز عليه لغناه المطلق وعدم حاجته إلى شيء."], "k": "«ووجدوا ما عملوا حاضراً»… ما الذي أحب أن أجده حاضراً في كتابي؟ فلأعمله اليوم."}, {"lbl": "الآيات ٥٠ – ٥٣", "q": "وَإِذۡ قُلۡنَا لِلۡمَلَـٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ كَانَ مِنَ ٱلۡجِنِّ فَفَسَقَ عَنۡ أَمۡرِ رَبِّهِۦٓۗ أَفَتَتَّخِذُونَهُۥ وَذُرِّيَّتَهُۥٓ أَوۡلِيَآءَ مِن دُونِي وَهُمۡ لَكُمۡ عَدُوُّۢۚ بِئۡسَ لِلظَّـٰلِمِينَ بَدَلٗا ﴿٥٠﴾ ۞مَّآ أَشۡهَدتُّهُمۡ خَلۡقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَا خَلۡقَ أَنفُسِهِمۡ وَمَا كُنتُ مُتَّخِذَ ٱلۡمُضِلِّينَ عَضُدٗا ﴿٥١﴾ وَيَوۡمَ يَقُولُ نَادُواْ شُرَكَآءِيَ ٱلَّذِينَ زَعَمۡتُمۡ فَدَعَوۡهُمۡ فَلَمۡ يَسۡتَجِيبُواْ لَهُمۡ وَجَعَلۡنَا بَيۡنَهُم مَّوۡبِقٗا ﴿٥٢﴾ وَرَءَا ٱلۡمُجۡرِمُونَ ٱلنَّارَ فَظَنُّوٓاْ أَنَّهُم مُّوَاقِعُوهَا وَلَمۡ يَجِدُواْ عَنۡهَا مَصۡرِفٗا ﴿٥٣﴾", "w": [["اسجدوا لآدم", "حيّوه بالسجود له كما أمرتكم، طاعة لي."], ["إلا إبليس", "الشيطان أبى السجود ورفضه."], ["ففسق عن أمر ربه", "خرج عن طاعته، ولم يكن من الملائكة بل كان من الجن."], ["أفتتخذونه وذريته أولياء", "الاستفهام للاستنكار، ينكر تعالى على بني آدم اتخاذ الشيطان وأولاده أولياء يُطاعون ويوالون، وهم لهم عدو."], ["بئس للظالمين بدلاً", "قبح بدلاً طاعة إبليس وذريته عن طاعة الله ورسوله."], ["المضلّين عضداً", "ما كنت متخذ الشياطين من الإنس والجن أعواناً في الخلق والتدبير."], ["موبقاً", "حاجزاً بين المشركين وما كانوا يعبدون، أو وادياً من أودية جهنم يهلكون فيه."], ["مواقعوها", "واقعون فيها لا يخرجون منها أبداً."], ["ولم يجدوا عنها مصرفاً", "مكاناً غيرها ينصرفون إليه لينجوا من عذابها."]], "m": "ما زال السياق في إرشاد بني آدم إلى ما ينجيهم: اذكر لهم إذ قلنا للملائكة اسجدوا لآدم فسجدوا، إلا إبليس، الذي يطيعه الناس اليوم، كان من الجن لا من الملائكة، فخرج عن طاعة ربه. أفيصح منكم يا بني آدم أن تتخذوا عدوّ أبيكم وعدوّ ربكم وعدوّكم وذريته أولياء تطيعونهم فيما يطلبون من الكفر والفسق؟ بئس للظالمين بدلاً طاعة الشيطان عن طاعة الله ورسوله. ما أشهدتهم خلق السماوات والأرض ولا خلق أنفسهم، فأنا المنفرد بالخلق والتدبير، وما كنت متخذ المضلّين أعواناً، فكيف يُعبد الشيطان وأنا خالقه وخالق عابديه؟ واذكر يوم يقال لهم في عرصات القيامة: نادوا شركائي الذين زعمتم أنهم يشفعون لكم، فدعوهم: يا فلان، يا فلان، فلم يستجيبوا لهم، إذ لا يجرؤ أحد ممن عُبد من دون الله أن يقول: رب هؤلاء كانوا يعبدونني، وجعلنا بينهم حاجزاً. ورأى المجرمون النار يؤتى بها تُجرّ بالسلاسل فأيقنوا أنهم داخلون فيها، ولم يجدوا عنها مكاناً ينصرفون إليه لأنهم محاطون بالزبانية.", "h": ["تقرير عداوة إبليس وذريته لبني آدم.", "العجب من بني آدم كيف يطيعون عدوهم ويعصون ربهم!", "لا يستحق العبادة أحد سوى الله عز وجل، لأنه الخالق لكل معبود.", "بيان خزي المشركين يوم القيامة، حيث يُطلب إليهم أن يدعوا شركاءهم لإغاثتهم فيدعونهم فلا يستجيبون لهم.", "جمع الله تعالى المشركين وما كانوا يعبدون من الشياطين في موبق واحد في جهنم، وهو وادٍ من شر أودية جهنم وأسوئها."], "k": "«أفتتخذونه وذريته أولياء من دوني وهم لكم عدو»… في أي أمر أطيع عدوي وأنا أعرف عداوته؟"}, {"lbl": "الآيات ٥٤ – ٥٩", "q": "وَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِلنَّاسِ مِن كُلِّ مَثَلٖۚ وَكَانَ ٱلۡإِنسَٰنُ أَكۡثَرَ شَيۡءٖ جَدَلٗا ﴿٥٤﴾ وَمَا مَنَعَ ٱلنَّاسَ أَن يُؤۡمِنُوٓاْ إِذۡ جَآءَهُمُ ٱلۡهُدَىٰ وَيَسۡتَغۡفِرُواْ رَبَّهُمۡ إِلَّآ أَن تَأۡتِيَهُمۡ سُنَّةُ ٱلۡأَوَّلِينَ أَوۡ يَأۡتِيَهُمُ ٱلۡعَذَابُ قُبُلٗا ﴿٥٥﴾ وَمَا نُرۡسِلُ ٱلۡمُرۡسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَۚ وَيُجَٰدِلُ ٱلَّذِينَ كَفَرُواْ بِٱلۡبَٰطِلِ لِيُدۡحِضُواْ بِهِ ٱلۡحَقَّۖ وَٱتَّخَذُوٓاْ ءَايَٰتِي وَمَآ أُنذِرُواْ هُزُوٗا ﴿٥٦﴾ وَمَنۡ أَظۡلَمُ مِمَّن ذُكِّرَ بِـَٔايَٰتِ رَبِّهِۦ فَأَعۡرَضَ عَنۡهَا وَنَسِيَ مَا قَدَّمَتۡ يَدَاهُۚ إِنَّا جَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرٗاۖ وَإِن تَدۡعُهُمۡ إِلَى ٱلۡهُدَىٰ فَلَن يَهۡتَدُوٓاْ إِذًا أَبَدٗا ﴿٥٧﴾ وَرَبُّكَ ٱلۡغَفُورُ ذُو ٱلرَّحۡمَةِۖ لَوۡ يُؤَاخِذُهُم بِمَا كَسَبُواْ لَعَجَّلَ لَهُمُ ٱلۡعَذَابَۚ بَل لَّهُم مَّوۡعِدٞ لَّن يَجِدُواْ مِن دُونِهِۦ مَوۡئِلٗا ﴿٥٨﴾ وَتِلۡكَ ٱلۡقُرَىٰٓ أَهۡلَكۡنَٰهُمۡ لَمَّا ظَلَمُواْ وَجَعَلۡنَا لِمَهۡلِكِهِم مَّوۡعِدٗا ﴿٥٩﴾", "w": [["صرّفنا", "بيّنا وكرّرنا البيان."], ["من كل مثل", "المثل: الصفة المستغربة العجيبة."], ["سنّة الأولين", "العذاب بالإبادة الشاملة والاستئصال التام."], ["قُبُلاً", "مقابلة ومعاينة."], ["ليدحضوا به الحق", "ليبطلوا به الحق."], ["هزواً", "مهزوءاً به."], ["وفي آذانهم وقراً", "ثقلاً فهم لا يسمعون."], ["موئلاً", "مكاناً يلجئون إليه."], ["لمهلكهم موعداً", "وقتاً معيّناً لإهلاكهم."]], "m": "ما زال السياق في بيان حجج الله على عباده ليؤمنوا: ولقد ضربنا في هذا القرآن الأمثال الكثيرة، وبيّنا فيه الحجج، وصرّفنا فيه الوعد والوعيد، فقابلوه بالجحود، وكان الإنسان أكثر شيء جدلاً، يصرف أكثر همّه في الجدل والخصومة حتى لا يذعن للحق. وما منع الناس أن يؤمنوا إذ جاءهم الهدى، ويستغفروا ربهم، إلا أن تأتيهم سنّة الأولين بعذاب الاستئصال، أو يأتيهم عذاب يوم القيامة معاينة، وحينئذ لا ينفع الإيمان. وما نرسل المرسلين إلا مبشّرين بالجنة لمن آمن وعمل صالحاً، ومنذرين بالنار لمن كفر، فلم نرسلهم جبّارين، ويجادل الذين كفروا بالباطل ليبطلوا به الحق، واتخذوا آياتي وما أُنذروا به سخرية. ومن أظلم ممن ذُكّر بآيات ربه فأعرض عنها ونسي ما قدّمت يداه من الإجرام والشرك؟ ومن سنّته فيمن توغّل في الشر أن يجعل على قلبه غطاءً فلا يفقه، وفي أذنيه ثقلاً فلا يسمع الهدى، فإن تدعهم إلى الهدى فلن يهتدوا إذاً أبداً. وربك الغفور ذو الرحمة لو يؤاخذهم بما كسبوا لعجّل لهم العذاب، ولكن لهم موعد لن يجدوا من دونه ملجأً، ويرجح أنه يوم بدر، لأن السياق في الظلمة المعاندين كأبي جهل وعقبة بن أبي معيط. وتلك القرى من قوم هود وصالح ولوط أهلكناهم لما ظلموا، وجعلنا لهلاكهم موعداً محدّداً، فكذلك مجرمو قريش، وقد أهلكهم ببدر.", "h": ["لقد أعذر الله تعالى إلى الناس بما بيّن في كتابه من الحجج وما ضرب فيه من الأمثال.", "بيان غريزة الجدل في الإنسان والمخاصمة.", "بيان مهمة الرسل، وهي البشارة والنذارة، وليست إكراه الناس على الإيمان.", "بيان عظم ظلم من يُذكَّر بالقرآن فيعرض ويواصل جرائمه ناسياً ما قدّمت يداه.", "بيان سنة الله في أن العبد إذا واصل الشر والفساد يُحجب عن الإيمان والخير ويُحرم الهداية أبداً، حتى يهلك كافراً ظالماً فيخلد في العذاب المهين."], "k": "«ومن أظلم ممن ذُكّر بآيات ربه فأعرض عنها ونسي ما قدّمت يداه»… آية ذُكّرت بها اليوم، هل وقفت عندها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (203, 18, 60, 74, 'سورة الكهف ٦٠ – ٧٤', 'رحلة موسى ﵇ إلى مجمع البحرين في طلب العلم، و«هل أتبعك على أن تعلّمن مما عُلّمت رشداً»، وخرق السفينة وقتل الغلام', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 203) = $j$[{"lbl": "الآيات ٦٠ – ٦٩", "q": "وَإِذۡ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبۡرَحُ حَتَّىٰٓ أَبۡلُغَ مَجۡمَعَ ٱلۡبَحۡرَيۡنِ أَوۡ أَمۡضِيَ حُقُبٗا ﴿٦٠﴾ فَلَمَّا بَلَغَا مَجۡمَعَ بَيۡنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ سَرَبٗا ﴿٦١﴾ فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدۡ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبٗا ﴿٦٢﴾ قَالَ أَرَءَيۡتَ إِذۡ أَوَيۡنَآ إِلَى ٱلصَّخۡرَةِ فَإِنِّي نَسِيتُ ٱلۡحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيۡطَٰنُ أَنۡ أَذۡكُرَهُۥۚ وَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ عَجَبٗا ﴿٦٣﴾ قَالَ ذَٰلِكَ مَا كُنَّا نَبۡغِۚ فَٱرۡتَدَّا عَلَىٰٓ ءَاثَارِهِمَا قَصَصٗا ﴿٦٤﴾ فَوَجَدَا عَبۡدٗا مِّنۡ عِبَادِنَآ ءَاتَيۡنَٰهُ رَحۡمَةٗ مِّنۡ عِندِنَا وَعَلَّمۡنَٰهُ مِن لَّدُنَّا عِلۡمٗا ﴿٦٥﴾ قَالَ لَهُۥ مُوسَىٰ هَلۡ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدٗا ﴿٦٦﴾ قَالَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا ﴿٦٧﴾ وَكَيۡفَ تَصۡبِرُ عَلَىٰ مَا لَمۡ تُحِطۡ بِهِۦ خُبۡرٗا ﴿٦٨﴾ قَالَ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ صَابِرٗا وَلَآ أَعۡصِي لَكَ أَمۡرٗا ﴿٦٩﴾", "w": [["وإذ قال موسى لفتاه", "اذكر إذ قال موسى بن عمران نبي بني إسرائيل لفتاه يوشع بن نون."], ["مجمع البحرين", "حيث التقى البحران."], ["حقباً", "الحقب: الزمن، وهو ثمانون سنة، والجمع أحقاب."], ["سبيله في البحر سرباً", "طريقه في البحر طريقاً كالنفق."], ["فلما جاوزا", "المكان الذي فيه الصخرة، ومنه اتخذ الحوت طريقه في البحر."], ["في البحر عجباً", "عجباً لموسى، حيث تعجّب من إحياء الحوت واتخاذه في البحر طريقاً كالنفق."], ["قصصاً", "يتتبّعان آثار أقدامهما."], ["عبداً من عبادنا", "هو الخضر ﵇."], ["مما عُلّمت رشداً", "ما هو رشاد إلى الحق ودليل على الهدى."], ["ما لم تحط به خبراً", "علماً."], ["ولا أعصي لك أمراً", "أنتهي إلى ما تأمرني به وإن لم يكن موافقاً هواي."]], "m": "هذه قصة موسى مع الخضر ﵉، وهي تقرّر نبوة محمد ﷺ، إذ مثل هذا القصص لا يتأتى لأحد أن يقصّه ما لم يتلقّه وحياً. والقصة كما في البخاري: خطب موسى يوماً في بني إسرائيل فأجاد، فسأله رجل: هل يوجد من هو أعلم منك؟ فقال: لا، فأوحى إليه ربه: بلى، عبدنا خضر، فتاقت نفسه للقياه، فأرشده إلى مجمع البحرين، وجعل له الحوت علامة: أن يأخذ طعامه حوتاً، فإذا فقده فثَمّ عبد الله. فقال لفتاه يوشع: لا أزال سائراً حتى أبلغ مجمع البحرين، أو أمضي زمناً طويلاً حتى أظفر بهذا العبد الصالح لأتعلّم منه. فلما بلغاه واستراحا عند الصخرة خرج الحوت من المكتل وشقّ طريقه إلى البحر فانجاب عنه الماء كالطاق، ونسي الفتى أن يذكره لغلبة النوم، فلما جاوزا المكان وشعرا بالجوع قال موسى: آتنا غداءنا، لقد لقينا من سفرنا هذا تعباً. قال الفتى: أتذكر إذ أوينا إلى الصخرة؟ فإني نسيت الحوت، وما أنسانيه إلا الشيطان، واتخذ سبيله في البحر عجباً، حيي بعد موت. قال موسى: ذلك ما كنا نطلب، فرجعا يتتبّعان آثار أقدامهما، فوجدا عبداً من عبادنا آتيناه رحمة من عندنا، وعلّمناه من لدنا علماً خاصاً به. قال له موسى مستعطفاً: هل أتبعك على أن تعلّمني مما علّمك الله رشاداً يدلّني على الحق؟ قال: إنك لن تستطيع معي صبراً، لأنك سترى أموراً لا تقرّني عليها، وكيف تصبر على ما لم تحط به علماً؟ قال موسى وقد صمّم على طلب العلم مهما كلّفه: ستجدني إن شاء الله صابراً، ولا أعصي لك أمراً.", "h": ["عتب الله تعالى على رسوله موسى ﵇ عندما سُئل: هل هناك من هو أعلم منك؟ فقال: لا، وكان المفروض أن يقول على الأقل: الله أعلم، فكُلّف هذه الرحلة الشاقة.", "استحباب الرفقة في السفر، وخدمة التلميذ للشيخ، إذ كان يوشع يخدم موسى بحمل الزاد.", "طروء النسيان على الإنسان مهما كان صالحاً.", "مراجعة الصواب بعد الخطأ خير من التمادي على الخطأ: «فارتدّا على آثارهما قصصاً».", "تجلّي قدرة الله تعالى في إحياء الحوت بعد الموت، وانجياب الماء عنه حتى كان كالطاق، فكان للحوت سرباً، ولموسى وفتاه عجباً، وبه استدلّ موسى على مكان الخضر.", "استحباب طلب المزيد من العلم مهما كان المرء عالماً، وعن ابن عباس قال: سأل موسى ربه: أي رب، أي عبادك أحب إليك؟ قال: الذي يذكرني ولا ينساني، قال: فأي عبادك أقضى؟ قال: الذي يقضي بالحق ولا يتبع الهوى، قال: أي رب، أي عبادك أعلم؟ قال: الذي يبتغي علم الناس إلى علم نفسه، عسى أن يصيب كلمة تهديه إلى هدى أو تردّه عن ردى."], "k": "«هل أتبعك على أن تعلّمن مما عُلّمت رشداً»… نبيّ كليم يرحل ليتعلّم؛ فما العلم الذي أرحل إليه أنا؟"}, {"lbl": "الآيات ٧٠ – ٧٤", "q": "قَالَ فَإِنِ ٱتَّبَعۡتَنِي فَلَا تَسۡـَٔلۡنِي عَن شَيۡءٍ حَتَّىٰٓ أُحۡدِثَ لَكَ مِنۡهُ ذِكۡرٗا ﴿٧٠﴾ فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِي ٱلسَّفِينَةِ خَرَقَهَاۖ قَالَ أَخَرَقۡتَهَا لِتُغۡرِقَ أَهۡلَهَا لَقَدۡ جِئۡتَ شَيۡـًٔا إِمۡرٗا ﴿٧١﴾ قَالَ أَلَمۡ أَقُلۡ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا ﴿٧٢﴾ قَالَ لَا تُؤَاخِذۡنِي بِمَا نَسِيتُ وَلَا تُرۡهِقۡنِي مِنۡ أَمۡرِي عُسۡرٗا ﴿٧٣﴾ فَٱنطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَٰمٗا فَقَتَلَهُۥ قَالَ أَقَتَلۡتَ نَفۡسٗا زَكِيَّةَۢ بِغَيۡرِ نَفۡسٖ لَّقَدۡ جِئۡتَ شَيۡـٔٗا نُّكۡرٗا ﴿٧٤﴾", "w": [["ذكراً", "بياناً وتفصيلاً لما خفي عليك."], ["لقد جئت شيئاً إمراً", "فعلت شيئاً منكراً."], ["ولا ترهقني", "لا تغشني بما يعسر عليّ ولا أطيق حمله فتضيق عليّ صحبتي إياك."], ["نفساً زكية", "طاهرة لم تتلوث روحها بالذنوب."], ["بغير نفس", "بغير قصاص."], ["نكراً", "الأمر الذي تنكره الشرائع والعقول، وهو المنكر الشديد النكارة."]], "m": "ما زال السياق في الحوار بين موسى والخضر: قال الخضر: فإن اتبعتني فلا تسألني عن شيء أفعله مما لا تعرف له وجهاً شرعياً حتى أكون أنا الذي أبيّن لك حقيقته. فانطلقا حتى وصلا ميناءً، فركبا سفينة كان الخضر يعرف أصحابها فلم يأخذوا منهما أجرة، فلما توغّلت في البحر أخذ الخضر فأساً فخرقها، فجعل موسى يحشو الخرق بثوبه ويقول: أخرقتها لتغرق أهلها، وقد حملونا بلا أجر؟ لقد أتيت منكراً فظيعاً. قال: ألم أقل إنك لن تستطيع معي صبراً؟ قال: لا تؤاخذني بما نسيت، فإن الناسي لا حرج عليه، وكانت هذه من موسى نسياناً حقاً، ولا تغشني بما يعسر عليّ. فانطلقا بعد نزولهما إلى البر، فوجدا غلاماً يلعب مع الغلمان، فأخذه الخضر جانباً فقتله، فقال موسى: أقتلت نفساً طاهرة لم تذنب ولم تقتل نفساً تستوجب القصاص؟ لقد أتيت منكراً عظيماً، ولم تكن هذه نسياناً من موسى، بل عمداً، إذ لم يطق فعل منكر كهذا لا يعرف له وجهاً.", "h": ["جواز الاشتراط في الصحبة وطلب العلم وغيرهما للمصلحة الراجحة.", "جواز ركوب السفن في البحر.", "مشروعية إنكار المنكر على من علم أنه منكر.", "رفع الحرج عن الناس.", "مشروعية القصاص، وهو النفس بالنفس."], "k": "«لا تؤاخذني بما نسيت ولا ترهقني من أمري عسراً»… هل أعذر من نسي، كما أحب أن أُعذر؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 203;
insert into public.tdb_cards(topic, i, body) select 203, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٦٠ – ٦٩", "q": "وَإِذۡ قَالَ مُوسَىٰ لِفَتَىٰهُ لَآ أَبۡرَحُ حَتَّىٰٓ أَبۡلُغَ مَجۡمَعَ ٱلۡبَحۡرَيۡنِ أَوۡ أَمۡضِيَ حُقُبٗا ﴿٦٠﴾ فَلَمَّا بَلَغَا مَجۡمَعَ بَيۡنِهِمَا نَسِيَا حُوتَهُمَا فَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ سَرَبٗا ﴿٦١﴾ فَلَمَّا جَاوَزَا قَالَ لِفَتَىٰهُ ءَاتِنَا غَدَآءَنَا لَقَدۡ لَقِينَا مِن سَفَرِنَا هَٰذَا نَصَبٗا ﴿٦٢﴾ قَالَ أَرَءَيۡتَ إِذۡ أَوَيۡنَآ إِلَى ٱلصَّخۡرَةِ فَإِنِّي نَسِيتُ ٱلۡحُوتَ وَمَآ أَنسَىٰنِيهُ إِلَّا ٱلشَّيۡطَٰنُ أَنۡ أَذۡكُرَهُۥۚ وَٱتَّخَذَ سَبِيلَهُۥ فِي ٱلۡبَحۡرِ عَجَبٗا ﴿٦٣﴾ قَالَ ذَٰلِكَ مَا كُنَّا نَبۡغِۚ فَٱرۡتَدَّا عَلَىٰٓ ءَاثَارِهِمَا قَصَصٗا ﴿٦٤﴾ فَوَجَدَا عَبۡدٗا مِّنۡ عِبَادِنَآ ءَاتَيۡنَٰهُ رَحۡمَةٗ مِّنۡ عِندِنَا وَعَلَّمۡنَٰهُ مِن لَّدُنَّا عِلۡمٗا ﴿٦٥﴾ قَالَ لَهُۥ مُوسَىٰ هَلۡ أَتَّبِعُكَ عَلَىٰٓ أَن تُعَلِّمَنِ مِمَّا عُلِّمۡتَ رُشۡدٗا ﴿٦٦﴾ قَالَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا ﴿٦٧﴾ وَكَيۡفَ تَصۡبِرُ عَلَىٰ مَا لَمۡ تُحِطۡ بِهِۦ خُبۡرٗا ﴿٦٨﴾ قَالَ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ صَابِرٗا وَلَآ أَعۡصِي لَكَ أَمۡرٗا ﴿٦٩﴾", "w": [["وإذ قال موسى لفتاه", "اذكر إذ قال موسى بن عمران نبي بني إسرائيل لفتاه يوشع بن نون."], ["مجمع البحرين", "حيث التقى البحران."], ["حقباً", "الحقب: الزمن، وهو ثمانون سنة، والجمع أحقاب."], ["سبيله في البحر سرباً", "طريقه في البحر طريقاً كالنفق."], ["فلما جاوزا", "المكان الذي فيه الصخرة، ومنه اتخذ الحوت طريقه في البحر."], ["في البحر عجباً", "عجباً لموسى، حيث تعجّب من إحياء الحوت واتخاذه في البحر طريقاً كالنفق."], ["قصصاً", "يتتبّعان آثار أقدامهما."], ["عبداً من عبادنا", "هو الخضر ﵇."], ["مما عُلّمت رشداً", "ما هو رشاد إلى الحق ودليل على الهدى."], ["ما لم تحط به خبراً", "علماً."], ["ولا أعصي لك أمراً", "أنتهي إلى ما تأمرني به وإن لم يكن موافقاً هواي."]], "m": "هذه قصة موسى مع الخضر ﵉، وهي تقرّر نبوة محمد ﷺ، إذ مثل هذا القصص لا يتأتى لأحد أن يقصّه ما لم يتلقّه وحياً. والقصة كما في البخاري: خطب موسى يوماً في بني إسرائيل فأجاد، فسأله رجل: هل يوجد من هو أعلم منك؟ فقال: لا، فأوحى إليه ربه: بلى، عبدنا خضر، فتاقت نفسه للقياه، فأرشده إلى مجمع البحرين، وجعل له الحوت علامة: أن يأخذ طعامه حوتاً، فإذا فقده فثَمّ عبد الله. فقال لفتاه يوشع: لا أزال سائراً حتى أبلغ مجمع البحرين، أو أمضي زمناً طويلاً حتى أظفر بهذا العبد الصالح لأتعلّم منه. فلما بلغاه واستراحا عند الصخرة خرج الحوت من المكتل وشقّ طريقه إلى البحر فانجاب عنه الماء كالطاق، ونسي الفتى أن يذكره لغلبة النوم، فلما جاوزا المكان وشعرا بالجوع قال موسى: آتنا غداءنا، لقد لقينا من سفرنا هذا تعباً. قال الفتى: أتذكر إذ أوينا إلى الصخرة؟ فإني نسيت الحوت، وما أنسانيه إلا الشيطان، واتخذ سبيله في البحر عجباً، حيي بعد موت. قال موسى: ذلك ما كنا نطلب، فرجعا يتتبّعان آثار أقدامهما، فوجدا عبداً من عبادنا آتيناه رحمة من عندنا، وعلّمناه من لدنا علماً خاصاً به. قال له موسى مستعطفاً: هل أتبعك على أن تعلّمني مما علّمك الله رشاداً يدلّني على الحق؟ قال: إنك لن تستطيع معي صبراً، لأنك سترى أموراً لا تقرّني عليها، وكيف تصبر على ما لم تحط به علماً؟ قال موسى وقد صمّم على طلب العلم مهما كلّفه: ستجدني إن شاء الله صابراً، ولا أعصي لك أمراً.", "h": ["عتب الله تعالى على رسوله موسى ﵇ عندما سُئل: هل هناك من هو أعلم منك؟ فقال: لا، وكان المفروض أن يقول على الأقل: الله أعلم، فكُلّف هذه الرحلة الشاقة.", "استحباب الرفقة في السفر، وخدمة التلميذ للشيخ، إذ كان يوشع يخدم موسى بحمل الزاد.", "طروء النسيان على الإنسان مهما كان صالحاً.", "مراجعة الصواب بعد الخطأ خير من التمادي على الخطأ: «فارتدّا على آثارهما قصصاً».", "تجلّي قدرة الله تعالى في إحياء الحوت بعد الموت، وانجياب الماء عنه حتى كان كالطاق، فكان للحوت سرباً، ولموسى وفتاه عجباً، وبه استدلّ موسى على مكان الخضر.", "استحباب طلب المزيد من العلم مهما كان المرء عالماً، وعن ابن عباس قال: سأل موسى ربه: أي رب، أي عبادك أحب إليك؟ قال: الذي يذكرني ولا ينساني، قال: فأي عبادك أقضى؟ قال: الذي يقضي بالحق ولا يتبع الهوى، قال: أي رب، أي عبادك أعلم؟ قال: الذي يبتغي علم الناس إلى علم نفسه، عسى أن يصيب كلمة تهديه إلى هدى أو تردّه عن ردى."], "k": "«هل أتبعك على أن تعلّمن مما عُلّمت رشداً»… نبيّ كليم يرحل ليتعلّم؛ فما العلم الذي أرحل إليه أنا؟"}, {"lbl": "الآيات ٧٠ – ٧٤", "q": "قَالَ فَإِنِ ٱتَّبَعۡتَنِي فَلَا تَسۡـَٔلۡنِي عَن شَيۡءٍ حَتَّىٰٓ أُحۡدِثَ لَكَ مِنۡهُ ذِكۡرٗا ﴿٧٠﴾ فَٱنطَلَقَا حَتَّىٰٓ إِذَا رَكِبَا فِي ٱلسَّفِينَةِ خَرَقَهَاۖ قَالَ أَخَرَقۡتَهَا لِتُغۡرِقَ أَهۡلَهَا لَقَدۡ جِئۡتَ شَيۡـًٔا إِمۡرٗا ﴿٧١﴾ قَالَ أَلَمۡ أَقُلۡ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا ﴿٧٢﴾ قَالَ لَا تُؤَاخِذۡنِي بِمَا نَسِيتُ وَلَا تُرۡهِقۡنِي مِنۡ أَمۡرِي عُسۡرٗا ﴿٧٣﴾ فَٱنطَلَقَا حَتَّىٰٓ إِذَا لَقِيَا غُلَٰمٗا فَقَتَلَهُۥ قَالَ أَقَتَلۡتَ نَفۡسٗا زَكِيَّةَۢ بِغَيۡرِ نَفۡسٖ لَّقَدۡ جِئۡتَ شَيۡـٔٗا نُّكۡرٗا ﴿٧٤﴾", "w": [["ذكراً", "بياناً وتفصيلاً لما خفي عليك."], ["لقد جئت شيئاً إمراً", "فعلت شيئاً منكراً."], ["ولا ترهقني", "لا تغشني بما يعسر عليّ ولا أطيق حمله فتضيق عليّ صحبتي إياك."], ["نفساً زكية", "طاهرة لم تتلوث روحها بالذنوب."], ["بغير نفس", "بغير قصاص."], ["نكراً", "الأمر الذي تنكره الشرائع والعقول، وهو المنكر الشديد النكارة."]], "m": "ما زال السياق في الحوار بين موسى والخضر: قال الخضر: فإن اتبعتني فلا تسألني عن شيء أفعله مما لا تعرف له وجهاً شرعياً حتى أكون أنا الذي أبيّن لك حقيقته. فانطلقا حتى وصلا ميناءً، فركبا سفينة كان الخضر يعرف أصحابها فلم يأخذوا منهما أجرة، فلما توغّلت في البحر أخذ الخضر فأساً فخرقها، فجعل موسى يحشو الخرق بثوبه ويقول: أخرقتها لتغرق أهلها، وقد حملونا بلا أجر؟ لقد أتيت منكراً فظيعاً. قال: ألم أقل إنك لن تستطيع معي صبراً؟ قال: لا تؤاخذني بما نسيت، فإن الناسي لا حرج عليه، وكانت هذه من موسى نسياناً حقاً، ولا تغشني بما يعسر عليّ. فانطلقا بعد نزولهما إلى البر، فوجدا غلاماً يلعب مع الغلمان، فأخذه الخضر جانباً فقتله، فقال موسى: أقتلت نفساً طاهرة لم تذنب ولم تقتل نفساً تستوجب القصاص؟ لقد أتيت منكراً عظيماً، ولم تكن هذه نسياناً من موسى، بل عمداً، إذ لم يطق فعل منكر كهذا لا يعرف له وجهاً.", "h": ["جواز الاشتراط في الصحبة وطلب العلم وغيرهما للمصلحة الراجحة.", "جواز ركوب السفن في البحر.", "مشروعية إنكار المنكر على من علم أنه منكر.", "رفع الحرج عن الناس.", "مشروعية القصاص، وهو النفس بالنفس."], "k": "«لا تؤاخذني بما نسيت ولا ترهقني من أمري عسراً»… هل أعذر من نسي، كما أحب أن أُعذر؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;